INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12b3652c-fcf4-4109-9fa0-3318b6aa26fb', '贈佳人', '贈佳人', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["步搖金翠玉搔頭，傾國傾城勝莫愁。","若逞仙姿遊洛浦，定知神女謝風流。"]', '["步搖金翠玉搔头，傾国傾城勝莫愁。","若逞仙姿游洛浦，定知神女謝风流。"]', '诗', 'shi', '', NULL, '贈佳人 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b314252-f4df-4c66-aeb1-545a3950294d', '休暇日中書相公致齋禁省因以寄贈', '休暇日中书相公致斋禁省因以寄贈', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["嘗聞聖主得賢臣，三接能令四海春。","月滿禁垣齋沐夜，清吟屬和更何人。"]', '["嘗闻聖主得賢臣，三接能令四海春。","月满禁垣斋沐夜，清吟屬和更何人。"]', '诗', 'shi', '', NULL, '休暇日中書相公致齋禁省因以寄贈 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f088449-9e08-4505-ac55-379919d5f89d', '春興', '春兴', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["楊柳陰陰細雨晴，殘花落盡見流鶯。","春風一枝吹香夢，夢逐春風到洛城。"]', '["楊柳陰陰細雨晴，殘花落尽见流鶯。","春风一枝吹香梦，梦逐春风到洛城。"]', '诗', 'shi', '', NULL, '春興 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e021303d-f151-47aa-a459-2c7237b84037', '酬裴起居西亭留題', '酬裴起居西亭留題', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["豔歌能起關山恨，紅燭偏凝寒塞情。","況是池塘風雨夜，不堪絲管盡離聲。"]', '["豔歌能起关山恨，紅燭偏凝寒塞情。","況是池塘风雨夜，不堪絲管尽離声。"]', '诗', 'shi', '', NULL, '酬裴起居西亭留題 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('780d5e37-4d28-4b8e-bf85-416afe322d0e', '送張侍御赴京', '送張侍御赴京', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["江南煙雨塞鴻飛，西府文章謝掾歸。","相送汀州蘭棹晚，菱歌一曲淚霑衣。"]', '["江南煙雨塞鴻飞，西府文章謝掾归。","相送汀州蘭棹晚，菱歌一曲泪霑衣。"]', '诗', 'shi', '', NULL, '送張侍御赴京 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16d39ffc-d7f3-4bf3-b94a-cef47b6cf26c', '鄂渚送友', '鄂渚送友', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["雲帆淼淼巴陵渡，煙樹蒼蒼故郢城。","江上梅花無數落，送君南浦不勝情。"]', '["云帆淼淼巴陵渡，煙樹蒼蒼故郢城。","江上梅花無數落，送君南浦不勝情。"]', '诗', 'shi', '', NULL, '鄂渚送友 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e77fae8-1435-4119-abd0-a25d4091acce', '送裴戡行軍', '送裴戡行軍', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["珠履三千醉不歡，玉人猶苦夜冰寒。","送君偏有無言淚，天下關山行路難。"]', '["珠履三千醉不歡，玉人猶苦夜冰寒。","送君偏有無言泪，天下关山行路难。"]', '诗', 'shi', '', NULL, '送裴戡行軍 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab1e1eab-9dad-4171-949d-368e33f2f538', '宿青陽驛', '宿青陽驛', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["空山搖落三秋暮，螢過疎簾月露團。","寂寞銀燈愁不寐，蕭蕭風竹夜窗寒。"]', '["空山搖落三秋暮，螢過疎簾月露團。","寂寞銀灯愁不寐，蕭蕭风竹夜窗寒。"]', '诗', 'shi', '', NULL, '宿青陽驛 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be16d2f7-5775-4dbd-afab-079d1b2ce0c3', '送崔舍人起居', '送崔舍人起居', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["赤墀同拜紫泥封，駟牡連徵侍九重。","惟有白鬚張司馬，不言名利尚相從。"]', '["赤墀同拜紫泥封，駟牡連徵侍九重。","惟有白鬚張司马，不言名利尚相從。"]', '诗', 'shi', '', NULL, '送崔舍人起居 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d25b2fa-42af-4f96-877b-3df08ad3f523', '路岐重賦', '路岐重賦', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["芳郊欲別闌干淚，故國難期聚散雲。","分手更逢江驛暮，馬嘶猨叫不堪聞。"]', '["芳郊欲別闌干泪，故国难期聚散云。","分手更逢江驛暮，马嘶猨叫不堪闻。"]', '诗', 'shi', '', NULL, '路岐重賦 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('228913ce-468d-44fd-8ae2-b6b2cedd301a', '重送盧三十一起居', '重送盧三十一起居', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["相如擁傳有光輝，何事闌干淚濕衣。","舊府東山餘妓在，重將歌舞送君歸。"]', '["相如擁傳有光輝，何事闌干泪濕衣。","旧府东山餘妓在，重將歌舞送君归。"]', '诗', 'shi', '', NULL, '重送盧三十一起居 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61dfa1e6-46f8-4644-8824-89f9be332363', '送張諫議', '送張諫議', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["漢庭從事五人來，回首疆場獨未回。","今日送君魂斷處，寒雲寥落數株梅。"]', '["漢庭從事五人来，回首疆場独未回。","今日送君魂斷处，寒云寥落數株梅。"]', '诗', 'shi', '', NULL, '送張諫議 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c929045-3fd4-449c-8f6d-eb8da3b1642a', '同諸公夜讌監軍翫花之作', '同諸公夜讌監軍翫花之作', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["五侯門館百花繁，紅燭搖風白雪翻。","不似鳳皇池畔見，飄揚今隔上林園。"]', '["五侯门館百花繁，紅燭搖风白雪翻。","不似鳳皇池畔见，飄揚今隔上林园。"]', '诗', 'shi', '', NULL, '同諸公夜讌監軍翫花之作 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bc60095-c6ed-417f-9b0c-6675900cab51', '郊居寓目偶題', '郊居寓目偶題', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["晨趨禁掖暮郊園，松桂蒼蒼煙露繁。","明月上時羣動息，雪峰高處正當軒。"]', '["晨趨禁掖暮郊园，松桂蒼蒼煙露繁。","明月上时羣动息，雪峰高处正當軒。"]', '诗', 'shi', '', NULL, '郊居寓目偶題 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccefee74-c9b6-4cea-9212-23e71dc8f7d7', '題嘉陵驛', '題嘉陵驛', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["悠悠風斾繞山川，山驛空濛雨似煙。","路半嘉陵頭已白，蜀門西上更青天。"]', '["悠悠风斾繞山川，山驛空濛雨似煙。","路半嘉陵头已白，蜀门西上更青天。"]', '诗', 'shi', '', NULL, '題嘉陵驛 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f5035f5-5dc6-4915-beb3-86dc32784590', '送柳郎中裴起居', '送柳郎中裴起居', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["望鄉臺上秦人在，學射山中杜魄哀。","落日河橋千騎別，春風寂寞斾旌迴。"]', '["望乡台上秦人在，学射山中杜魄哀。","落日河橋千騎別，春风寂寞斾旌迴。"]', '诗', 'shi', '', NULL, '送柳郎中裴起居 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24c0ca77-5a28-4a38-a773-6b5d9ef9f6db', '秋日出遊偶作', '秋日出游偶作', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["黃花丹葉滿江城，暫愛江頭風景清。","閑步欲舒山野性，貔貅不許獨行人。"]', '["黄花丹葉满江城，暫愛江头风景清。","闲步欲舒山野性，貔貅不許独行人。"]', '诗', 'shi', '', NULL, '秋日出遊偶作 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a56eb8bb-1b57-4106-a3a6-34be16282ea3', '夏夜餞裴行軍赴朝命', '夏夜餞裴行軍赴朝命', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["三年同看錦城花，銀燭連宵照綺霞。","報國從來先意氣，臨岐不用重咨嗟。"]', '["三年同看錦城花，銀燭連宵照綺霞。","報国從来先意氣，臨岐不用重咨嗟。"]', '诗', 'shi', '', NULL, '夏夜餞裴行軍赴朝命 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4103b07-1372-436a-aa34-df797cda442a', '摩訶池送李侍御之鳳翔', '摩訶池送李侍御之鳳翔', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["柳暗花明池上山，高樓歌酒換離顏。","他時欲寄相思字，何處黃雲是隴間。"]', '["柳暗花明池上山，高楼歌酒換離顏。","他时欲寄相思字，何处黄云是隴间。"]', '诗', 'shi', '', NULL, '摩訶池送李侍御之鳳翔 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3aa141c1-cabe-4dc5-9031-b47077b558e8', '送魏正則擢第歸江陵', '送魏正則擢第归江陵', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["商山路接玉山深，古木蒼然盡合陰。","會府登筵君最少，江城秋至肯驚心。"]', '["商山路接玉山深，古木蒼然尽合陰。","會府登筵君最少，江城秋至肯驚心。"]', '诗', 'shi', '', NULL, '送魏正則擢第歸江陵 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e485d65-f956-4ddf-a7bd-de1ff08bf0cc', '登闔閭古城', '登闔閭古城', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["登高望遠自傷情，柳發花開映古城。","全盛已隨流水去，黃鸝空囀舊春聲。"]', '["登高望远自傷情，柳發花开映古城。","全盛已隨流水去，黄鸝空囀旧春声。"]', '诗', 'shi', '', NULL, '登闔閭古城 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de9b3ef9-0389-4a01-8808-0200895b53f6', '尋三藏上人', '尋三藏上人', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["北風吹雪暮蕭蕭，問法尋僧上界遙。","臨水手持筇竹杖，逢君不語指芭蕉。"]', '["北风吹雪暮蕭蕭，问法尋僧上界遙。","臨水手持筇竹杖，逢君不語指芭蕉。"]', '诗', 'shi', '', NULL, '尋三藏上人 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa4fc547-36e8-46ae-a781-b0fed35cdc7c', '山居', '山居', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["身依泉壑將時背，路入煙蘿得地深。","終歲不知城郭事，手栽林竹盡成陰。"]', '["身依泉壑將时背，路入煙蘿得地深。","終歲不知城郭事，手栽林竹尽成陰。"]', '诗', 'shi', '', NULL, '山居 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('179f095e-a959-4adf-8a40-355d5ae9b8f0', '長安賊中寄題江南所居茱萸樹', '长安賊中寄題江南所居茱萸樹', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["手種茱萸舊井傍，幾迴春露又秋霜。","今來獨向秦中見，攀折無時不斷腸。"]', '["手種茱萸旧井傍，幾迴春露又秋霜。","今来独向秦中见，攀折無时不斷腸。"]', '诗', 'shi', '', NULL, '長安賊中寄題江南所居茱萸樹 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c7e8d3d-9702-48fa-86a7-24e967ecd386', '春齋夜雨憶郭通微', '春斋夜雨憶郭通微', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["桃源在在阻風塵，世事悠悠又遇春。","雨滴閑堦清夜久，焚香偏憶白雲人。"]', '["桃源在在阻风塵，世事悠悠又遇春。","雨滴闲堦清夜久，焚香偏憶白云人。"]', '诗', 'shi', '', NULL, '春齋夜雨憶郭通微 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32229d8a-92c7-48ca-bf6a-6c255154d6dc', '送嚴秀才', '送嚴秀才', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["灞滻別離腸已斷，江山迢遰信仍稀。","送君偏下臨岐淚，家在南州身未歸。"]', '["灞滻別離腸已斷，江山迢遰信仍稀。","送君偏下臨岐泪，家在南州身未归。"]', '诗', 'shi', '', NULL, '送嚴秀才 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cb1c6ec-1139-46a6-a563-3d741797da80', '春日酬熊執易南亭花發見贈', '春日酬熊執易南亭花發见贈', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["千株桃杏參差發，想見花時人却愁。","曾忝陸機琴酒會，春亭惟願一淹留。"]', '["千株桃杏參差發，想见花时人却愁。","曾忝陸機琴酒會，春亭惟願一淹留。"]', '诗', 'shi', '', NULL, '春日酬熊執易南亭花發見贈 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0433d021-c243-4fb2-abbf-9ff7bf21dfe0', '中春亭雪夜寄西隣韓李二舍人', '中春亭雪夜寄西隣韓李二舍人', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["廣庭飛雪對愁人，寒谷由來不悟春。","却笑山陰乘興夜，何如今日戴家鄰。"]', '["廣庭飞雪对愁人，寒谷由来不悟春。","却笑山陰乘兴夜，何如今日戴家鄰。"]', '诗', 'shi', '', NULL, '中春亭雪夜寄西隣韓李二舍人 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f8f3438-0a72-42cb-8c01-d17f52cf096e', '立秋日與陸華原於縣界南館送鄒十八', '立秋日與陸华原於縣界南館送鄒十八', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["風入昭陽池館秋，片雲孤鶴兩難留。","明朝獨向青山郭，唯有蟬聲催白頭。"]', '["风入昭陽池館秋，片云孤鹤兩难留。","明朝独向青山郭，唯有蟬声催白头。"]', '诗', 'shi', '', NULL, '立秋日與陸華原於縣界南館送鄒十八 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f360aa48-666e-415d-a273-847e775c1176', '酬韋胄曹登天長寺上方見寄', '酬韋胄曹登天长寺上方见寄', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["青門幾度霑襟淚，併在東林雪外峰。","今日重煩相憶處，春光知繞鳳池濃。"]', '["青门幾度霑襟泪，併在东林雪外峰。","今日重煩相憶处，春光知繞鳳池濃。"]', '诗', 'shi', '', NULL, '酬韋胄曹登天長寺上方見寄 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e249f461-e5db-4406-a638-3b435663eb77', '陌上暮春', '陌上暮春', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["青青南陌柳如絲，柳色鶯聲晚日遲。","何處最傷遊客思，春風三月落花時。"]', '["青青南陌柳如絲，柳色鶯声晚日遲。","何处最傷游客思，春风三月落花时。"]', '诗', 'shi', '', NULL, '陌上暮春 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21cd5e27-2efa-47f5-8a91-767adea389f4', '春日偶作', '春日偶作', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["飛花寂寂燕雙雙，南客衡門對楚江。","惆悵管弦何處發，春風吹到讀書窗。"]', '["飞花寂寂燕雙雙，南客衡门对楚江。","惆悵管弦何处發，春风吹到读书窗。"]', '诗', 'shi', '', NULL, '春日偶作 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('713c0702-37ca-423b-af84-4867a96648c3', '春暮寄杜嘉興昆弟', '春暮寄杜嘉兴昆弟', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["柳色千家與萬家，輕風細雨落殘花。","數枝瓊玉無由見，空掩柴扉度歲華。"]', '["柳色千家與万家，轻风細雨落殘花。","數枝瓊玉無由见，空掩柴扉度歲华。"]', '诗', 'shi', '', NULL, '春暮寄杜嘉興昆弟 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf0b1a1f-1756-4089-b981-fce29447d128', '渡淮', '渡淮', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["暮濤凝雪長淮水，細雨飛梅五月天。","行子不須愁夜泊，綠楊多處有人煙。"]', '["暮濤凝雪长淮水，細雨飞梅五月天。","行子不須愁夜泊，綠楊多处有人煙。"]', '诗', 'shi', '', NULL, '渡淮 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a7238a5-6a40-493c-be9f-eaa771ab5d1e', '與崔十五同訪裴校書不遇', '與崔十五同訪裴校书不遇', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["梨花落盡柳花時，庭樹流鶯日過遲。","幾度相思不相見，春風何處有佳期。"]', '["梨花落尽柳花时，庭樹流鶯日過遲。","幾度相思不相见，春风何处有佳期。"]', '诗', 'shi', '', NULL, '與崔十五同訪裴校書不遇 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('426adf2d-8473-4abc-8705-b7e78a7096b2', '夏日寄陸三達陸四逢幷王念八仲周', '夏日寄陸三達陸四逢幷王念八仲周', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["士衡兄弟舊齊名，還似當年在洛城。","聞說重門方隱相，古槐高柳夏陰清。"]', '["士衡兄弟旧齊名，還似當年在洛城。","闻说重门方隐相，古槐高柳夏陰清。"]', '诗', 'shi', '', NULL, '夏日寄陸三達陸四逢幷王念八仲周 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab1a164e-f393-42d9-a7d4-a46d65ca3d4e', '秋原寓目', '秋原寓目', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["木落風高天宇開，秋原一望思悠哉。","邊城今少射鵰騎，連鴈嗷嗷何處來。"]', '["木落风高天宇开，秋原一望思悠哉。","邊城今少射鵰騎，連鴈嗷嗷何处来。"]', '诗', 'shi', '', NULL, '秋原寓目 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8262ad50-0a33-4ccf-a513-262bc9be6849', '贈歌人', '贈歌人', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["林鶯一哢四時春，蟬翼羅衣白玉人。","曾逐使君歌舞地，清聲長嘯翠眉顰。"]', '["林鶯一哢四时春，蟬翼羅衣白玉人。","曾逐使君歌舞地，清声长嘯翠眉顰。"]', '诗', 'shi', '', NULL, '贈歌人 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84801294-c15b-4d91-87a3-195c19b0fd6e', '同苗郎中送嚴侍御赴黔中因訪仙源之事', '同苗郎中送嚴侍御赴黔中因訪仙源之事', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["武陵源在朗江東，流水飛花仙洞中。","莫問阮郎千古事，綠楊深處翠霞空。"]', '["武陵源在朗江东，流水飞花仙洞中。","莫问阮郎千古事，綠楊深处翠霞空。"]', '诗', 'shi', '', NULL, '同苗郎中送嚴侍御赴黔中因訪仙源之事 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9d4da7d-6233-4720-8041-6fc3dcb806b9', '使次盤豆驛望永樂縣', '使次盤豆驛望永乐縣', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["山川不記何年別，城郭應非昔所經。","欲駐征車終日望，天河雲雨晦冥冥。"]', '["山川不記何年別，城郭應非昔所經。","欲駐征车終日望，天河云雨晦冥冥。"]', '诗', 'shi', '', NULL, '使次盤豆驛望永樂縣 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e30f274-4e0e-407c-856c-f2e06f5314cd', '緱山道中口號', '緱山道中口號', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["秋山寂寂秋水清，寒郊木葉飛無聲。","王子白雲仙去久，洛濱行路夜吹笙。"]', '["秋山寂寂秋水清，寒郊木葉飞無声。","王子白云仙去久，洛濱行路夜吹笙。"]', '诗', 'shi', '', NULL, '緱山道中口號 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fabac5b-0b26-4589-b7d1-2703e951ec57', '歲暮送舍人', '歲暮送舍人', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["邊城歲暮望鄉關，身逐戎旌未得還。","欲別臨岐無限淚，故園花發寄君攀。"]', '["邊城歲暮望乡关，身逐戎旌未得還。","欲別臨岐無限泪，故园花發寄君攀。"]', '诗', 'shi', '', NULL, '歲暮送舍人 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56815b0d-af85-402c-965c-34eb4b83c349', '寓興呈崔員外諸公', '寓兴呈崔員外諸公', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["三月楊花飛滿空，飄颻十里雪如風。","不知何處香醪熟，願醉佳園芳樹中。"]', '["三月楊花飞满空，飄颻十里雪如风。","不知何处香醪熟，願醉佳园芳樹中。"]', '诗', 'shi', '', NULL, '寓興呈崔員外諸公 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14d0f60f-8688-41c2-b400-273e05445960', '單于曉角', '單于晓角', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["胡兒吹角漢城頭，月皎霜寒大漠秋。","三奏未終天便曉，何人不起望鄉愁。"]', '["胡兒吹角漢城头，月皎霜寒大漠秋。","三奏未終天便晓，何人不起望乡愁。"]', '诗', 'shi', '', NULL, '單于曉角 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f1d6e6d-f175-4bf9-a497-67fcdb883b74', '汴河聞笳', '汴河闻笳', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["何處金笳月裏悲，悠悠邊客夢先知。","單于城下關山曲，今日中原總解吹。"]', '["何处金笳月裏悲，悠悠邊客梦先知。","單于城下关山曲，今日中原總解吹。"]', '诗', 'shi', '', NULL, '汴河聞笳 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cad40c5-7a28-4b23-a498-172f22ca59ef', '塞上春懷', '塞上春懷', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["東風河外五城喧，南客征袍滿淚痕。","愁至獨登高處望，藹然雲樹重傷魂。"]', '["东风河外五城喧，南客征袍满泪痕。","愁至独登高处望，藹然云樹重傷魂。"]', '诗', 'shi', '', NULL, '塞上春懷 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3af11b19-37ad-40b2-a3c6-220ce5c9661a', '塞外月夜寄荆南熊侍御', '塞外月夜寄荆南熊侍御', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["南依劉表北劉琨，征戰年年簫鼓喧。","雲雨一乖千萬里，長城秋月洞庭猨。"]', '["南依劉表北劉琨，征戰年年簫鼓喧。","云雨一乖千万里，长城秋月洞庭猨。"]', '诗', 'shi', '', NULL, '塞外月夜寄荆南熊侍御 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42966dbe-63b5-42b8-a5f9-9f357dd48fc0', '單于罷戰却歸題善陽館', '單于罷戰却归題善陽館', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["單于南去善陽關，身逐歸雲到處閑。","曾是五年蓮府客，每聞胡虜哭陰山。"]', '["單于南去善陽关，身逐归云到处闲。","曾是五年蓮府客，每闻胡虜哭陰山。"]', '诗', 'shi', '', NULL, '單于罷戰却歸題善陽館 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c26a02fa-e19c-442d-993e-810d06d3f345', '韋常侍以賓客致仕同諸公題壁', '韋常侍以賓客致仕同諸公題壁', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["孤雲永日自徘徊，巖館蒼蒼遍綠苔。","望苑忽驚新詔下，綵鸞歸處玉籠開。"]', '["孤云永日自徘徊，巖館蒼蒼遍綠苔。","望苑忽驚新詔下，綵鸾归处玉籠开。"]', '诗', 'shi', '', NULL, '韋常侍以賓客致仕同諸公題壁 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0608acf-1273-4b33-a4ef-75432cbc542f', '學仙難', '学仙难', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["玉殿笙歌漢帝愁，鸞龍儼駕望瀛洲。","黃金化盡方士死，青天欲上無緣由。"]', '["玉殿笙歌漢帝愁，鸾龙儼駕望瀛洲。","黄金化尽方士死，青天欲上無緣由。"]', '诗', 'shi', '', NULL, '學仙難 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68a0ab81-87c5-4af5-a27a-9c6032f35b21', '唐昌觀玉蘂花', '唐昌观玉蘂花', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["琪樹芊芊玉蘂新，洞宮長閉綵霞春。","日暮落英鋪地雪，獻花應過九天人。"]', '["琪樹芊芊玉蘂新，洞宮长閉綵霞春。","日暮落英鋪地雪，獻花應過九天人。"]', '诗', 'shi', '', NULL, '唐昌觀玉蘂花 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7b2cf6c-d8c3-4e6f-99e0-9fa24dc3a111', '春曉聞鶯', '春晓闻鶯', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["寥寥蘭臺曉夢驚，綠林殘月思孤鶯。","猶疑蜀魄千年恨，化作寃禽萬囀聲。"]', '["寥寥蘭台晓梦驚，綠林殘月思孤鶯。","猶疑蜀魄千年恨，化作寃禽万囀声。"]', '诗', 'shi', '', NULL, '春曉聞鶯 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d2b82b1-d43a-490c-aaca-cda5b53f87e3', '聞嚴祕書與正字及諸客夜會因寄', '闻嚴祕书與正字及諸客夜會因寄', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["衡門寥落歲陰窮，露濕莓苔葉厭風。","聞道今宵阮家會，竹林明月七人同。"]', '["衡门寥落歲陰窮，露濕莓苔葉厭风。","闻道今宵阮家會，竹林明月七人同。"]', '诗', 'shi', '', NULL, '聞嚴祕書與正字及諸客夜會因寄 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d20674e-0477-4f34-b9c0-5e0035b0de1a', '戲贈韓二秀才', '戲贈韓二秀才', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["名高折桂方年少，心苦爲文命未通。","聞說東堂今有待，飛鳴何處及春風。"]', '["名高折桂方年少，心苦爲文命未通。","闻说东堂今有待，飞鳴何处及春风。"]', '诗', 'shi', '', NULL, '戲贈韓二秀才 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d44dcb5d-8d29-4df0-8df3-7ede18b32157', '聞王仲周所居牡丹花發因戲贈', '闻王仲周所居牡丹花發因戲贈', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["聞說庭花發暮春，長安才子看須頻。","花開花落無人見，借問何人是主人。"]', '["闻说庭花發暮春，长安才子看須頻。","花开花落無人见，借问何人是主人。"]', '诗', 'shi', '', NULL, '聞王仲周所居牡丹花發因戲贈 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('396222af-6881-4647-8a15-89bc112edccf', '酬王十八見招', '酬王十八见招', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["王昌家直在城東，落盡庭花昨夜風。","高興不辭千日醉，隨君走馬向新豐。"]', '["王昌家直在城东，落尽庭花昨夜风。","高兴不辞千日醉，隨君走马向新豐。"]', '诗', 'shi', '', NULL, '酬王十八見招 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a707722-b597-4d05-ab3b-b8b417a6607a', '贈道者', '贈道者', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["麻衣如雪一枝梅，笑掩微妝入夢來。","若到越溪逢越女，紅蓮池裏白蓮開。"]', '["麻衣如雪一枝梅，笑掩微妝入梦来。","若到越溪逢越女，紅蓮池裏白蓮开。"]', '诗', 'shi', '', NULL, '贈道者 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50ec944a-86b4-4da6-9044-11805b384ebd', '重送白將軍', '重送白將軍', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["紅燭芳筵惜夜分，歌樓管咽思難聞。","早知怨別人間世，不下青山老白雲。"]', '["紅燭芳筵惜夜分，歌楼管咽思难闻。","早知怨別人间世，不下青山老白云。"]', '诗', 'shi', '', NULL, '重送白將軍 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9113a4ff-cf7f-43d4-b9e0-3afcd64ae623', '和李丞題李將軍林園', '和李丞題李將軍林园', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["落英飄蘂雪紛紛，啼鳥如悲霍冠軍。","逝水不迴弦管絕，玉樓迢遰鎖浮雲。"]', '["落英飄蘂雪紛紛，啼鸟如悲霍冠軍。","逝水不迴弦管絕，玉楼迢遰鎖浮云。"]', '诗', 'shi', '', NULL, '和李丞題李將軍林園 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dcc415e-5b0e-4fc1-9ed5-2138a36a0859', '同張惟送霍總', '同張惟送霍總', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["春風簫管怨津樓，三奏行人醉不留。","別後相思江上岸，落花飛處杜鵑愁。"]', '["春风簫管怨津楼，三奏行人醉不留。","別後相思江上岸，落花飞处杜鵑愁。"]', '诗', 'shi', '', NULL, '同張惟送霍總 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e303e0c4-2c11-4a79-aa5e-42c35340f111', '贈別崔起居', '贈別崔起居', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["三十年前會府同，紅顏銷盡兩成翁。","別淚共將何處灑，錦江南渡足春風。"]', '["三十年前會府同，紅顏銷尽兩成翁。","別泪共將何处灑，錦江南渡足春风。"]', '诗', 'shi', '', NULL, '贈別崔起居 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0383d7f2-5f68-4f59-b0b6-9bc78141ac8d', '春日偶題', '春日偶題', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["山川百戰古刀州，龍節來分聖主憂。","靜守化條無一事，春風獨上望京樓。"]', '["山川百戰古刀州，龙節来分聖主憂。","静守化條無一事，春风独上望京楼。"]', '诗', 'shi', '', NULL, '春日偶題 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f9b8c66-73e1-4e8e-bf47-b86227d04865', '聽歌', '听歌', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["月上重樓絲管秋，佳人夜唱古梁州。","滿堂誰是知音者，不惜千金與莫愁。"]', '["月上重楼絲管秋，佳人夜唱古梁州。","满堂誰是知音者，不惜千金與莫愁。"]', '诗', 'shi', '', NULL, '聽歌 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8f03f75-1b1a-4b4c-89d8-838c23527d7d', '酬韋胄曹', '酬韋胄曹', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["相逢異縣蹉跎意，無復少年容易歡。","桃李美人攀折盡，何如松柏四時寒。"]', '["相逢異縣蹉跎意，無复少年容易歡。","桃李美人攀折尽，何如松柏四时寒。"]', '诗', 'shi', '', NULL, '酬韋胄曹 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae6fed07-a7f9-4283-b5c8-1d330730630f', '同幕府夜宴惜花', '同幕府夜宴惜花', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["芳草落花明月榭，朝雲暮雨錦城春。","莫愁紅豔風前散，自有青蛾鏡裏人。"]', '["芳草落花明月榭，朝云暮雨錦城春。","莫愁紅豔风前散，自有青蛾镜裏人。"]', '诗', 'shi', '', NULL, '同幕府夜宴惜花 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36140ae0-9376-4462-bdcf-89497be3482e', '代佳人贈張郎中', '代佳人贈張郎中', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["洛陽佳麗本神仙，冰雪顏容桃李年。","心愛阮郎留不住，獨將珠淚濕紅鉛。"]', '["洛陽佳丽本神仙，冰雪顏容桃李年。","心愛阮郎留不住，独將珠泪濕紅鉛。"]', '诗', 'shi', '', NULL, '代佳人贈張郎中 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3276545b-c16b-4f60-a05a-890a32a2f989', '餞裴行軍赴朝命', '餞裴行軍赴朝命', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["來時聖主假光輝，心恃朝恩計日歸。","誰料忽成雲雨別，獨將邊淚灑戎衣。"]', '["来时聖主假光輝，心恃朝恩計日归。","誰料忽成云雨別，独將邊泪灑戎衣。"]', '诗', 'shi', '', NULL, '餞裴行軍赴朝命 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('599f85c6-76cb-4af5-bc51-67b9c36b2ab4', '秋日經潼關感寓', '秋日經潼关感寓', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["昔年曾逐漢征東，三授兵符百戰中。","力保山河嗟下世，秋風牢落故營空。"]', '["昔年曾逐漢征东，三授兵符百戰中。","力保山河嗟下世，秋风牢落故營空。"]', '诗', 'shi', '', NULL, '秋日經潼關感寓 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2fe3516-46f7-4dfd-a920-81ea1183946c', '贈歌人', '贈歌人', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["仙歌靜轉玉簫催，疑是流鶯禁苑來。","他日相思夢巫峽，莫敎雲雨晦陽臺。"]', '["仙歌静轉玉簫催，疑是流鶯禁苑来。","他日相思梦巫峽，莫敎云雨晦陽台。"]', '诗', 'shi', '', NULL, '贈歌人 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f4b11ce-41f7-4601-bf8c-8b71fdffbd85', '見郭侍郎題壁', '见郭侍郎題壁', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["萬里楓江偶問程，青苔壁上故人名。","悠悠身世限南北，一別十年空復情。"]', '["万里楓江偶问程，青苔壁上故人名。","悠悠身世限南北，一別十年空复情。"]', '诗', 'shi', '', NULL, '見郭侍郎題壁 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44ed1bc9-3783-42a6-bc48-82485dbb977f', '癸巳歲吉甫圜丘攝事合於中書後閣宿齋常負忝媿移止於集賢院會門下相公以七言垂寄亦有所酬短章絕韻不足抒意因敘所懷奉寄相公兼呈集賢院諸學士', '癸巳歲吉甫圜丘攝事合於中书後閣宿斋常負忝媿移止於集賢院會门下相公以七言垂寄亦有所酬短章絕韻不足抒意因敘所懷奉寄相公兼呈集賢院諸学士', '66efb8ec-44b5-4adc-90fb-1f9860b6fadd', '唐', '["淮海同三入，樞衡過六年。","廟齋兢永夕，書府會羣仙。","粉壁連霜曙，冰池對月圓。","歲時憂裏換，鐘漏靜中傳。","蓬髮顏空老，松心契獨全。","贈言因傅說，垂訓在三篇。"]', '["淮海同三入，樞衡過六年。","廟斋兢永夕，书府會羣仙。","粉壁連霜曙，冰池对月圓。","歲时憂裏換，鐘漏静中傳。","蓬髮顏空老，松心契独全。","贈言因傅说，垂訓在三篇。"]', '诗', 'shi', '', NULL, '癸巳歲吉甫圜丘攝事合於中書後閣宿齋常負忝媿移止於集賢院會門下相公以七言垂寄亦有所酬短章絕韻不足抒意因敘所懷奉寄相公兼呈集賢院諸學士 李吉甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ed7ffff-815f-4eb6-a6c6-889e3c0f5726', '夏夜北園即事寄門下武相公', '夏夜北园即事寄门下武相公', '66efb8ec-44b5-4adc-90fb-1f9860b6fadd', '唐', '["結構非華宇，登臨似古原。","僻殊蕭相宅，蕪勝邵平園。","避暑依南廡，追涼在北軒。","煙霞霄外靜，草露月中繁。","鵲繞驚還止，蟲吟思不喧。","懷君欲有贈，宿昔貴忘言。"]', '["結構非华宇，登臨似古原。","僻殊蕭相宅，蕪勝邵平园。","避暑依南廡，追涼在北軒。","煙霞霄外静，草露月中繁。","鵲繞驚還止，蟲吟思不喧。","懷君欲有贈，宿昔貴忘言。"]', '诗', 'shi', '', NULL, '夏夜北園即事寄門下武相公 李吉甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe5c016a-8068-4c6c-884c-673000384992', '九日小園獨謠贈門下武相公', '九日小园独謠贈门下武相公', '66efb8ec-44b5-4adc-90fb-1f9860b6fadd', '唐', '["小園休沐暇，暫與故山期。","樹杪懸丹棗，苔陰落紫梨。","舞叢新菊徧，繞格古藤垂。","受露紅蘭晚，迎霜白薤肥。","上公留鳳沼，冠劒侍清祠。","應念端居者，長慙補衮詩。"]', '["小园休沐暇，暫與故山期。","樹杪懸丹棗，苔陰落紫梨。","舞叢新菊徧，繞格古藤垂。","受露紅蘭晚，迎霜白薤肥。","上公留鳳沼，冠劒侍清祠。","應念端居者，长慙補衮诗。"]', '诗', 'shi', '', NULL, '九日小園獨謠贈門下武相公 李吉甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fdc955d-2299-4c7f-b87a-70debfcda2cf', '懷伊川賦', '懷伊川賦', '66efb8ec-44b5-4adc-90fb-1f9860b6fadd', '唐', '["龍門南岳盡伊原，草樹人煙目所存。","正是北州梨棗熟，夢魂秋日到郊園。"]', '["龙门南岳尽伊原，草樹人煙目所存。","正是北州梨棗熟，梦魂秋日到郊园。"]', '诗', 'shi', '', NULL, '懷伊川賦 李吉甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e108a00-ae84-4160-8ff3-5248a1e5613d', '奉和武相公省中宿齋酬李相公見寄', '奉和武相公省中宿斋酬李相公见寄', '170218e7-8099-4428-a712-203ab61ebca6', '唐', '["高閣安仁省，名園廣武廬。","沐蘭朝太一，種竹詠華胥。","禁靜疎鐘徹，庭開爽韻虛。","洪鈞齊萬物，縹帙整羣書。","寒露滋新菊，秋風落故蕖。","同懷不同賞，幽意竟何如。"]', '["高閣安仁省，名园廣武廬。","沐蘭朝太一，種竹詠华胥。","禁静疎鐘徹，庭开爽韻虛。","洪鈞齊万物，縹帙整羣书。","寒露滋新菊，秋风落故蕖。","同懷不同賞，幽意竟何如。"]', '诗', 'shi', '', NULL, '奉和武相公省中宿齋酬李相公見寄 鄭絪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09b66e08-96ee-4d27-ad2f-0df7aab9bff8', '寒夜聞霜鐘', '寒夜闻霜鐘', '170218e7-8099-4428-a712-203ab61ebca6', '唐', '["霜鐘初應律，寂寂出重林。","拂水宜清聽，凌空散逈音。","舂容時未歇，搖曳夜方深。","月下和虛籟，風前間遠砧。","淨兼寒漏徹，閑畏曙更侵。","遙想千山外，泠泠何處尋。"]', '["霜鐘初應律，寂寂出重林。","拂水宜清听，凌空散逈音。","舂容时未歇，搖曳夜方深。","月下和虛籟，风前间远砧。","淨兼寒漏徹，闲畏曙更侵。","遙想千山外，泠泠何处尋。"]', '诗', 'shi', '', NULL, '寒夜聞霜鐘 鄭絪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('065ec845-0d17-47f0-92ff-9b433fa200d7', '奉酬宣上人九月十五日東亭望月見贈因懷紫閣舊遊', '奉酬宣上人九月十五日东亭望月见贈因懷紫閣旧游', '170218e7-8099-4428-a712-203ab61ebca6', '唐', '["中年偶逐鴛鸞侶，弱歲多從麋鹿羣。","紫閣道流今不見，紅樓禪客早曾聞。","松齋月朗星初散，苔砌霜繁夜欲分。","一覽綵牋佳句滿，何人更詠惠休文。"]', '["中年偶逐鴛鸾侶，弱歲多從麋鹿羣。","紫閣道流今不见，紅楼禪客早曾闻。","松斋月朗星初散，苔砌霜繁夜欲分。","一覽綵牋佳句满，何人更詠惠休文。"]', '诗', 'shi', '', NULL, '奉酬宣上人九月十五日東亭望月見贈因懷紫閣舊遊 鄭絪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7973e61-9631-48b9-853d-839a9b51da9c', '九日登高懷邵二', '九日登高懷邵二', '170218e7-8099-4428-a712-203ab61ebca6', '唐', '["簪茱泛菊俯平阡，飲過三杯却惘然。","十歲此辰同醉友，登高各處已三年。"]', '["簪茱泛菊俯平阡，饮過三杯却惘然。","十歲此辰同醉友，登高各处已三年。"]', '诗', 'shi', '', NULL, '九日登高懷邵二 鄭絪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4c9fd5b-7d00-4a57-9799-f255cf4c34ea', '享太廟樂章', '享太廟乐章', '170218e7-8099-4428-a712-203ab61ebca6', '唐', '["於穆時文，受天明命。","允恭玄默，化成理定。","出震嗣德，應乾傳聖。","猗歟緝熙，千億流慶。"]', '["於穆时文，受天明命。","允恭玄默，化成理定。","出震嗣德，應乾傳聖。","猗歟緝熙，千億流慶。"]', '诗', 'shi', '', NULL, '享太廟樂章 鄭絪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f99ba34-200a-466e-85e8-db551714528c', '句', '句', '170218e7-8099-4428-a712-203ab61ebca6', '唐', '["情人共惆悵，良友不同遊。"]', '["情人共惆悵，良友不同游。"]', '诗', 'shi', '', NULL, '句 鄭絪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48c02ec1-d54a-4a91-8e03-e7e37e7c02d8', '和黃門相公詔還題石門洞', '和黄门相公詔還題石门洞', 'b6dc0167-a22a-48a0-b2a5-9e90ae635422', '唐', '["紫氛隨馬處，黃閣駐車情。","嵌壑驚山勢，周灘戀水聲。","地分三蜀限，關志百牢名。","琬琰攀酬郢，微言鼎飪情。"]', '["紫氛隨马处，黄閣駐车情。","嵌壑驚山勢，周灘戀水声。","地分三蜀限，关志百牢名。","琬琰攀酬郢，微言鼎飪情。"]', '诗', 'shi', '', NULL, '和黃門相公詔還題石門洞 鄭餘慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59d4fa99-b2bd-4cfa-88a7-3e43888a9173', '享太廟樂章', '享太廟乐章', 'b6dc0167-a22a-48a0-b2a5-9e90ae635422', '唐', '["開邸除暴，時邁勛尊。","三元告命，四極駿奔。","金枝翠葉，輝燭瑤琨。","象德億載，貽慶湯孫。"]', '["开邸除暴，时邁勛尊。","三元告命，四極駿奔。","金枝翠葉，輝燭瑤琨。","象德億載，貽慶湯孫。"]', '诗', 'shi', '', NULL, '享太廟樂章 鄭餘慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84c837f5-7ccb-4252-8592-d509e7792ced', '和黃門武相公詔還題石門洞', '和黄门武相公詔還題石门洞', '024f8550-784f-4db7-a694-fbd8f282ed08', '唐', '["益部恩輝降，同榮漢相還。","韶芳滿歸路，軒騎出重關。","望日朝天闕，披雲過蜀山。","更題風雅韻，永絕翠嵓間。"]', '["益部恩輝降，同榮漢相還。","韶芳满归路，軒騎出重关。","望日朝天闕，披云過蜀山。","更題风雅韻，永絕翠嵓间。"]', '诗', 'shi', '', NULL, '和黃門武相公詔還題石門洞 趙宗儒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('672a206d-370a-4d5a-ad33-fe74689475ba', '和武相公錦樓翫月得濃字', '和武相公錦楼翫月得濃字', 'f4a65a16-99b3-4548-a77e-9dce02b2d8a9', '唐', '["此夜年年月，偏宜此地逢。","近看江水淺，遙辨雪山重。","萬井金花肅，千林玉露濃。","不唯樓上思，飛蓋亦陪從。"]', '["此夜年年月，偏宜此地逢。","近看江水淺，遙辨雪山重。","万井金花肅，千林玉露濃。","不唯楼上思，飞蓋亦陪從。"]', '诗', 'shi', '', NULL, '和武相公錦樓翫月得濃字 柳公綽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88cfcd1d-7f8b-48ce-bd8a-f8b24f96b06c', '題梓州牛頭寺', '題梓州牛头寺', 'f4a65a16-99b3-4548-a77e-9dce02b2d8a9', '唐', '["一出西城第二橋，兩邊山木晚蕭蕭。","井花淨洗行人耳，留聽溪聲入夜潮。"]', '["一出西城第二橋，兩邊山木晚蕭蕭。","井花淨洗行人耳，留听溪声入夜潮。"]', '诗', 'shi', '', NULL, '題梓州牛頭寺 柳公綽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33aca5e5-8e74-4ba9-8ba1-cc083d6f93f5', '贈毛仙翁', '贈毛仙翁', 'f4a65a16-99b3-4548-a77e-9dce02b2d8a9', '唐', '["桃源千里遠，花洞四時春。","中有含真客，長爲不死人。","松高枝葉茂，鶴老羽毛新。","莫遣同籬槿，朝榮暮化塵。"]', '["桃源千里远，花洞四时春。","中有含真客，长爲不死人。","松高枝葉茂，鹤老羽毛新。","莫遣同籬槿，朝榮暮化塵。"]', '诗', 'shi', '', NULL, '贈毛仙翁 柳公綽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b9d00c7-3128-4bee-b338-2d354d51c002', '和武相公中秋錦樓翫月得蒼字', '和武相公中秋錦楼翫月得蒼字', 'bc293f88-b807-4fe6-b698-174bebc44ec6', '唐', '["高秋今夜月，皓色正蒼蒼。","遠水澄如練，孤鴻逈帶霜。","旅人方積思，繁宿稍沈光。","朱檻叨陪賞，尤宜清漏長。"]', '["高秋今夜月，皓色正蒼蒼。","远水澄如練，孤鴻逈带霜。","旅人方積思，繁宿稍沈光。","朱檻叨陪賞，尤宜清漏长。"]', '诗', 'shi', '', NULL, '和武相公中秋錦樓翫月得蒼字 張正一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1647555-1944-4bdb-9515-7ab825db789b', '奉和武相公中秋錦樓翫月得來字', '奉和武相公中秋錦楼翫月得来字', 'e575ec45-b79b-4db5-b3da-adf2e86e46a6', '唐', '["玉露中秋夜，金波碧落開。","鵲驚初泛濫，鴻思共裴回。","遠月清光徧，高空爽氣來。","此時陪永望，更得上燕臺。"]', '["玉露中秋夜，金波碧落开。","鵲驚初泛濫，鴻思共裴回。","远月清光徧，高空爽氣来。","此时陪永望，更得上燕台。"]', '诗', 'shi', '', NULL, '奉和武相公中秋錦樓翫月得來字 徐放 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26812d7f-e7f0-4936-be69-3dc2cf0bc0c8', '和武相公中秋錦樓翫月 一', '和武相公中秋錦楼翫月 一', '64c36659-b4b6-4815-94dd-30f1fbf9070f', '唐', '["清景同千里，寒光盡一年。","竟天多鴈過，通夕少人眠。","照別江樓上，添愁野帳前。","隋侯恩未報，猶有夜珠圓。"]', '["清景同千里，寒光尽一年。","竟天多鴈過，通夕少人眠。","照別江楼上，添愁野帳前。","隋侯恩未報，猶有夜珠圓。"]', '诗', 'shi', '', NULL, '和武相公中秋錦樓翫月 一 崔備 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80e7683d-5fdb-4cb6-96a0-c6fe3caac9fd', '和武相公中秋錦樓翫月 二', '和武相公中秋錦楼翫月 二', '64c36659-b4b6-4815-94dd-30f1fbf9070f', '唐', '["四時皆有月，一夜獨當秋。","照耀初含露，裴回正滿樓。","遙連雪山淨，逈入錦江流。","願以清光末，年年許從遊。"]', '["四时皆有月，一夜独當秋。","照耀初含露，裴回正满楼。","遙連雪山淨，逈入錦江流。","願以清光末，年年許從游。"]', '诗', 'shi', '', NULL, '和武相公中秋錦樓翫月 二 崔備 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ded1278e-fc9c-4144-a9b8-909dedc80ed1', '奉陪武相公西亭夜宴陸郎中', '奉陪武相公西亭夜宴陸郎中', '64c36659-b4b6-4815-94dd-30f1fbf9070f', '唐', '["賓閣玳筵開，通宵遞玉杯。","塵隨歌扇起，雪逐舞衣迴。","剪燭清光發，添香煖氣來。","令君敦宿好，更爲一裴回。"]', '["賓閣玳筵开，通宵遞玉杯。","塵隨歌扇起，雪逐舞衣迴。","剪燭清光發，添香煖氣来。","令君敦宿好，更爲一裴回。"]', '诗', 'shi', '', NULL, '奉陪武相公西亭夜宴陸郎中 崔備 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f96292d-2984-443f-bf6e-bf8d9a0bca98', '清溪路中寄諸公', '清溪路中寄諸公', '64c36659-b4b6-4815-94dd-30f1fbf9070f', '唐', '["偏郡隔雲岑，迴溪路更深。","少留攀桂樹，長渴望梅林。","野筍資公膳，山花慰客心。","別來無信息，可謂井瓶沈。"]', '["偏郡隔云岑，迴溪路更深。","少留攀桂樹，长渴望梅林。","野筍資公膳，山花慰客心。","別来無信息，可謂井瓶沈。"]', '诗', 'shi', '', NULL, '清溪路中寄諸公 崔備 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7535fc40-4a58-4d17-8a62-49ec015d16e5', '奉酬中書相公至日圜丘行事合於中書宿直移止於集賢院敘情見寄之什', '奉酬中书相公至日圜丘行事合於中书宿直移止於集賢院敘情见寄之什', '64c36659-b4b6-4815-94dd-30f1fbf9070f', '唐', '["典籍開書府，恩榮避鼎司。","郊丘資有事，齋戒守無爲。","宿霧蒙瓊樹，餘香覆玉墀。","進經逢乙夜，展禮值明時。","勳共山河列，名同竹帛垂。","年年佐堯舜，相與致雍熙。"]', '["典籍开书府，恩榮避鼎司。","郊丘資有事，斋戒守無爲。","宿霧蒙瓊樹，餘香覆玉墀。","進經逢乙夜，展禮值明时。","勳共山河列，名同竹帛垂。","年年佐堯舜，相與致雍熙。"]', '诗', 'shi', '', NULL, '奉酬中書相公至日圜丘行事合於中書宿直移止於集賢院敘情見寄之什 崔備 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69326a4a-873d-48a0-aa55-4b0100b4dbe9', '使院憶山中道侶兼懷李約', '使院憶山中道侶兼懷李約', '64c36659-b4b6-4815-94dd-30f1fbf9070f', '唐', '["松竹去名嶽，衡茅思舊居。","山君水上印，天女月中書。","舊秩芸香在，空匳藥氣餘。","褐衣寬易攬，白髮少難梳。","病柳傷摧折，殘花惜掃除。","憶巢同倦鳥，避網甚跳魚。","阮巷慚交絕，商嵓愧跡疎。","與君非宦侶，何日共樵漁。"]', '["松竹去名嶽，衡茅思旧居。","山君水上印，天女月中书。","旧秩芸香在，空匳藥氣餘。","褐衣寬易攬，白髮少难梳。","病柳傷摧折，殘花惜掃除。","憶巢同倦鸟，避網甚跳鱼。","阮巷慚交絕，商嵓愧跡疎。","與君非宦侶，何日共樵漁。"]', '诗', 'shi', '', NULL, '使院憶山中道侶兼懷李約 崔備 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81b16cce-4a73-4c69-9ce0-2064143e3f13', '奉陪武相公西亭夜[宴]陸郎中', '奉陪武相公西亭夜[宴]陸郎中', 'a10da015-0dfd-4888-916f-7d7870d920c7', '唐', '["弘閣陳芳宴，佳賓此會難。","交逢貴日重，醉得少時歡。","舒黛凝歌思，求音足筆端。","一聞清佩動，珠玉夜珊珊。"]', '["弘閣陳芳宴，佳賓此會难。","交逢貴日重，醉得少时歡。","舒黛凝歌思，求音足笔端。","一闻清佩动，珠玉夜珊珊。"]', '诗', 'shi', '', NULL, '奉陪武相公西亭夜[宴]陸郎中 蕭祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c0b2801-38db-4c5a-95c1-9a8f1a65a1b9', '遊石堂觀', '游石堂观', 'a10da015-0dfd-4888-916f-7d7870d920c7', '唐', '["西山高高何所如，上有古昔真人居。","嶔崖巨石自成室，其下磅礴含清虛。","我來斯邑訪遺迹，乃遇沈生躭載籍。","沈生爲政哀惸[嫠]，又能索隱探靈奇。","欣然向我話佳境，與我崎嶇到山頂。","甘瓜剖綠出寒泉，碧甌浮花酌春茗。","嚼瓜啜茗身清涼，汗消絺綌如迎霜。","胡爲空山百草花，倏爾籩豆肆我旁。","始驚知周無小大，力寡多方驗斯在。","妙用騰聲冠蓋間，勝遊恣意煙霞外。","故碑石像凡幾年，雲鬱雨霏生綠煙。","我知遊此多靈仙，縹緲月中飛下天。","天風微微夕露委，松梢颼颼曉聲起。","鳳去空遺簫管音，星翻寥落銀河水。","勸君學道此時來，結茅獨宿何遼哉。","齋心玄默感靈衛，必見鸞鶴相裴回。","我愛崇山雙劒北，峰如人首拄天黑。","羣仙傴僂勢奔走，壯若歸尊趨有德。","半巖有洞頂有池，出入靈怪潛蛟螭。","我去不得晝夜思，夢遊曾信南風吹。","南風吹我到林嶺，故國不見秦天逈。","山花名藥撲地香，月色泉聲洞心冷。","蔭松散髮逢異人，寂寞曠然口不言。","道陵公遠莫能識，髮短耳長誰獨存。","司農驚覺忽惆悵，可惜所遊俱是妄。","蘊懷耿耿誰與言，直至今來意通形神開。","擁傳又恨斜陽催，一丘人境尚堪戀，何況海上金銀臺。"]', '["西山高高何所如，上有古昔真人居。","嶔崖巨石自成室，其下磅礴含清虛。","我来斯邑訪遺迹，乃遇沈生躭載籍。","沈生爲政哀惸[嫠]，又能索隐探靈奇。","欣然向我話佳境，與我崎嶇到山頂。","甘瓜剖綠出寒泉，碧甌浮花酌春茗。","嚼瓜啜茗身清涼，汗消絺綌如迎霜。","胡爲空山百草花，倏爾籩豆肆我旁。","始驚知周無小大，力寡多方驗斯在。","妙用腾声冠蓋间，勝游恣意煙霞外。","故碑石像凡幾年，云鬱雨霏生綠煙。","我知游此多靈仙，縹緲月中飞下天。","天风微微夕露委，松梢颼颼晓声起。","鳳去空遺簫管音，星翻寥落銀河水。","勸君学道此时来，結茅独宿何遼哉。","斋心玄默感靈衛，必见鸾鹤相裴回。","我愛崇山雙劒北，峰如人首拄天黑。","羣仙傴僂勢奔走，壯若归尊趨有德。","半巖有洞頂有池，出入靈怪潛蛟螭。","我去不得晝夜思，梦游曾信南风吹。","南风吹我到林嶺，故国不见秦天逈。","山花名藥撲地香，月色泉声洞心冷。","蔭松散髮逢異人，寂寞曠然口不言。","道陵公远莫能識，髮短耳长誰独存。","司農驚覺忽惆悵，可惜所游俱是妄。","蘊懷耿耿誰與言，直至今来意通形神开。","擁傳又恨斜陽催，一丘人境尚堪戀，何況海上金銀台。"]', '诗', 'shi', '', NULL, '遊石堂觀 蕭祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e1dec45-4d55-43be-a12d-fe17aeee05b8', '奉陪武相公西亭夜宴陸郎中', '奉陪武相公西亭夜宴陸郎中', '7eb90ad3-493d-49d5-9ce9-f7076d5645ee', '唐', '["芳氣襲猗蘭，青雲展舊歡。","仙來紅燭下，花發綵毫端。","海嶽期方遠，松筠歲正寒。","仍聞言贈處，一字重琅玕。"]', '["芳氣襲猗蘭，青云展旧歡。","仙来紅燭下，花發綵毫端。","海嶽期方远，松筠歲正寒。","仍闻言贈处，一字重琅玕。"]', '诗', 'shi', '', NULL, '奉陪武相公西亭夜宴陸郎中 王良士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62e9f763-eff2-4c64-bfcf-e343f318082c', '南至日隔霜仗望含元殿爐煙', '南至日隔霜仗望含元殿爐煙', '7eb90ad3-493d-49d5-9ce9-f7076d5645ee', '唐', '["抗殿疏龍首，高高接上玄。","節當南至日，星是北辰天。","寶戟羅仙仗，金爐引御煙。","霏微雙闕麗，容曳九門連。","拂曙祥光滿，分晴瑞色鮮。","一陽今在曆，生植仰陶甄。"]', '["抗殿疏龙首，高高接上玄。","節當南至日，星是北辰天。","寶戟羅仙仗，金爐引御煙。","霏微雙闕丽，容曳九门連。","拂曙祥光满，分晴瑞色鲜。","一陽今在曆，生植仰陶甄。"]', '诗', 'shi', '', NULL, '南至日隔霜仗望含元殿爐煙 王良士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d340e52-7750-4d46-a3d8-cc0afcdeead2', '奉陪武相公西亭夜宴陸郎中', '奉陪武相公西亭夜宴陸郎中', '5b94cef3-86d4-45ee-9afe-c7661547f900', '唐', '["仙郎膺上才，夜宴接三台。","燭引銀河轉，花連錦帳開。","靜看歌扇舉，不覺舞腰回。","寥落東方曙，無辭盡玉杯。"]', '["仙郎膺上才，夜宴接三台。","燭引銀河轉，花連錦帳开。","静看歌扇舉，不覺舞腰回。","寥落东方曙，無辞尽玉杯。"]', '诗', 'shi', '', NULL, '奉陪武相公西亭夜宴陸郎中 獨孤實 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d37fc42-ae4e-40c3-930a-e1f645a78493', '奉陪武相公西亭夜宴陸郎中', '奉陪武相公西亭夜宴陸郎中', 'cae233c6-b22c-443d-a923-361374c72c21', '唐', '["華堂良宴開，星使自天來。","舞轉朱絲逐，歌餘素扇回。","水光凌曲檻，夜色靄高臺。","不在賓階末，何由接上台。"]', '["华堂良宴开，星使自天来。","舞轉朱絲逐，歌餘素扇回。","水光凌曲檻，夜色靄高台。","不在賓階末，何由接上台。"]', '诗', 'shi', '', NULL, '奉陪武相公西亭夜宴陸郎中 盧士政 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0eb43102-8924-4e6d-a2f8-7304c15df2df', '聞鶯', '闻鶯', 'b6e42185-4c39-47c7-b1c2-884b6a7078af', '唐', '["玉繩河漢曉縱橫，萬籟潛收鶯獨鳴。","能將百囀清心骨，寧止閑窗夢不成。"]', '["玉繩河漢晓縱橫，万籟潛收鶯独鳴。","能將百囀清心骨，寧止闲窗梦不成。"]', '诗', 'shi', '', NULL, '聞鶯 于敖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d13cbe7c-4d3e-4ca5-8913-9e71a3de0a7c', '和武相公聞鶯', '和武相公闻鶯', '408f8054-ab51-468d-a614-464b95e11686', '唐', '["華館沈沈曙境清，伯勞初囀月微明。","不知台座宵吟久，猶向花窗驚夢聲。"]', '["华館沈沈曙境清，伯勞初囀月微明。","不知台座宵吟久，猶向花窗驚梦声。"]', '诗', 'shi', '', NULL, '和武相公聞鶯 皇甫鏞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15d66ae7-0b76-4946-be9d-6f6e053cd9f7', '白露爲霜', '白露爲霜', '5d19d97e-048d-4082-aac0-a47b5256afc3', '唐', '["悲秋將歲晚，繁露已成霜。","徧渚蘆先白，霑籬菊自黃。","應鐘鳴遠寺，擁雁度三湘。","氣逼襦衣薄，寒侵宵夢長。","滿庭添月色，拂水斂荷香。","獨念蓬門下，窮年在一方。"]', '["悲秋將歲晚，繁露已成霜。","徧渚蘆先白，霑籬菊自黄。","應鐘鳴远寺，擁雁度三湘。","氣逼襦衣薄，寒侵宵梦长。","满庭添月色，拂水斂荷香。","独念蓬门下，窮年在一方。"]', '诗', 'shi', '', NULL, '白露爲霜 顏粲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a912702-845a-4342-a933-c304a12c956a', '吳宮敎美人戰', '吳宮敎美人戰', '5d19d97e-048d-4082-aac0-a47b5256afc3', '唐', '["有客陳兵畫，功成欲霸吳。","玉顏承將略，金鈿指軍符。","轉佩風雲暗，鳴鼙錦繡趨。","雪花頻落粉，香汗盡流珠。","掩笑誰干令，嚴刑必用誅。","至今孫子術，猶可靜邊隅。"]', '["有客陳兵畫，功成欲霸吳。","玉顏承將略，金鈿指軍符。","轉佩风云暗，鳴鼙錦繡趨。","雪花頻落粉，香汗尽流珠。","掩笑誰干令，嚴刑必用誅。","至今孫子術，猶可静邊隅。"]', '诗', 'shi', '', NULL, '吳宮敎美人戰 顏粲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bab503a-923c-48d1-b22d-9002d3828eb7', '月暎清淮流', '月暎清淮流', 'dd9173fb-a835-4a37-b4db-383aa0c01f9f', '唐', '["遙夜淮彌淨，浮空月正明。","虛無含氣白，凝澹暎波清。","見底深還淺，居高缺復盈。","處柔知坎德，持潔表陰精。","利物功難並，和光道已成。","安流方利涉，應鑒此時情。"]', '["遙夜淮彌淨，浮空月正明。","虛無含氣白，凝澹暎波清。","见底深還淺，居高缺复盈。","处柔知坎德，持潔表陰精。","利物功难並，和光道已成。","安流方利涉，應鑒此时情。"]', '诗', 'shi', '', NULL, '月暎清淮流 徐敞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa7c671f-a287-48ca-b682-88f0b3a52f5f', '圓靈水鏡', '圓靈水镜', 'dd9173fb-a835-4a37-b4db-383aa0c01f9f', '唐', '["浮光上東洛，楊彩滿圓靈。","明滅淪江水，盈虛逐砌蓂。","不分沙岸白，偏照海山清。","練色臨窗牖，蟾光靄戶庭。","成輪疑璧影，初魄類弓形。","遠近凝清質，娟娟出衆星。"]', '["浮光上东洛，楊彩满圓靈。","明滅淪江水，盈虛逐砌蓂。","不分沙岸白，偏照海山清。","練色臨窗牖，蟾光靄戶庭。","成輪疑璧影，初魄類弓形。","远近凝清質，娟娟出衆星。"]', '诗', 'shi', '', NULL, '圓靈水鏡 徐敞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc1ccfae-5091-4e0a-9b84-2e2cdecd6f78', '虹藏不見', '虹藏不见', 'dd9173fb-a835-4a37-b4db-383aa0c01f9f', '唐', '["迎冬小雪至，應節晚虹藏。","玉氣徒成象，星精不散光。","美人初比色，飛鳥罷呈祥。","石澗收晴影，天津失彩梁。","霏霏空暮雨，杳杳暎殘陽。","舒卷應時令，因知聖曆長。"]', '["迎冬小雪至，應節晚虹藏。","玉氣徒成象，星精不散光。","美人初比色，飞鸟罷呈祥。","石澗收晴影，天津失彩梁。","霏霏空暮雨，杳杳暎殘陽。","舒卷應时令，因知聖曆长。"]', '诗', 'shi', '', NULL, '虹藏不見 徐敞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cc0df2b-7f6a-49a4-845a-256909e1640f', '白露爲霜', '白露爲霜', 'dd9173fb-a835-4a37-b4db-383aa0c01f9f', '唐', '["早寒青女至，零露結爲霜。","入夜飛清景，凌晨積素光。","駟星初皙皙，葭菼復蒼蒼。","色冒沙灘白，威加木葉黃。","鮮輝襲紈扇，殺氣掩干將。","葛屨那堪履，徒令君子傷。"]', '["早寒青女至，零露結爲霜。","入夜飞清景，凌晨積素光。","駟星初皙皙，葭菼复蒼蒼。","色冒沙灘白，威加木葉黄。","鲜輝襲紈扇，殺氣掩干將。","葛屨那堪履，徒令君子傷。"]', '诗', 'shi', '', NULL, '白露爲霜 徐敞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0e11484-7829-42a7-9ba1-fef44fd90e8c', '賦得金莖露', '賦得金莖露', 'dd9173fb-a835-4a37-b4db-383aa0c01f9f', '唐', '["武帝貴長生，延年餌玉英。","銅盤貯珠露，仙掌抗金莖。","拂曙氛埃斂，凌空沆瀣清。","岧嶤捧瑞氣，巃嵸出宮城。","勢入浮雲聳，形標霽色明。","大君當御宇，何必去蓬瀛。"]', '["武帝貴长生，延年餌玉英。","銅盤貯珠露，仙掌抗金莖。","拂曙氛埃斂，凌空沆瀣清。","岧嶤捧瑞氣，巃嵸出宮城。","勢入浮云聳，形標霽色明。","大君當御宇，何必去蓬瀛。"]', '诗', 'shi', '', NULL, '賦得金莖露 徐敞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecd26238-3ff4-426f-991c-db5f7e2fa663', '圓靈水鏡', '圓靈水镜', 'e03e529f-d309-47c2-8af3-6a1333cbfa66', '唐', '["鳳池開月鏡，清瑩寫寥天。","影散微波上，光含片玉懸。","菱花凝泛灧，桂樹暎清鮮。","樂廣披雲日，山濤卷霧年。","濯纓何處去，鑒物自堪妍。","迴首看雲液，蟾蜍勢正圓。"]', '["鳳池开月镜，清瑩寫寥天。","影散微波上，光含片玉懸。","菱花凝泛灧，桂樹暎清鲜。","乐廣披云日，山濤卷霧年。","濯纓何处去，鑒物自堪妍。","迴首看云液，蟾蜍勢正圓。"]', '诗', 'shi', '', NULL, '圓靈水鏡 張聿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f1665d5-167e-466e-b78c-205026af40af', '景風扇物', '景风扇物', 'e03e529f-d309-47c2-8af3-6a1333cbfa66', '唐', '["何處青蘋末，呈祥起遠空。","曉來搖草樹，輕度淨塵蒙。","水上微波動，林前媚景通。","寥天鳴萬籟，蘭徑長幽藂。","漸颺摶扶勢，應從槖籥功。","開襟若有日，願覩大王風。"]', '["何处青蘋末，呈祥起远空。","晓来搖草樹，轻度淨塵蒙。","水上微波动，林前媚景通。","寥天鳴万籟，蘭徑长幽藂。","漸颺摶扶勢，應從槖籥功。","开襟若有日，願覩大王风。"]', '诗', 'shi', '', NULL, '景風扇物 張聿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd2121e3-0b68-418f-ac3e-25f3f8f8d38b', '劒化爲龍', '劒化爲龙', 'e03e529f-d309-47c2-8af3-6a1333cbfa66', '唐', '["古劒誠難屈，精明有所從。","沈埋方出獄，合會却成龍。","牛斗光初歇，蜿蜒氣漸濃。","雲濤透百丈，水府躍千重。","拖尾迷蓮鍔，張鱗露錦容。","至今沙岸下，誰得覩玄蹤。"]', '["古劒誠难屈，精明有所從。","沈埋方出獄，合會却成龙。","牛斗光初歇，蜿蜒氣漸濃。","云濤透百丈，水府躍千重。","拖尾迷蓮鍔，張鱗露錦容。","至今沙岸下，誰得覩玄蹤。"]', '诗', 'shi', '', NULL, '劒化爲龍 張聿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0d67b0e-00be-4415-bb75-0a67874a70c9', '餘瑞麥', '餘瑞麦', 'e03e529f-d309-47c2-8af3-6a1333cbfa66', '唐', '["瑞麥生堯日，芃芃雨露偏。","兩岐分更合，異畝頴仍連。","冀獲明王慶，寧唯太守賢。","仁風吹靡靡，甘雨長芊芊。","聖德應多稔，皇家配有年。","已聞天下泰，誰爲濟西田。"]', '["瑞麦生堯日，芃芃雨露偏。","兩岐分更合，異畝頴仍連。","冀獲明王慶，寧唯太守賢。","仁风吹靡靡，甘雨长芊芊。","聖德應多稔，皇家配有年。","已闻天下泰，誰爲濟西田。"]', '诗', 'shi', '', NULL, '餘瑞麥 張聿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5c514d3-ced1-4f5d-a11b-eaee03666fe9', '賦得[首夏]猶清和', '賦得[首夏]猶清和', 'e03e529f-d309-47c2-8af3-6a1333cbfa66', '唐', '["早夏宜春景，和光起禁城。","祝融將御節，炎帝啓朱明。","日送殘花晚，風過御苑清。","郊原浮麥氣，池沼發荷英。","樹影臨山動，禽飛入漢輕。","幸逢堯禹化，全勝谷中情。"]', '["早夏宜春景，和光起禁城。","祝融將御節，炎帝啓朱明。","日送殘花晚，风過御苑清。","郊原浮麦氣，池沼發荷英。","樹影臨山动，禽飞入漢轻。","幸逢堯禹化，全勝谷中情。"]', '诗', 'shi', '', NULL, '賦得[首夏]猶清和 張聿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('113ed055-c563-4624-b599-60de7d6246d2', '移居洞庭', '移居洞庭', '9f0d9e14-cae3-4ab7-8462-345582af266f', '唐', '["重林將疊嶂，此處可逃秦。","水隔人間世，花開洞裏春。","荷鋤分地利，縱酒樂天真。","萬事更何有，吾今已外身。"]', '["重林將叠嶂，此处可逃秦。","水隔人间世，花开洞裏春。","荷鋤分地利，縱酒乐天真。","万事更何有，吾今已外身。"]', '诗', 'shi', '', NULL, '移居洞庭 麴信陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('806341c7-a221-4bbd-bee8-7eab466a2407', '吳門送客', '吳门送客', '9f0d9e14-cae3-4ab7-8462-345582af266f', '唐', '["亂山吳苑外，臨水讓王祠。","素是傷情處，春非送客時。","不須愁落日，且願駐青絲。","千里會應到，一尊誰共持。"]', '["亂山吳苑外，臨水讓王祠。","素是傷情处，春非送客时。","不須愁落日，且願駐青絲。","千里會應到，一尊誰共持。"]', '诗', 'shi', '', NULL, '吳門送客 麴信陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11031562-0934-42be-af76-285639fa65b7', '長安道', '长安道', '9f0d9e14-cae3-4ab7-8462-345582af266f', '唐', '["朱門暎綠楊，雙闕抵通莊。","玉珮聲逾遠，紅塵猶自香。"]', '["朱门暎綠楊，雙闕抵通莊。","玉珮声逾远，紅塵猶自香。"]', '诗', 'shi', '', NULL, '長安道 麴信陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05175d05-24bb-49e9-9dd1-c92703cb2205', '出自賊中謁恒上人', '出自賊中謁恒上人', '9f0d9e14-cae3-4ab7-8462-345582af266f', '唐', '["再拜吾師喜復悲，誓心從此永歸依。","浮生恍忽若真夢，何事于中有是非。"]', '["再拜吾師喜复悲，誓心從此永归依。","浮生恍忽若真梦，何事于中有是非。"]', '诗', 'shi', '', NULL, '出自賊中謁恒上人 麴信陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea82d3a9-ada3-46ff-8f7a-f9f089f6d955', '過真律師舊院', '過真律師旧院', '9f0d9e14-cae3-4ab7-8462-345582af266f', '唐', '["寂然秋院閉秋光，過客閑來禮影堂。","堅冰銷盡還成水，本自無形何足傷。"]', '["寂然秋院閉秋光，過客闲来禮影堂。","堅冰銷尽還成水，本自無形何足傷。"]', '诗', 'shi', '', NULL, '過真律師舊院 麴信陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7936063-a47b-4210-b514-a7216f177260', '酬談上人詠海石榴', '酬談上人詠海石榴', '9f0d9e14-cae3-4ab7-8462-345582af266f', '唐', '["真僧相勸外浮華，萬法無常可歎嗟。","但試尋思階下樹，何人種此我看花。"]', '["真僧相勸外浮华，万法無常可歎嗟。","但試尋思階下樹，何人種此我看花。"]', '诗', 'shi', '', NULL, '酬談上人詠海石榴 麴信陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddcdf931-6f87-4344-bd7b-105f5d478859', '句', '句', '9f0d9e14-cae3-4ab7-8462-345582af266f', '唐', '["臺笠冒山雨，渚田耕荇花。"]', '["台笠冒山雨，渚田耕荇花。"]', '诗', 'shi', '', NULL, '句 麴信陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01e7f9b0-19a0-4ec7-b334-c12ecc904137', '冬日可愛', '冬日可愛', '598697cf-1ea6-4107-92ae-bbf92f92ab92', '唐', '["寒日臨清晝，遼天一望時。","未消埋徑雪，先暖讀書帷。","屬思光難駐，舒情影若遺。","晉臣曾比德，謝客昔言詩。","散彩寧偏煦，流陰信不追。","餘輝如可就，迴燭幸無私。"]', '["寒日臨清晝，遼天一望时。","未消埋徑雪，先暖读书帷。","屬思光难駐，舒情影若遺。","晉臣曾比德，謝客昔言诗。","散彩寧偏煦，流陰信不追。","餘輝如可就，迴燭幸無私。"]', '诗', 'shi', '', NULL, '冬日可愛 張正元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23f4dae2-e951-44ba-896e-790e78c8a291', '臨川羨魚', '臨川羨鱼', '598697cf-1ea6-4107-92ae-bbf92f92ab92', '唐', '["有客百愁侵，求魚正在今。","廣川何渺漫，高岸幾登臨。","風水寧相阻，煙霞豈憚深。","不應同逐鹿，詎肯比從禽。","結網非無力，忘筌自有心。","永存芳餌在，佇立思沈沈。"]', '["有客百愁侵，求鱼正在今。","廣川何渺漫，高岸幾登臨。","风水寧相阻，煙霞豈憚深。","不應同逐鹿，詎肯比從禽。","結網非無力，忘筌自有心。","永存芳餌在，佇立思沈沈。"]', '诗', 'shi', '', NULL, '臨川羨魚 張正元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4d6fab0-17cf-448c-97f9-d1345ad69217', '青雲干呂', '青云干呂', 'ce7f9b2f-c4b6-4b55-afec-90c8a646a3a4', '唐', '["異方占瑞氣，干呂見青雲。","表聖興中國，來王謁大君。","迎祥殊大樂，叶慶類橫汾。","自感明時起，非因觸石分。","暎霄難辨色，從吹乍成文。","須使流千載，垂芳在典墳。"]', '["異方占瑞氣，干呂见青云。","表聖兴中国，来王謁大君。","迎祥殊大乐，叶慶類橫汾。","自感明时起，非因觸石分。","暎霄难辨色，從吹乍成文。","須使流千載，垂芳在典墳。"]', '诗', 'shi', '', NULL, '青雲干呂 王履貞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c620865d-0ff1-4861-9847-114e33be2f18', '青雲干呂 一', '青云干呂 一', 'fad4698c-9a30-44d3-a63c-01bb8686dbd4', '唐', '["祥輝上干呂，郁郁又紛紛。","遠示無爲化，將明至道君。","勢凝千里靜，色向九霄分。","已見從龍意，寧知觸石文。","狀煙殊散漫，捧日更氛氳。","自使來賓國，西瞻仰瑞雲。"]', '["祥輝上干呂，郁郁又紛紛。","远示無爲化，將明至道君。","勢凝千里静，色向九霄分。","已见從龙意，寧知觸石文。","狀煙殊散漫，捧日更氛氳。","自使来賓国，西瞻仰瑞云。"]', '诗', 'shi', '', NULL, '青雲干呂 一 彭伉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd4c60cf-6385-48a0-86b2-2020cdf70f36', '青雲干呂 二', '青云干呂 二', 'fad4698c-9a30-44d3-a63c-01bb8686dbd4', '唐', '["聖布中區化，祥符異域雲。","含春初應呂，暈碧已成文。","東起隨風暖，西流共日曛。","升時嘉異月，爲慶等凝汾。","輕與晴煙比，高將曉霧分。","飄飄如可致，願此翊明君。"]', '["聖布中區化，祥符異域云。","含春初應呂，暈碧已成文。","东起隨风暖，西流共日曛。","升时嘉異月，爲慶等凝汾。","轻與晴煙比，高將晓霧分。","飄飄如可致，願此翊明君。"]', '诗', 'shi', '', NULL, '青雲干呂 二 彭伉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c4ab5cc-b027-4c39-a422-336422b6ac0c', '寄妻', '寄妻', 'fad4698c-9a30-44d3-a63c-01bb8686dbd4', '唐', '["莫訝相如獻賦遲，錦書誰道淚沾衣。","不須化作山頭石，待我堂前折桂枝。"]', '["莫訝相如獻賦遲，錦书誰道泪沾衣。","不須化作山头石，待我堂前折桂枝。"]', '诗', 'shi', '', NULL, '寄妻 彭伉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5a97aba-72cd-4663-81fe-1f0af4375e15', '青雲干呂', '青云干呂', '34dd0de2-8d07-46a8-b8cc-0c6be57b71cb', '唐', '["應節偏干呂，亭亭在紫氛。","綴空初布影，捧日已成文。","結蓋祥光迥，爲樓翠色分。","還同起封上，更似出橫汾。","作瑞來藩國，呈形表聖君。","裴回如有託，誰道比閑雲。"]', '["應節偏干呂，亭亭在紫氛。","綴空初布影，捧日已成文。","結蓋祥光迥，爲楼翠色分。","還同起封上，更似出橫汾。","作瑞来藩国，呈形表聖君。","裴回如有託，誰道比闲云。"]', '诗', 'shi', '', NULL, '青雲干呂 林藻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1a8a5bb-0c34-40a7-a065-e90994eff6c0', '吳宮敎戰', '吳宮敎戰', '34dd0de2-8d07-46a8-b8cc-0c6be57b71cb', '唐', '["強吳矜霸略，講武在深宮。","盡出嬌娥輩，先觀上將風。","揮戈羅袖卷，擐甲汗裝紅。","輕笑分旗下，含羞入隊中。","鼓停行未整，刑舉令方崇。","自可威鄰國，何勞騁戰功。"]', '["強吳矜霸略，講武在深宮。","尽出嬌娥輩，先观上將风。","揮戈羅袖卷，擐甲汗裝紅。","轻笑分旗下，含羞入隊中。","鼓停行未整，刑舉令方崇。","自可威鄰国，何勞騁戰功。"]', '诗', 'shi', '', NULL, '吳宮敎戰 林藻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82506631-692c-4f17-96a4-9fcb52ca6d5a', '梨嶺', '梨嶺', '34dd0de2-8d07-46a8-b8cc-0c6be57b71cb', '唐', '["曾向嶺頭題姓字，不穿楊葉不言歸。","弟兄各折一枝桂，還向嶺頭聯影飛。"]', '["曾向嶺头題姓字，不穿楊葉不言归。","弟兄各折一枝桂，還向嶺头聯影飞。"]', '诗', 'shi', '', NULL, '梨嶺 林藻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9da11f1c-210d-4a69-96f9-35afae382cf9', '贈馮宿', '贈馮宿', '620825b3-8b50-4efe-b3fd-043b359f6c0e', '唐', '["寒城上秦原，遊子衣飄飄。","黑雲截萬里，獵火從中燒。","陰空蒸長煙，殺氣獨不銷。","冰交石可裂，風疾山如搖。","時無青松心，顧我獨不凋。"]', '["寒城上秦原，游子衣飄飄。","黑云截万里，獵火從中燒。","陰空蒸长煙，殺氣独不銷。","冰交石可裂，风疾山如搖。","时無青松心，顧我独不凋。"]', '诗', 'shi', '', NULL, '贈馮宿 李觀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fca1edc-5d1c-4217-9fe2-fac9e7f6537a', '宿裴友書齋', '宿裴友书斋', '620825b3-8b50-4efe-b3fd-043b359f6c0e', '唐', '["臥君山窗下，山鳥與我言。","清風何颼飀，松栢中夜繁。","久遊失歸趣，宿此似故園。","林煙橫近郊，谿月落古原。","穉子不待曉，花間出柴門。"]', '["臥君山窗下，山鸟與我言。","清风何颼飀，松栢中夜繁。","久游失归趣，宿此似故园。","林煙橫近郊，谿月落古原。","穉子不待晓，花间出柴门。"]', '诗', 'shi', '', NULL, '宿裴友書齋 李觀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e5826d9-ab69-4819-8157-bd37264e9ec5', '御溝新柳', '御溝新柳', '620825b3-8b50-4efe-b3fd-043b359f6c0e', '唐', '["御溝迴廣陌，芳柳對行人。","翠色枝枝滿，年光樹樹新。","畏逢攀折客，愁見別離辰。","近暎章臺騎，遙分禁苑春。","嫩陰初覆水，高影漸離塵。","莫入胡兒笛，還令淚溼巾。"]', '["御溝迴廣陌，芳柳对行人。","翠色枝枝满，年光樹樹新。","畏逢攀折客，愁见別離辰。","近暎章台騎，遙分禁苑春。","嫩陰初覆水，高影漸離塵。","莫入胡兒笛，還令泪溼巾。"]', '诗', 'shi', '', NULL, '御溝新柳 李觀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a1d5bd1-5ed5-4872-a6b9-1536e85ad04e', '試中和節詔賜公卿尺詩', '試中和節詔賜公卿尺诗', '620825b3-8b50-4efe-b3fd-043b359f6c0e', '唐', '["淑節韶光媚，皇明寵錫崇。","具寮頒玉尺，成器幸良工。","豈止尋常用，將傳度量同。","人何不取利，物亦賴其功。","紫翰宣殊造，丹誠厲匪躬。","奉之無失墜，恩澤自天中。"]', '["淑節韶光媚，皇明寵錫崇。","具寮頒玉尺，成器幸良工。","豈止尋常用，將傳度量同。","人何不取利，物亦賴其功。","紫翰宣殊造，丹誠厲匪躬。","奉之無失墜，恩澤自天中。"]', '诗', 'shi', '', NULL, '試中和節詔賜公卿尺詩 李觀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bd0ff02-ddc1-46cb-8684-23c70acb437f', '省試恩賜耆老布帛', '省試恩賜耆老布帛', 'aefd5b04-cbf6-42cf-b054-fcbd572793a4', '唐', '["渙汗中天發，殊私海外存。","衰顏逢聖代，華髮受皇恩。","燭物明堯日，垂衣闢禹門。","惜時悲落景，賜帛慰餘魂。","厚澤沾翔泳，微生保子孫。","盛明今尚齒，歡奉九衢罇。"]', '["渙汗中天發，殊私海外存。","衰顏逢聖代，华髮受皇恩。","燭物明堯日，垂衣闢禹门。","惜时悲落景，賜帛慰餘魂。","厚澤沾翔泳，微生保子孫。","盛明今尚齒，歡奉九衢罇。"]', '诗', 'shi', '', NULL, '省試恩賜耆老布帛 李絳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66a2150d-f0f0-479f-ac3c-b3b06cc38818', '和裴相國荅張秘書贈馬詩', '和裴相国荅張秘书贈马诗', 'aefd5b04-cbf6-42cf-b054-fcbd572793a4', '唐', '["高才名價欲凌雲，上駟光華遠贈君。","念舊露垂丞相簡，感知星動客卿文。","縱橫逸氣寧稱力，馳騁長途定出羣。","伏櫪莫令空度歲，黃金結束取功勳。"]', '["高才名價欲凌云，上駟光华远贈君。","念旧露垂丞相簡，感知星动客卿文。","縱橫逸氣寧稱力，驰騁长途定出羣。","伏櫪莫令空度歲，黄金結束取功勳。"]', '诗', 'shi', '', NULL, '和裴相國荅張秘書贈馬詩 李絳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8502f5c2-f556-45e4-a3ec-f49fc4517daa', '賜耆老布帛', '賜耆老布帛', '8dbe3c8c-8dab-48a1-b054-7fae42e059dc', '唐', '["殊私及耆老，聖德賑黎元。","布帛忻天賜，生涯作主恩。","情均皆挾纊，禮異賁丘園。","慶洽時方泰，仁沾月告存。","寧知酬雨露，空識荷乾坤。","擊壤將何幸，裴回望九門。"]', '["殊私及耆老，聖德賑黎元。","布帛忻天賜，生涯作主恩。","情均皆挾纊，禮異賁丘园。","慶洽时方泰，仁沾月告存。","寧知酬雨露，空識荷乾坤。","擊壤將何幸，裴回望九门。"]', '诗', 'shi', '', NULL, '賜耆老布帛 崔樞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc401494-86e9-4133-93fc-b5fa6e701280', '齊優開籠飛去所獻楚王鵠', '齊優开籠飞去所獻楚王鵠', '8dbe3c8c-8dab-48a1-b054-7fae42e059dc', '唐', '["受命籠齊鵠，交歡獻楚王。","惠心先巧辯，戢羽見迴翔。","意適清風遠，憂除白日長。","度雲搖舊影，過樹閱新芳。","直取名翻重，寧唯好不傷。","誰言滑稽理，千載戒禽荒。"]', '["受命籠齊鵠，交歡獻楚王。","惠心先巧辯，戢羽见迴翔。","意適清风远，憂除白日长。","度云搖旧影，過樹閱新芳。","直取名翻重，寧唯好不傷。","誰言滑稽理，千載戒禽荒。"]', '诗', 'shi', '', NULL, '齊優開籠飛去所獻楚王鵠 崔樞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b05520d2-309a-490a-8627-74508d568f42', '試中和節詔賜公卿尺詩', '試中和節詔賜公卿尺诗', '37db6b1f-1437-4873-b219-d37fbb0a8df2', '唐', '["春仲令初吉，歡娛樂大中。","皇恩貞百度，寶尺賜羣公。","欲使方隅法，還令規矩同。","捧觀珍質麗，拜受聖恩崇。","如荷丘山重，思酬方寸功。","從茲度天地，與國慶無窮。"]', '["春仲令初吉，歡娛乐大中。","皇恩貞百度，寶尺賜羣公。","欲使方隅法，還令規矩同。","捧观珍質丽，拜受聖恩崇。","如荷丘山重，思酬方寸功。","從茲度天地，與国慶無窮。"]', '诗', 'shi', '', NULL, '試中和節詔賜公卿尺詩 陸復禮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92f47c36-d77a-4ab5-b5df-893d6ea09e28', '賦得白雲起封中', '賦得白云起封中', 'd8f6e843-eba5-4e3f-b4b6-061f72a1abf8', '唐', '["千年泰山頂，雲起漢皇封。","不作奇峯狀，寧分觸石容。","爲霖雖易得，表聖自難逢。","冉冉排空上，依依疊影重。","素光非曳練，靈貺是從龍。","豈學無心出，東西任所從。"]', '["千年泰山頂，云起漢皇封。","不作奇峯狀，寧分觸石容。","爲霖雖易得，表聖自难逢。","冉冉排空上，依依叠影重。","素光非曳練，靈貺是從龙。","豈学無心出，东西任所從。"]', '诗', 'shi', '', NULL, '賦得白雲起封中 李正辭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fd38375-40cc-4666-8ab8-e46b1fd2460f', '賦得白雲起封中', '賦得白云起封中', 'bc3a6605-8854-4b2b-b262-f2af602ef160', '唐', '["英英白雲起，呈瑞出封中。","表聖寧因地，逢時豈待風。","浮光彌皎潔，流影更沖融。","自叶堯年美，誰云漢日同。","金泥光乍掩，玉檢氣潛通。","欲與非煙並，亭亭不散空。"]', '["英英白云起，呈瑞出封中。","表聖寧因地，逢时豈待风。","浮光彌皎潔，流影更沖融。","自叶堯年美，誰云漢日同。","金泥光乍掩，玉檢氣潛通。","欲與非煙並，亭亭不散空。"]', '诗', 'shi', '', NULL, '賦得白雲起封中 張嗣初 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b151a64-7aad-4661-8b12-2cd02bcb16e2', '春色滿皇州', '春色满皇州', 'bc3a6605-8854-4b2b-b262-f2af602ef160', '唐', '["何處年華好，皇州淑氣勻。","韶陽潛應律，草木暗迎春。","柳變金堤畔，蘭抽曲水濱。","輕黃垂輦道，微綠映天津。","麗景浮丹闕，晴光擁紫宸。","不知幽遠地，今日幾枝新。"]', '["何处年华好，皇州淑氣勻。","韶陽潛應律，草木暗迎春。","柳变金堤畔，蘭抽曲水濱。","轻黄垂輦道，微綠映天津。","丽景浮丹闕，晴光擁紫宸。","不知幽远地，今日幾枝新。"]', '诗', 'shi', '', NULL, '春色滿皇州 張嗣初 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8df1473f-b50e-43d1-9320-217239903d4b', '日暮碧雲合', '日暮碧云合', 'ad9f5ffe-0748-4db9-8b28-ada0fafce560', '唐', '["日際愁陰生，天涯暮雲碧。","重重不辨蓋，沈沈乍如積。","林色黯疑暝，隟光俄已夕。","出岫且從龍，縈空寧觸石。","餘輝澹瑤草，浮影凝綺席。","時景詎能留，幾思輕尺璧。"]', '["日際愁陰生，天涯暮云碧。","重重不辨蓋，沈沈乍如積。","林色黯疑暝，隟光俄已夕。","出岫且從龙，縈空寧觸石。","餘輝澹瑤草，浮影凝綺席。","时景詎能留，幾思轻尺璧。"]', '诗', 'shi', '', NULL, '日暮碧雲合 許康佐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb0d7610-5904-4de0-a7e3-7d2b3c6dd666', '白雲起封中', '白云起封中', 'ad9f5ffe-0748-4db9-8b28-ada0fafce560', '唐', '["英英白雲起，呈瑞出封中。","表聖寧依地，逢時豈待風。","浮輝彌皎潔，流影更沖融。","自叶堯天美，誰言漢日同。","泥金光乍掩，檢玉氣俄通。","猶願非煙瑞，亭亭不散空。"]', '["英英白云起，呈瑞出封中。","表聖寧依地，逢时豈待风。","浮輝彌皎潔，流影更沖融。","自叶堯天美，誰言漢日同。","泥金光乍掩，檢玉氣俄通。","猶願非煙瑞，亭亭不散空。"]', '诗', 'shi', '', NULL, '白雲起封中 許康佐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7e6ff35-96d5-4a24-961c-d06262597051', '石季倫金谷園', '石季倫金谷园', '88d58303-5fe2-46a9-841e-cc457bd7ad88', '唐', '["石氏遺文在，淒涼見故園。","輕風思奏樂，衰草憶行軒。","舞榭蒼苔掩，歌臺落葉繁。","斷雲歸舊壑，流水咽新源。","曲沼殘煙斂，叢篁宿鳥喧。","唯餘池上月，猶似對金尊。"]', '["石氏遺文在，淒涼见故园。","轻风思奏乐，衰草憶行軒。","舞榭蒼苔掩，歌台落葉繁。","斷云归旧壑，流水咽新源。","曲沼殘煙斂，叢篁宿鸟喧。","唯餘池上月，猶似对金尊。"]', '诗', 'shi', '', NULL, '石季倫金谷園 許堯佐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5627b5d9-f801-4942-9fd2-5b6b9da22dfe', '石季倫金谷園', '石季倫金谷园', '4d20b582-b8de-4698-a576-387c9c7463c6', '唐', '["梓澤風流地，淒涼跡尚存。","殘芳迷妓女，衰草憶王孫。","舞態隨人謝，歌聲寄鳥言。","池平森灌木，月落弔空園。","流水悲難駐，浮雲影自翻。","賓階餘蘚石，車馬詎喧喧。"]', '["梓澤风流地，淒涼跡尚存。","殘芳迷妓女，衰草憶王孫。","舞態隨人謝，歌声寄鸟言。","池平森灌木，月落弔空园。","流水悲难駐，浮云影自翻。","賓階餘蘚石，车马詎喧喧。"]', '诗', 'shi', '', NULL, '石季倫金谷園 李君房 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5193221-e81f-4603-9afd-26dc0e8f4583', '享惠昭太子廟樂章登歌', '享惠昭太子廟乐章登歌', '402cdba7-1f9e-4b81-ac90-26d3fa1c72ae', '唐', '["因心克孝，位震遺芬。","賓天道茂，軫懷氣分。","發祇乃祀，咳歎如聞。","二歌斯升，以詠德薰。"]', '["因心克孝，位震遺芬。","賓天道茂，軫懷氣分。","發祇乃祀，咳歎如闻。","二歌斯升，以詠德薰。"]', '诗', 'shi', '', NULL, '享惠昭太子廟樂章登歌 杜羔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b07bc6b-8022-4278-a691-a47120a1da16', '南至日隔仗望含元殿香鑪', '南至日隔仗望含元殿香鑪', '4ed10e80-5435-475c-928f-5d124bb96033', '唐', '["抗殿疏元首，高高接上元。","節當南至日，星是北辰天。","寶戟羅仙仗，金鑪引瑞煙。","霏微雙闕麗，溶曳九州連。","拂曙祥光滿，分晴曉色鮮。","一陽今在曆，生植願陶甄。"]', '["抗殿疏元首，高高接上元。","節當南至日，星是北辰天。","寶戟羅仙仗，金鑪引瑞煙。","霏微雙闕丽，溶曳九州連。","拂曙祥光满，分晴晓色鲜。","一陽今在曆，生植願陶甄。"]', '诗', 'shi', '', NULL, '南至日隔仗望含元殿香鑪 車𬘔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96df8c5c-0f1a-471f-90f7-7b785f3c9e84', '奉和聖製九月十八日賜百寮追賞因書所懷', '奉和聖製九月十八日賜百寮追賞因书所懷', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["錫宴朝野洽，追歡堯舜情。","秋堂絲管動，水榭煙霞生。","黃花媚新霽，碧樹含餘清。","同和六律應，交泰萬宇平。","春藻下中天，湛恩闡文明。","小臣諒何以，亦此彯華纓。"]', '["錫宴朝野洽，追歡堯舜情。","秋堂絲管动，水榭煙霞生。","黄花媚新霽，碧樹含餘清。","同和六律應，交泰万宇平。","春藻下中天，湛恩闡文明。","小臣諒何以，亦此彯华纓。"]', '诗', 'shi', '', NULL, '奉和聖製九月十八日賜百寮追賞因書所懷 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a142d6c-8897-4ed1-80d3-b705d9cba724', '奉和聖製九日言懷賜中書門下及百寮', '奉和聖製九日言懷賜中书门下及百寮', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["令節在豐歲，皇情喜乂安。","絲竹調六律，簪裾列千官。","煙霜暮景清，水木秋光寒。","筵開曲池上，望盡終南端。","天文麗慶霄，墨妙驚飛鸞。","願言黃花酒，永奉今日歡。"]', '["令節在豐歲，皇情喜乂安。","絲竹調六律，簪裾列千官。","煙霜暮景清，水木秋光寒。","筵开曲池上，望尽終南端。","天文丽慶霄，墨妙驚飞鸾。","願言黄花酒，永奉今日歡。"]', '诗', 'shi', '', NULL, '奉和聖製九日言懷賜中書門下及百寮 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c623213-b98c-4b41-af11-f0206208ac1e', '奉和聖製重陽日中外同歡以詩言志因示百僚', '奉和聖製重陽日中外同歡以诗言志因示百僚', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["玉醴宴嘉節，拜恩歡有餘。","煌煌菊花秀，馥馥萸房舒。","白露秋稼熟，清風天籟虛。","和聲度簫韶，瑞氣深儲胥。","百辟皆醉止，萬方今宴如。","宸衷在化成，藻思煥瓊琚。","微臣徒竊抃，豈足歌唐虞。"]', '["玉醴宴嘉節，拜恩歡有餘。","煌煌菊花秀，馥馥萸房舒。","白露秋稼熟，清风天籟虛。","和声度簫韶，瑞氣深儲胥。","百辟皆醉止，万方今宴如。","宸衷在化成，藻思煥瓊琚。","微臣徒竊抃，豈足歌唐虞。"]', '诗', 'shi', '', NULL, '奉和聖製重陽日中外同歡以詩言志因示百僚 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f2d3368-1624-4bcb-93ba-9909ff3d9eab', '奉和聖製中春麟德殿會百寮觀新樂', '奉和聖製中春麟德殿會百寮观新乐', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["仲春藹芳景，內庭宴羣臣。","森森列干戚，濟濟趨鉤陳。","大樂本天地，中和序人倫。","正聲邁咸濩，易象含羲文。","玉俎映朝服，金鈿明舞茵。","韶光雪初霽，聖藻風自薫。","時泰恩澤溥，功成行綴新。","賡歌仰昭回，竊比華封人。"]', '["仲春藹芳景，內庭宴羣臣。","森森列干戚，濟濟趨鉤陳。","大乐本天地，中和序人倫。","正声邁咸濩，易象含羲文。","玉俎映朝服，金鈿明舞茵。","韶光雪初霽，聖藻风自薫。","时泰恩澤溥，功成行綴新。","賡歌仰昭回，竊比华封人。"]', '诗', 'shi', '', NULL, '奉和聖製中春麟德殿會百寮觀新樂 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a754b0bd-8cfc-434c-b56d-17c9c02ecff4', '奉和聖製中和節賜百官宴集因示後懷', '奉和聖製中和節賜百官宴集因示後懷', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["萬方慶嘉節，宴喜皇澤均。","曉開蓂葉初，景麗星鳥春。","藻思貞百度，著明並三辰。","物情舒在陽，時令弘至仁。","衢酒和樂被，薰弦聲曲新。","賡歌武弁側，永荷玄化醇。"]', '["万方慶嘉節，宴喜皇澤均。","晓开蓂葉初，景丽星鸟春。","藻思貞百度，著明並三辰。","物情舒在陽，时令弘至仁。","衢酒和乐被，薰弦声曲新。","賡歌武弁側，永荷玄化醇。"]', '诗', 'shi', '', NULL, '奉和聖製中和節賜百官宴集因示後懷 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b8928c7-3964-4370-8eee-5426e1e25eba', '奉和聖製重陽日即事六韻', '奉和聖製重陽日即事六韻', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["嘉節在陽數，至歡朝野同。","恩隨千鍾洽，慶屬五稼豐。","時菊洗露華，秋池涵霽空。","金絲響仙樂，劒舃羅宗公。","天道光下濟，睿詞敷大中。","多慙撃壤曲，何以荅堯聰。"]', '["嘉節在陽數，至歡朝野同。","恩隨千鍾洽，慶屬五稼豐。","时菊洗露华，秋池涵霽空。","金絲响仙乐，劒舃羅宗公。","天道光下濟，睿词敷大中。","多慙撃壤曲，何以荅堯聰。"]', '诗', 'shi', '', NULL, '奉和聖製重陽日即事六韻 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c902514-da71-4264-9cce-a13f36059c29', '奉和聖制豐年多慶九日示懷', '奉和聖制豐年多慶九日示懷', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["寒露應秋杪，清光澄曙空。","澤均行葦厚，年慶華黍豐。","聲明暢八表，宴喜陶九功。","文麗日月合，樂和天地同。","聖言在推誠，臣職惟匪躬。","瑣細何以報，翾飛淳化中。"]', '["寒露應秋杪，清光澄曙空。","澤均行葦厚，年慶华黍豐。","声明暢八表，宴喜陶九功。","文丽日月合，乐和天地同。","聖言在推誠，臣職惟匪躬。","瑣細何以報，翾飞淳化中。"]', '诗', 'shi', '', NULL, '奉和聖制豐年多慶九日示懷 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e521d234-7da4-4003-95b4-dc726a6dd1ad', '贈文敬太子廟時享退文舞迎武舞樂章', '贈文敬太子廟时享退文舞迎武舞乐章', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["干旄羽籥相虧蔽，一進一退殊行綴。","昔獻三雍盛禮容，今陳六佾崇儀制。"]', '["干旄羽籥相虧蔽，一進一退殊行綴。","昔獻三雍盛禮容，今陳六佾崇儀制。"]', '诗', 'shi', '', NULL, '贈文敬太子廟時享退文舞迎武舞樂章 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fe37e01-7122-47ef-a8f6-cdfae4b5a7f1', '讀穀梁傳二首 一', '读穀梁傳二首 一', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["荀寅士吉射，誠乃蔽聰明。","奈何趙志父，專舉晉陽兵。","下令漢七國，借此以爲名。","吾嘉徙薪智，禍亂何由生。"]', '["荀寅士吉射，誠乃蔽聰明。","奈何趙志父，專舉晉陽兵。","下令漢七国，借此以爲名。","吾嘉徙薪智，禍亂何由生。"]', '诗', 'shi', '', NULL, '讀穀梁傳二首 一 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a45b0aa0-ad57-4200-8d05-5f428e88abf1', '讀穀梁傳二首 二', '读穀梁傳二首 二', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["憶昔溴梁會，豈伊無諸侯。","羣臣自盟歃，君政如贅旒。","有力則宗楚，何人復尊周。","空文徒爾貶，見此[眥]□血流。"]', '["憶昔溴梁會，豈伊無諸侯。","羣臣自盟歃，君政如贅旒。","有力則宗楚，何人复尊周。","空文徒爾貶，见此[眥]□血流。"]', '诗', 'shi', '', NULL, '讀穀梁傳二首 二 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5872eadd-43a8-4f85-9389-25746a2246bd', '劉紹相訪夜話因書即事', '劉紹相訪夜話因书即事', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["故人愴久別，茲夕欵郊扉。","山僮漉野醖，穉子褰書帷。","清露泫珠瑩，金波流玉徽。","忘言我造適，瞪視君無違。","但令靜勝躁，自使癯者肥。","不待蘧生年，從此知昔非。"]', '["故人愴久別，茲夕欵郊扉。","山僮漉野醖，穉子褰书帷。","清露泫珠瑩，金波流玉徽。","忘言我造適，瞪視君無違。","但令静勝躁，自使癯者肥。","不待蘧生年，從此知昔非。"]', '诗', 'shi', '', NULL, '劉紹相訪夜話因書即事 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bf908a6-4359-4c8a-ae66-43a5911afa29', '臥病喜惠上人李鍊師茅處士見訪因以贈', '臥病喜惠上人李鍊師茅处士见訪因以贈', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["沈疴結繁慮，臥見書窗曙。","方外三賢人，惠然來相親。","整巾起曳策，喜非車馬客。","支郎有佳文，新句淩碧雲。","霓裳何飄飄，浩志淩紫氛。","復有沈冥士，遠係三茅君。","各言麋鹿性，不與簪組羣。","清言出象繫，曠跡逃玄纁。","心源蹔澄寂，世故方糺紛。","終當逐師輩，巖桂香氳芬。"]', '["沈疴結繁慮，臥见书窗曙。","方外三賢人，惠然来相親。","整巾起曳策，喜非车马客。","支郎有佳文，新句淩碧云。","霓裳何飄飄，浩志淩紫氛。","复有沈冥士，远係三茅君。","各言麋鹿性，不與簪組羣。","清言出象繫，曠跡逃玄纁。","心源蹔澄寂，世故方糺紛。","終當逐師輩，巖桂香氳芬。"]', '诗', 'shi', '', NULL, '臥病喜惠上人李鍊師茅處士見訪因以贈 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27ad7462-8d75-4ddf-895a-94b244da9487', '多病戲書因示長孺', '多病戲书因示长孺', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["行年未四十，已覺百病生。","眼眩飛蠅影，耳厭遠蟬聲。","甘辛敗六藏，冰炭交七情。","唯思曲肱枕，搔首擲華纓。"]', '["行年未四十，已覺百病生。","眼眩飞蠅影，耳厭远蟬声。","甘辛敗六藏，冰炭交七情。","唯思曲肱枕，搔首擲华纓。"]', '诗', 'shi', '', NULL, '多病戲書因示長孺 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fdfd45f-a4ae-48c5-8127-d55223988f0d', '古興', '古兴', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["月中有桂樹，無翼難上天。","海底有龍珠，下隔萬丈淵。","人生大限雖百歲，就中三十稱一世。","晦明烏兔相推遷，雪霜漸到雙鬢邊。","沈憂戚戚多浩歎，不得如意居太半。","一氣暫聚常恐散，黃河清兮白石爛。"]', '["月中有桂樹，無翼难上天。","海底有龙珠，下隔万丈淵。","人生大限雖百歲，就中三十稱一世。","晦明烏兔相推遷，雪霜漸到雙鬢邊。","沈憂戚戚多浩歎，不得如意居太半。","一氣暫聚常恐散，黄河清兮白石爛。"]', '诗', 'shi', '', NULL, '古興 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ab6a053-a0d9-4005-a5ce-d82d72340d2a', '感寓', '感寓', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["殘雨倦欹枕，病中時序分。","秋蟲與秋葉，一夜隔窗聞。","虛室對搖落，晤言無與羣。","冥心試觀化，世故如絲棼。","但看鳶戾天，豈見山出雲。","下里徒撃節，朱弦秘南薰。","梧桐秀朝陽，上有威鳳文。","終待九成奏，來儀瑞吾君。"]', '["殘雨倦欹枕，病中时序分。","秋蟲與秋葉，一夜隔窗闻。","虛室对搖落，晤言無與羣。","冥心試观化，世故如絲棼。","但看鳶戾天，豈见山出云。","下里徒撃節，朱弦秘南薰。","梧桐秀朝陽，上有威鳳文。","終待九成奏，来儀瑞吾君。"]', '诗', 'shi', '', NULL, '感寓 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7efba240-bbd8-45d9-b687-4af3a1b140bd', '跌傷伏枕有勸醲酒者蹔忘所苦因有一絕', '跌傷伏枕有勸醲酒者蹔忘所苦因有一絕', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["一杯宜病士，四體委胡牀。","蹔得遺形處，陶然在醉鄉。"]', '["一杯宜病士，四體委胡牀。","蹔得遺形处，陶然在醉乡。"]', '诗', 'shi', '', NULL, '跌傷伏枕有勸醲酒者蹔忘所苦因有一絕 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('deedbd74-074e-49df-9161-7a524d6d2b36', '病中苦熱', '病中苦熱', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["三伏鼓洪爐，支離一病夫。","倦眠身似火，渴歠汗如珠。","悸乏心難定，沈煩氣欲無。","何時灑微雨，因與好風俱。"]', '["三伏鼓洪爐，支離一病夫。","倦眠身似火，渴歠汗如珠。","悸乏心难定，沈煩氣欲無。","何时灑微雨，因與好风俱。"]', '诗', 'shi', '', NULL, '病中苦熱 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('add678d3-b662-4c8a-836b-17c30382f378', '覽鏡見白髮數莖光鮮特異', '覽镜见白髮數莖光鲜特異', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["秋來皎潔白鬚光，試脫朝簪學酒狂。","一曲酣歌還自樂，兒孫嬉笑挽衣裳。"]', '["秋来皎潔白鬚光，試脫朝簪学酒狂。","一曲酣歌還自乐，兒孫嬉笑挽衣裳。"]', '诗', 'shi', '', NULL, '覽鏡見白髮數莖光鮮特異 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cefb93d-3695-483a-8ed9-9d15ce5d39b8', '南亭曉坐因以示璩', '南亭晓坐因以示璩', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["隱几日無事，風交松桂枝。","園廬含曉霽，草木發華姿。","跡似南山隱，官從小宰移。","萬殊同野馬，方寸即靈龜。","弱質常多病，流年近始衰。","圖書傳授處，家有一男兒。"]', '["隐几日無事，风交松桂枝。","园廬含晓霽，草木發华姿。","跡似南山隐，官從小宰移。","万殊同野马，方寸即靈龟。","弱質常多病，流年近始衰。","圖书傳授处，家有一男兒。"]', '诗', 'shi', '', NULL, '南亭曉坐因以示璩 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5d3f266-dd2f-4608-a407-2218fff81515', '竹逕偶然作', '竹逕偶然作', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["退朝此休沐，閉戶無塵氛。","杖策入幽逕，清風隨此君。","琴觴恣偃傲，蘭蕙相氛氳。","幽賞方自適，林西煙景曛。"]', '["退朝此休沐，閉戶無塵氛。","杖策入幽逕，清风隨此君。","琴觴恣偃傲，蘭蕙相氛氳。","幽賞方自適，林西煙景曛。"]', '诗', 'shi', '', NULL, '竹逕偶然作 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('350dc47e-e3c6-4f08-b35d-d71134d35578', '拜昭陵過咸陽墅', '拜昭陵過咸陽墅', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["季子乏二頃，楊雄才一廛。","伊予此南畝，數已踰前賢。","頃歲辱明命，銘勳鏤貞堅。","遂茲操書致，內顧增缺然。","乃葺場圃事，迨今三四年。","適因昭陵拜，得抵咸陽田。","田夫競致辭，鄉耋爭來前。","村盤既羅列，雞黍皆珍鮮。","古稱祿代耕，人以食爲天。","自慙廩給厚，諒使井稅先。","塗塗溝塍霧，漠漠桑柘煙。","荒蹊沒古木，精舍臨秋泉。","池籠豈所安，樵牧乃所便。","終當解纓絡，田里諧因緣。"]', '["季子乏二頃，楊雄才一廛。","伊予此南畝，數已踰前賢。","頃歲辱明命，銘勳鏤貞堅。","遂茲操书致，內顧增缺然。","乃葺場圃事，迨今三四年。","適因昭陵拜，得抵咸陽田。","田夫競致辞，乡耋爭来前。","村盤既羅列，雞黍皆珍鲜。","古稱祿代耕，人以食爲天。","自慙廩給厚，諒使井稅先。","塗塗溝塍霧，漠漠桑柘煙。","荒蹊沒古木，精舍臨秋泉。","池籠豈所安，樵牧乃所便。","終當解纓絡，田里諧因緣。"]', '诗', 'shi', '', NULL, '拜昭陵過咸陽墅 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f56195d2-9839-487d-b558-2c38488840ec', '早春南亭即事', '早春南亭即事', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["虛齋坐清晝，梅坼柳條鮮。","節候開新曆，筋骸減故年。","振衣慙艾綬，闚鏡歎華顛。","獨有開懷處，孫孩戲目前。"]', '["虛斋坐清晝，梅坼柳條鲜。","節候开新曆，筋骸減故年。","振衣慙艾綬，闚镜歎华顛。","独有开懷处，孫孩戲目前。"]', '诗', 'shi', '', NULL, '早春南亭即事 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91aec24e-d49f-4f78-a8c0-c2526f271c19', '璩授京兆府參軍戲書以示兼呈獨孤郎', '璩授京兆府參軍戲书以示兼呈独孤郎', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["見爾府中趨，初官足慰吾。","老牛還舐犢，凡鳥亦將雛。","喜至翻成感，癡來或欲殊。","因慙玉潤客，應笑此非夫。"]', '["见爾府中趨，初官足慰吾。","老牛還舐犢，凡鸟亦將雛。","喜至翻成感，癡来或欲殊。","因慙玉潤客，應笑此非夫。"]', '诗', 'shi', '', NULL, '璩授京兆府參軍戲書以示兼呈獨孤郎 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70273d46-92cd-40d2-b5c3-e4077a482d3b', '書紳詩', '书紳诗', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["和靜有真質，斯人稱最靈。","感物惑天性，觸里紛多名。","禍機生隱微，智者鑒未形。","敗禮因近習，喆人自居貞。","當令念慮端，鄙嫚不能萌。","苟非不踰矩，焉得遂性情。","謹之在事初，動用各有程。","千里起步武，彗雲自纖莖。","心源一流放，駭浪奔長鯨。","淵木苟端深，枝流則貞清。","和理通性術，悠久方昭明。","先師留中庸，可以導此生。"]', '["和静有真質，斯人稱最靈。","感物惑天性，觸里紛多名。","禍機生隐微，智者鑒未形。","敗禮因近習，喆人自居貞。","當令念慮端，鄙嫚不能萌。","苟非不踰矩，焉得遂性情。","謹之在事初，动用各有程。","千里起步武，彗云自纖莖。","心源一流放，駭浪奔长鯨。","淵木苟端深，枝流則貞清。","和理通性術，悠久方昭明。","先師留中庸，可以導此生。"]', '诗', 'shi', '', NULL, '書紳詩 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c94d51de-dc20-468d-a9ff-bc4fb0bfcc0b', '侍從遊後湖讌坐', '侍從游後湖讌坐', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["絕境殊不遠，湖塘直吾廬。","煙霞旦夕生，泛覽誠可娛。","慈顏俯見喻，輟爾詩與書。","清旭理輕舟，嬉遊散煩劬。","宿雨蕩殘燠，惠風與之俱。","心靈一開曠，機巧眇已疎。","中流有荷花，花實相芬敷。","田田綠葉映，豔豔紅姿舒。","繁香好風結，淨質清露濡。","丹霞無容輝，嫮色亦踟躕。","穠芳射水木，欹葉游龜魚。","化工若有情，生植皆不如。","輕舟任沿泝，畢景乃躊躇。","家人亦恬曠，稚齒皆忻愉。","素弦激淒清，旨酒盈罇壺。","壽觴既頻獻，樂極隨歌呼。","圓月初出海，澄輝來滿湖。","清光照酒酣，頫傾百慮無。","以茲心目暢，敵彼名利途。","輕肥何爲者，漿藿自有餘。","願銷區中累，保此湖上居。","無用誠自適，年年翫芙蕖。"]', '["絕境殊不远，湖塘直吾廬。","煙霞旦夕生，泛覽誠可娛。","慈顏俯见喻，輟爾诗與书。","清旭理轻舟，嬉游散煩劬。","宿雨蕩殘燠，惠风與之俱。","心靈一开曠，機巧眇已疎。","中流有荷花，花實相芬敷。","田田綠葉映，豔豔紅姿舒。","繁香好风結，淨質清露濡。","丹霞無容輝，嫮色亦踟躕。","穠芳射水木，欹葉游龟鱼。","化工若有情，生植皆不如。","轻舟任沿泝，畢景乃躊躇。","家人亦恬曠，稚齒皆忻愉。","素弦激淒清，旨酒盈罇壺。","壽觴既頻獻，乐極隨歌呼。","圓月初出海，澄輝来满湖。","清光照酒酣，頫傾百慮無。","以茲心目暢，敵彼名利途。","轻肥何爲者，漿藿自有餘。","願銷區中累，保此湖上居。","無用誠自適，年年翫芙蕖。"]', '诗', 'shi', '', NULL, '侍從遊後湖讌坐 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02615ab9-cfa6-48f0-8880-373d2c8bc9ab', '晨坐寓興', '晨坐寓兴', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["清晨坐虛齋，羣動寂未諠。","泊然一室內，因見萬化源。","得喪心既齊，清淨敎益敦。","境來每自愜，理勝或不言。","亭柯見榮枯，止水知清渾。","悠悠世上人，此理法難論。"]', '["清晨坐虛斋，羣动寂未諠。","泊然一室內，因见万化源。","得喪心既齊，清淨敎益敦。","境来每自愜，理勝或不言。","亭柯见榮枯，止水知清渾。","悠悠世上人，此理法难論。"]', '诗', 'shi', '', NULL, '晨坐寓興 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3966f7e4-c1d9-4f20-848b-5fab69db1d5c', '郊居歲暮因書所懷', '郊居歲暮因书所懷', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["養拙方去諠，深居絕人事。","返耕忘帝力，樂道疎代累。","翛然衡茅下，便有江海意。","寧知肉食尊，自覺儒衣貴。","煙霜當暮節，水石多幽致。","三徑日閑安，千峯對深邃。","策藜出村渡，岸幘尋古寺。","月魄清夜琴，猨聲警朝寐。","地偏芝桂長，境勝煙霞異。","獨鳥帶晴光，疎篁淨寒翠。","窗前風葉下，枕上溪雲至。","散髮對農書，齋心看道記。","清言覈名理，開卷窮精義。","求譽觀朵頤，危身陷芳餌。","紛吾守孤直，世業常恐墜。","就學緝韋編，銘心對欹器。","元和暢萬物，動植咸使遂。","素履期不渝，永懷丘中志。"]', '["養拙方去諠，深居絕人事。","返耕忘帝力，乐道疎代累。","翛然衡茅下，便有江海意。","寧知肉食尊，自覺儒衣貴。","煙霜當暮節，水石多幽致。","三徑日闲安，千峯对深邃。","策藜出村渡，岸幘尋古寺。","月魄清夜琴，猨声警朝寐。","地偏芝桂长，境勝煙霞異。","独鸟带晴光，疎篁淨寒翠。","窗前风葉下，枕上溪云至。","散髮对農书，斋心看道記。","清言覈名理，开卷窮精義。","求譽观朵頤，危身陷芳餌。","紛吾守孤直，世業常恐墜。","就学緝韋編，銘心对欹器。","元和暢万物，动植咸使遂。","素履期不渝，永懷丘中志。"]', '诗', 'shi', '', NULL, '郊居歲暮因書所懷 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e34ee41-2947-4078-930d-c337323c95eb', '暮春閑居示同志', '暮春闲居示同志', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["避諠非傲世，幽興樂郊園。","好古每開卷，居貧常閉門。","曙鐘來古寺，旭日上西軒。","稍與清境會，蹔無塵事煩。","靜看雲起滅，閑望鳥飛翻。","乍問山僧偈，時聽漁父言。","體羸諳藥性，事簡見心源。","冠帶驚年長，詩書喜道存。","小池泉脈湊，危棟燕雛喧。","風入松陰靜，花添竹影繁。","灌園輸井稅，學稼奉晨昏。","此外知何有，怡然向一罇。"]', '["避諠非傲世，幽兴乐郊园。","好古每开卷，居貧常閉门。","曙鐘来古寺，旭日上西軒。","稍與清境會，蹔無塵事煩。","静看云起滅，闲望鸟飞翻。","乍问山僧偈，时听漁父言。","體羸諳藥性，事簡见心源。","冠带驚年长，诗书喜道存。","小池泉脈湊，危棟燕雛喧。","风入松陰静，花添竹影繁。","灌园輸井稅，学稼奉晨昏。","此外知何有，怡然向一罇。"]', '诗', 'shi', '', NULL, '暮春閑居示同志 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1dbc932-5ffe-4c31-9842-3eb04250ae38', '田家即事', '田家即事', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["閑臥藜牀對落暉，翛然便覺世情非。","漠漠稻花資旅食，青青荷葉製儒衣。","山僧相訪期中飯，漁父同遊或夜歸。","待學尚平婚稼畢，渚煙溪月共忘機。"]', '["闲臥藜牀对落暉，翛然便覺世情非。","漠漠稻花資旅食，青青荷葉製儒衣。","山僧相訪期中飯，漁父同游或夜归。","待学尚平婚稼畢，渚煙溪月共忘機。"]', '诗', 'shi', '', NULL, '田家即事 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb895ffd-c47f-4f2a-9372-d537c55a2775', '寓興', '寓兴', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["弱冠無所就，百憂鍾一身。","世德既顛墜，素懷亦堙淪。","風煙隔嵩丘，羸疾滯漳濱。","昭代未通籍，豐年猶食貧。","敢求庖有魚，但慮甑生塵。","俛首愧僮僕，蹇步羞親賓。","豈伊當途者，一一由中人。","已矣勿復言，吾將問秋旻。"]', '["弱冠無所就，百憂鍾一身。","世德既顛墜，素懷亦堙淪。","风煙隔嵩丘，羸疾滯漳濱。","昭代未通籍，豐年猶食貧。","敢求庖有鱼，但慮甑生塵。","俛首愧僮僕，蹇步羞親賓。","豈伊當途者，一一由中人。","已矣勿复言，吾將问秋旻。"]', '诗', 'shi', '', NULL, '寓興 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc7ec377-73c4-4253-b590-8006ebefba2c', '浩歌', '浩歌', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["杖策出蓬蓽，浩歌秋興長。","北風吹荷衣，簫颯景氣涼。","通逵抵山郭，里巷連湖光。","孤雲淨遠峯，綠水溢芳塘。","魚鳥樂天性，雜英互芬芳。","我心獨何爲，萬慮縈中腸。","履道身未泰，主家謀不臧。","心爲世敎牽，跡寄翰墨場。","出處兩未定，羈羸空自傷。","沈憂不可裁，佇立河之梁。","晚歸茅簷下，左右陳壺觴。","獨酌復長謠，放心遊八荒。","得喪同一域，是非亦何常。","胡爲苦此生，矻矻徒自強。","乃知杯中物，可使憂患忘。","因茲謝時輩，棲息無何鄉。"]', '["杖策出蓬蓽，浩歌秋兴长。","北风吹荷衣，簫颯景氣涼。","通逵抵山郭，里巷連湖光。","孤云淨远峯，綠水溢芳塘。","鱼鸟乐天性，杂英互芬芳。","我心独何爲，万慮縈中腸。","履道身未泰，主家謀不臧。","心爲世敎牽，跡寄翰墨場。","出处兩未定，羈羸空自傷。","沈憂不可裁，佇立河之梁。","晚归茅簷下，左右陳壺觴。","独酌复长謠，放心游八荒。","得喪同一域，是非亦何常。","胡爲苦此生，矻矻徒自強。","乃知杯中物，可使憂患忘。","因茲謝时輩，棲息無何乡。"]', '诗', 'shi', '', NULL, '浩歌 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25317c49-f336-448b-9a56-2afbf5c4e049', '與道者同守庚申', '與道者同守庚申', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["洞真善救世，守夜看仙經。","俾我外持內，當茲申配庚。","齋心已恬愉，澡身自澂明。","沈沈簾幃下，靄靄燈燭清。","四支動用息，一室虛白生。","收視忘趨舍，叩齒集神靈。","伊予嗜欲寡，居常痾恙輕。","三尸既伏竄，九藏乃和平。","無令耳目勝，則使性命傾。","窅然深夜中，若與元氣幷。","釋宗稱定慧，儒師著誠明。","派分示三敎，理詣無二名。","吉祥能止止，委順則生生。","視履苟無咎，天祐期永貞。","應物智不勞，虛中理自冥。","豈資金丹術，即此駐頹齡。"]', '["洞真善救世，守夜看仙經。","俾我外持內，當茲申配庚。","斋心已恬愉，澡身自澂明。","沈沈簾幃下，靄靄灯燭清。","四支动用息，一室虛白生。","收視忘趨舍，叩齒集神靈。","伊予嗜欲寡，居常痾恙轻。","三尸既伏竄，九藏乃和平。","無令耳目勝，則使性命傾。","窅然深夜中，若與元氣幷。","釋宗稱定慧，儒師著誠明。","派分示三敎，理詣無二名。","吉祥能止止，委順則生生。","視履苟無咎，天祐期永貞。","應物智不勞，虛中理自冥。","豈資金丹術，即此駐頹齡。"]', '诗', 'shi', '', NULL, '與道者同守庚申 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fefe96e-e5b5-4787-92c5-d94cac659653', '丙庚歲苦貧戲題', '丙庚歲苦貧戲題', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["清朝起藜牀，雪霜對枯籬。","家人來告予，今日無晨炊。","鹺醯一已整，薪炭固難期。","厚生彼何人，工拙各異宜。","間歲從使檄，親賓苦川馳。","雖非悖而[入]□，[與出]□□常相随。","吳門與南畝，頗亦持鎡基。","有時[遇豐年]□□□，歲計猶不支。","顏淵諒賢人，陋巷能自怡。","[中憶裴]□□□子野，泰然傾薄糜。","愧非古人心，戚戚愁[朝飢]□□。","[近]□古猶不及，太上那可希。","奈何時風扇，使[我正性]□□□衰。","巧智競憂勞，展轉生澆漓。","吾觀黃金[印]□，[未]□勝青松枝。","麤令有魚菽，豈復求輕肥。","顧慙[主家]□□拙，甘使羣下嗤。","如何致一杯，醉後無所知。"]', '["清朝起藜牀，雪霜对枯籬。","家人来告予，今日無晨炊。","鹺醯一已整，薪炭固难期。","厚生彼何人，工拙各異宜。","间歲從使檄，親賓苦川驰。","雖非悖而[入]□，[與出]□□常相随。","吳门與南畝，頗亦持鎡基。","有时[遇豐年]□□□，歲計猶不支。","顏淵諒賢人，陋巷能自怡。","[中憶裴]□□□子野，泰然傾薄糜。","愧非古人心，戚戚愁[朝飢]□□。","[近]□古猶不及，太上那可希。","奈何时风扇，使[我正性]□□□衰。","巧智競憂勞，展轉生澆漓。","吾观黄金[印]□，[未]□勝青松枝。","麤令有鱼菽，豈复求轻肥。","顧慙[主家]□□拙，甘使羣下嗤。","如何致一杯，醉後無所知。"]', '诗', 'shi', '', NULL, '丙庚歲苦貧戲題 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1195763f-2db9-4952-9590-484f779faed8', '獨酌', '独酌', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["獨酌復獨酌，滿盞流霞色。","身外皆虛名，酒中有全德。","風清與月朗，對此情何極。"]', '["独酌复独酌，满盞流霞色。","身外皆虛名，酒中有全德。","风清與月朗，对此情何極。"]', '诗', 'shi', '', NULL, '獨酌 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a13f6647-8e74-49a0-9eac-d66cba88be77', '知非', '知非', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["名敎自可樂，搢紳貴行道。","何必學狂歌，深山對豐草。"]', '["名敎自可乐，搢紳貴行道。","何必学狂歌，深山对豐草。"]', '诗', 'shi', '', NULL, '知非 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef17370a-d05e-4929-bbcf-fc07a197c13a', '誡言', '誡言', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["言之或未行，前哲所不取。","方寸雖浩然，因之三緘口。"]', '["言之或未行，前哲所不取。","方寸雖浩然，因之三緘口。"]', '诗', 'shi', '', NULL, '誡言 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5afbc76d-f8df-433e-afd9-427578401a1d', '醉後', '醉後', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["美祿與賢人，相逢自可親。","願將花柳月，盡賞醉鄉春。"]', '["美祿與賢人，相逢自可親。","願將花柳月，尽賞醉乡春。"]', '诗', 'shi', '', NULL, '醉後 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('576d674f-e294-45b1-9cf7-d99a379caf43', '奉和李相公早朝於中書候傳點偶書所懷奉呈門下相公中書相公', '奉和李相公早朝於中书候傳点偶书所懷奉呈门下相公中书相公', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["五更鐘漏歇，千門扃鑰開。","紫宸殘月下，黃道曉光來。","辨色趨中禁，分班列上台。","祥煙初繚繞，威鳳正裴回。","斧藻歸全德，輪轅適衆材。","化成風偃草，道合鼎調梅。","渥命隨三接，皇恩暢九垓。","嘉言造膝去，喜氣沃心迴。","東閣延多士，南山賦有臺。","陽春那敢和，空此詠康哉。"]', '["五更鐘漏歇，千门扃鑰开。","紫宸殘月下，黄道晓光来。","辨色趨中禁，分班列上台。","祥煙初繚繞，威鳳正裴回。","斧藻归全德，輪轅適衆材。","化成风偃草，道合鼎調梅。","渥命隨三接，皇恩暢九垓。","嘉言造膝去，喜氣沃心迴。","东閣延多士，南山賦有台。","陽春那敢和，空此詠康哉。"]', '诗', 'shi', '', NULL, '奉和李相公早朝於中書候傳點偶書所懷奉呈門下相公中書相公 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0b13a02-62ae-42fe-a743-ab4eb09cb744', '奉和于司空二十五丈新卜城南郊居接司徒公別墅即事書情奉獻兼呈李裴相公', '奉和于司空二十五丈新卜城南郊居接司徒公別墅即事书情奉獻兼呈李裴相公', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["一德承昌運，三公翊至尊。","雲龍諧理代，魚水見深恩。","別墅池塘曉，晴郊草木蕃。","溝塍連杜曲，茅土盛于門。","卜築因登覽，經邦每討論。","退朝鳴玉會，入室斷金言。","材俊依東閣，壺觴接後園。","逕深雲自起，風靜葉初翻。","宰物歸心匠，虛中即化源。","巴人寧敢和，空此媿遊藩。"]', '["一德承昌運，三公翊至尊。","云龙諧理代，鱼水见深恩。","別墅池塘晓，晴郊草木蕃。","溝塍連杜曲，茅土盛于门。","卜築因登覽，經邦每討論。","退朝鳴玉會，入室斷金言。","材俊依东閣，壺觴接後园。","逕深云自起，风静葉初翻。","宰物归心匠，虛中即化源。","巴人寧敢和，空此媿游藩。"]', '诗', 'shi', '', NULL, '奉和于司空二十五丈新卜城南郊居接司徒公別墅即事書情奉獻兼呈李裴相公 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('302ea12d-1497-4d4f-b3f4-86c7c4574197', '奉和新卜城南郊居得與衛右丞鄰舍因賦詩寄贈', '奉和新卜城南郊居得與衛右丞鄰舍因賦诗寄贈', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["上宰坐論道，郊居仍里仁。","六符既昭晰，萬象隨陶鈞。","旭旦下玉墀，鳴騶拂車茵。","軒窗退殘暑，風物迎蕭辰。","山澤蜃雨出，林塘魚鳥馴。","豈同求羊逕，共是羲皇人。","石君五曹重，左戶三壤均。","居止煙火接，逢迎雞黍頻。","大方本無隅，盛德必有鄰。","千年郢曲後，復此聞陽春。"]', '["上宰坐論道，郊居仍里仁。","六符既昭晰，万象隨陶鈞。","旭旦下玉墀，鳴騶拂车茵。","軒窗退殘暑，风物迎蕭辰。","山澤蜃雨出，林塘鱼鸟馴。","豈同求羊逕，共是羲皇人。","石君五曹重，左戶三壤均。","居止煙火接，逢迎雞黍頻。","大方本無隅，盛德必有鄰。","千年郢曲後，复此闻陽春。"]', '诗', 'shi', '', NULL, '奉和新卜城南郊居得與衛右丞鄰舍因賦詩寄贈 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cc49168-b18c-4c44-aef6-a559c2a407e5', '奉和韋曲莊言懷貽東曲外族諸弟', '奉和韋曲莊言懷貽东曲外族諸弟', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["韋曲冠蓋里，鮮原鬱青蔥。","公台睦中外，墅舍鄰西東。","騶馭出國門，晨曦正曈曨。","燕居平外土，野服參華蟲。","疆畎分古渠，煙霞連灌叢。","長幼序以齒，歡言無不同。","憶昔全盛時，勛劬播休功。","代業擴宇內，光塵藹墟中。","慨息多永歎，歌詩厚時風。","小生忝瓜葛，慕義斯無窮。"]', '["韋曲冠蓋里，鲜原鬱青蔥。","公台睦中外，墅舍鄰西东。","騶馭出国门，晨曦正曈曨。","燕居平外土，野服參华蟲。","疆畎分古渠，煙霞連灌叢。","长幼序以齒，歡言無不同。","憶昔全盛时，勛劬播休功。","代業擴宇內，光塵藹墟中。","慨息多永歎，歌诗厚时风。","小生忝瓜葛，慕義斯無窮。"]', '诗', 'shi', '', NULL, '奉和韋曲莊言懷貽東曲外族諸弟 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6adac152-9779-40b7-a7dd-58a4144a7845', '和王侍郎病中領度支煩迫之餘過西園書堂閑望', '和王侍郎病中領度支煩迫之餘過西园书堂闲望', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["憑檻輟繁務，晴光煙樹分。","中邦均禹貢，上藥驗桐君。","滿逕風轉蕙，卷簾山出雲。","鏘然玉音發，餘興在斯文。"]', '["憑檻輟繁務，晴光煙樹分。","中邦均禹貢，上藥驗桐君。","满逕风轉蕙，卷簾山出云。","鏘然玉音發，餘兴在斯文。"]', '诗', 'shi', '', NULL, '和王侍郎病中領度支煩迫之餘過西園書堂閑望 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('693a0842-0d81-45fc-a1af-5539ffc88e39', '奉和度支李侍郎早朝', '奉和度支李侍郎早朝', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["夙駕趨北闕，曉星啓東方。","鳴騶分騎吏，列燭散康莊。","照灼華簪並，逶迤綺陌長。","腰金初辨色，噴玉自生光。","獻替均三壤，貞明集百祥。","下才叨接武，空此媿文昌。"]', '["夙駕趨北闕，晓星啓东方。","鳴騶分騎吏，列燭散康莊。","照灼华簪並，逶迤綺陌长。","腰金初辨色，噴玉自生光。","獻替均三壤，貞明集百祥。","下才叨接武，空此媿文昌。"]', '诗', 'shi', '', NULL, '奉和度支李侍郎早朝 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bb587f0-50bf-4a26-888f-60b5aa12bcc2', '奉和劉侍郎司徒奉詔伐叛書情呈宰相', '奉和劉侍郎司徒奉詔伐叛书情呈宰相', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["玉帳元侯重，黃樞上宰雄。","緣情詞律外，宣力廟謀中。","震耀恭天討，嚴凝助歲功。","行看畫麟閣，凜凜有英風。"]', '["玉帳元侯重，黄樞上宰雄。","緣情词律外，宣力廟謀中。","震耀恭天討，嚴凝助歲功。","行看畫麟閣，凜凜有英风。"]', '诗', 'shi', '', NULL, '奉和劉侍郎司徒奉詔伐叛書情呈宰相 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bad7958c-eafc-4acb-8c6a-663f745cb133', '奉和鄜州劉大夫麥秋出師遮虜有懷中朝親故', '奉和鄜州劉大夫麦秋出師遮虜有懷中朝親故', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["天子愛全才，故人雄外臺。","綠油登上將，青綬亞中台。","亭障鳴笳入，風雲轉斾來。","蘭坊分杳杳，麥壠望莓莓。","月向琱弓滿，蓮依寶劒開。","行師齊鶴列，錫馬盡龍媒。","壯志徵梁甫，嘉招萃楚材。","千尋推直幹，百鍊去纖埃。","間闊勞相望，歡言幸早陪。","每聯花下騎，幾泛竹間杯。","芳訊雙魚遠，流年兩鬢催。","何時介圭覲，攜手詠康哉。"]', '["天子愛全才，故人雄外台。","綠油登上將，青綬亞中台。","亭障鳴笳入，风云轉斾来。","蘭坊分杳杳，麦壠望莓莓。","月向琱弓满，蓮依寶劒开。","行師齊鹤列，錫马尽龙媒。","壯志徵梁甫，嘉招萃楚材。","千尋推直幹，百鍊去纖埃。","间闊勞相望，歡言幸早陪。","每聯花下騎，幾泛竹间杯。","芳訊雙鱼远，流年兩鬢催。","何时介圭覲，携手詠康哉。"]', '诗', 'shi', '', NULL, '奉和鄜州劉大夫麥秋出師遮虜有懷中朝親故 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ec3cb79-610a-41c8-ac87-601a64b29d72', '太原鄭尚書遠寄新詩走筆酬贈因代書賀', '太原鄭尚书远寄新诗走笔酬贈因代书賀', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["曉開閶闔出絲言，共喜全才鎮北門。","職重油幢推上略，榮兼革履見深恩。","昔歲經過同二仲，登朝並命慙無用。","曲臺分季奉齋祠，直筆繫年陪侍從。","芬芳雞舌向南宮，伏奏丹墀跡又同。","公望數承黃紙詔，虛懷自號白雲翁。","戎裝躞蹀紛出祖，金印煌煌寵司武。","時看介士閱犀渠，每狎儒生冠章甫。","晉祠汾水古幷州，千騎雙旌居上頭。","新握兵符應感激，遠緘詩句更風流。","緇衣諸侯諒稱美，白衣尚書何可比。","只今麟閣待丹青，努力加餐報天子。"]', '["晓开閶闔出絲言，共喜全才鎮北门。","職重油幢推上略，榮兼革履见深恩。","昔歲經過同二仲，登朝並命慙無用。","曲台分季奉斋祠，直笔繫年陪侍從。","芬芳雞舌向南宮，伏奏丹墀跡又同。","公望數承黄紙詔，虛懷自號白云翁。","戎裝躞蹀紛出祖，金印煌煌寵司武。","时看介士閱犀渠，每狎儒生冠章甫。","晉祠汾水古幷州，千騎雙旌居上头。","新握兵符應感激，远緘诗句更风流。","緇衣諸侯諒稱美，白衣尚书何可比。","只今麟閣待丹青，努力加餐報天子。"]', '诗', 'shi', '', NULL, '太原鄭尚書遠寄新詩走筆酬贈因代書賀 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fcbc9fd-9c0f-4ecd-a97b-0a996f02acb7', '奉和許閣老酬淮南崔十七端公見寄', '奉和許閣老酬淮南崔十七端公见寄', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["文行蘊良圖，聲華挹大巫。","掄才超粉署，駮議在黃樞。","自得環中辨，偏推席上儒。","八音諧雅樂，六轡騁康衢。","密侍仝鏘珮，雄才本棄繻。","爐煙霏瑣闥，宮漏滴銅壺。","舊友雙魚至，新文六義敷。","斷金揮麗藻，比玉詠生芻。","交辟嘗推重，單辭忽受誣。","風波疲賈誼，岐路泣楊朱。","溟漲前程險，炎荒旅夢孤。","空悲鳶跕水，翻羨鴈銜蘆。","故國方迢遰，羈愁自鬱紆。","遠猷來象魏，霈澤過番禺。","盡室扁舟客，還家萬里途。","索居因仕宦，著論擬潛夫。","帆席來應駛，郊園半已蕪。","夕陽尋古逕，涼吹動纖枯。","憶昔同驅傳，忘懷或據梧。","幕庭依古剎，緡稅給中都。","瓜步經過慣，龍沙眺聽殊。","春山嵐漠漠，秋渚露塗塗。","孰謂原思病，非關甯武愚。","方看簪獬豸，俄歎縶騊駼。","芳訊風情在，佳期歲序徂。","二賢歡最久，三益義非無。","柏悅心應爾，松寒志不渝。","子將陪禁掖，亭伯限江湖。","交分終推轂，離憂莫向隅。","分曹日相見，延首憶田蘇。"]', '["文行蘊良圖，声华挹大巫。","掄才超粉署，駮議在黄樞。","自得环中辨，偏推席上儒。","八音諧雅乐，六轡騁康衢。","密侍仝鏘珮，雄才本棄繻。","爐煙霏瑣闥，宮漏滴銅壺。","旧友雙鱼至，新文六義敷。","斷金揮丽藻，比玉詠生芻。","交辟嘗推重，單辞忽受誣。","风波疲賈誼，岐路泣楊朱。","溟漲前程險，炎荒旅梦孤。","空悲鳶跕水，翻羨鴈銜蘆。","故国方迢遰，羈愁自鬱紆。","远猷来象魏，霈澤過番禺。","尽室扁舟客，還家万里途。","索居因仕宦，著論擬潛夫。","帆席来應駛，郊园半已蕪。","夕陽尋古逕，涼吹动纖枯。","憶昔同驱傳，忘懷或據梧。","幕庭依古剎，緡稅給中都。","瓜步經過慣，龙沙眺听殊。","春山嵐漠漠，秋渚露塗塗。","孰謂原思病，非关甯武愚。","方看簪獬豸，俄歎縶騊駼。","芳訊风情在，佳期歲序徂。","二賢歡最久，三益義非無。","柏悅心應爾，松寒志不渝。","子將陪禁掖，亭伯限江湖。","交分終推轂，離憂莫向隅。","分曹日相见，延首憶田蘇。"]', '诗', 'shi', '', NULL, '奉和許閣老酬淮南崔十七端公見寄 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4be0f59-bf02-4900-a8e2-6bba2e0f9cd8', '奉和李給事省中書情寄劉苗崔三曹長因呈許陳二閣老', '奉和李給事省中书情寄劉苗崔三曹长因呈許陳二閣老', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["常寮幾處伏明光，新詔聯翩夕拜郎。","五夜漏清天欲曙，萬年枝暖日初長。","分曹列侍登文石，促膝閑謠接羽觴。","共說漢朝榮上賞，豈令三友滯馮唐。"]', '["常寮幾处伏明光，新詔聯翩夕拜郎。","五夜漏清天欲曙，万年枝暖日初长。","分曹列侍登文石，促膝闲謠接羽觴。","共说漢朝榮上賞，豈令三友滯馮唐。"]', '诗', 'shi', '', NULL, '奉和李給事省中書情寄劉苗崔三曹長因呈許陳二閣老 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b25f5fac-fce1-471d-bf7a-3de59c7a6337', '過張監閣老宅對酒奉酬見贈', '過張監閣老宅对酒奉酬见贈', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["里仁無外事，徐步一開顏。","荆玉收難盡，齊竽喜暫閑。","秋風傾菊酒，霽景下蓬山。","不用投車轄，甘從倒載還。"]', '["里仁無外事，徐步一开顏。","荆玉收难尽，齊竽喜暫闲。","秋风傾菊酒，霽景下蓬山。","不用投车轄，甘從倒載還。"]', '诗', 'shi', '', NULL, '過張監閣老宅對酒奉酬見贈 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2aabe1f5-d767-4f15-b802-18717c5bfb86', '奉和張舍人閣老閣中直夜思聞雅琴因以書事通簡僚友', '奉和張舍人閣老閣中直夜思闻雅琴因以书事通簡僚友', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["紫垣宿清夜，藹藹復沈沈。","圓月衡漢淨，好風松滌深。","軒窗韻虛籟，蘭雪懷幽音。","珠露銷暑氣，玉徽結遐心。","盛才本殊倫，雅誥方在今。","佇見舒彩翮，翻飛歸鳳林。"]', '["紫垣宿清夜，藹藹复沈沈。","圓月衡漢淨，好风松滌深。","軒窗韻虛籟，蘭雪懷幽音。","珠露銷暑氣，玉徽結遐心。","盛才本殊倫，雅誥方在今。","佇见舒彩翮，翻飞归鳳林。"]', '诗', 'shi', '', NULL, '奉和張舍人閣老閣中直夜思聞雅琴因以書事通簡僚友 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e511cab-22be-4eaf-bb9e-13bdccd5a8d7', '和兵部李尚書東亭詩', '和兵部李尚书东亭诗', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["三接履聲退，東亭斯曠然。","風流披鶴氅，操割佩龍泉。","雲卷巖巘疊，雨餘松桂鮮。","豈煩禽尚遊，所貴天理全。"]', '["三接履声退，东亭斯曠然。","风流披鹤氅，操割佩龙泉。","云卷巖巘叠，雨餘松桂鲜。","豈煩禽尚游，所貴天理全。"]', '诗', 'shi', '', NULL, '和兵部李尚書東亭詩 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adf0c2fc-4c31-4f42-9a62-08d58d8ac0e0', '和司門殷員外早秋省中書直夜寄荆南衛象端公', '和司门殷員外早秋省中书直夜寄荆南衛象端公', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["共嗟王粲滯荆州，才子爲郎憶舊遊。","涼夜偏宜粉署直，清言遠待玉人酬。","風生北渚煙波闊，露下南宮星漢秋。","早晚得爲同舍侶，知君兩地結離憂。"]', '["共嗟王粲滯荆州，才子爲郎憶旧游。","涼夜偏宜粉署直，清言远待玉人酬。","风生北渚煙波闊，露下南宮星漢秋。","早晚得爲同舍侶，知君兩地結離憂。"]', '诗', 'shi', '', NULL, '和司門殷員外早秋省中書直夜寄荆南衛象端公 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f03f7085-be14-4c97-b540-77f2e8fa5811', '酬陸三十二參浙東見寄', '酬陸三十二參浙东见寄', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["驄馬別已久，鯉魚來自烹。","殷懃故人意，怊悵中林情。","茫茫重江外，杳杳一枝瓊。","搔首望良覿，爲君華髮生。"]', '["驄马別已久，鯉鱼来自烹。","殷懃故人意，怊悵中林情。","茫茫重江外，杳杳一枝瓊。","搔首望良覿，爲君华髮生。"]', '诗', 'shi', '', NULL, '酬陸三十二參浙東見寄 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ca9a7ec-615d-40a3-8bb4-bb3a0e4dc79e', '奉酬張監閣老雪後過中書見贈加兩韻簡南省僚舊', '奉酬張監閣老雪後過中书见贈加兩韻簡南省僚旧', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["寓直久叨榮，新恩倍若驚。","風清五夜永，節換一陽生。","潘鬢年空長，齊竽藝本輕。","常時望連茹，今日劇懸旌。","枉步歡方接，含毫思又縈。","煩君白雪句，歲晏若爲情。"]', '["寓直久叨榮，新恩倍若驚。","风清五夜永，節換一陽生。","潘鬢年空长，齊竽藝本轻。","常时望連茹，今日劇懸旌。","枉步歡方接，含毫思又縈。","煩君白雪句，歲晏若爲情。"]', '诗', 'shi', '', NULL, '奉酬張監閣老雪後過中書見贈加兩韻簡南省僚舊 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fe10fdc-cd5e-4562-a7b2-2f6361695fa9', '酬主客仲員外見賀正除', '酬主客仲員外见賀正除', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["五年承乏奉如綸，才薄那堪侍從臣。","禁署獨聞清漏曉，命書慙對紫泥新。","周班每喜簪裾接，郢曲偏宜諷詠頻。","憶昔曲臺嘗議禮，見君論著最相親。"]', '["五年承乏奉如綸，才薄那堪侍從臣。","禁署独闻清漏晓，命书慙对紫泥新。","周班每喜簪裾接，郢曲偏宜諷詠頻。","憶昔曲台嘗議禮，见君論著最相親。"]', '诗', 'shi', '', NULL, '酬主客仲員外見賀正除 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87bc3c81-8852-4d74-9a63-965bec0fd17b', '奉和太府韋卿閣老左藏庫中假山之作', '奉和太府韋卿閣老左藏庫中假山之作', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["春山仙掌百花開，九棘腰金有上才。","忽向庭中摹峻極，如從洞裏見昭回。","小松已負干霄狀，片石皆疑縮地來。","都內今朝似方外，仍傳麗曲寄雲臺。"]', '["春山仙掌百花开，九棘腰金有上才。","忽向庭中摹峻極，如從洞裏见昭回。","小松已負干霄狀，片石皆疑縮地来。","都內今朝似方外，仍傳丽曲寄云台。"]', '诗', 'shi', '', NULL, '奉和太府韋卿閣老左藏庫中假山之作 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f69baba-03d2-488d-b585-db29502e5d1c', '奉和崔評事寄外甥劉同州幷呈杜賓客許給事王侍郎昆弟楊少尹李侍御幷見寄之作', '奉和崔評事寄外甥劉同州幷呈杜賓客許給事王侍郎昆弟楊少尹李侍御幷见寄之作', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["芳訊來江湖，開緘粲瑤碧。","詩因乘黃贈，才擅雕龍格。","深陳名敎本，諒以仁義積。","藻思成采章，雅音聞皦繹。","清時左馮翊，貴士二千石。","前日應星文，今茲敞華戟。","謝公嘗乞墅，甯氏終相宅。","往歲疲草玄，忘年齊舉白。","酒酣吟更苦，夜艾談方劇。","棗巷風雨秋，石頭煙水夕。","多逢長者轍，不屑諸公辟。","酷似仰牢之，雄詞挹亭伯。","老驥念千里，飢鷹舒六翮。","叵能捨郊扉，來偶朝中客。"]', '["芳訊来江湖，开緘粲瑤碧。","诗因乘黄贈，才擅雕龙格。","深陳名敎本，諒以仁義積。","藻思成采章，雅音闻皦繹。","清时左馮翊，貴士二千石。","前日應星文，今茲敞华戟。","謝公嘗乞墅，甯氏終相宅。","往歲疲草玄，忘年齊舉白。","酒酣吟更苦，夜艾談方劇。","棗巷风雨秋，石头煙水夕。","多逢长者轍，不屑諸公辟。","酷似仰牢之，雄词挹亭伯。","老驥念千里，飢鷹舒六翮。","叵能捨郊扉，来偶朝中客。"]', '诗', 'shi', '', NULL, '奉和崔評事寄外甥劉同州幷呈杜賓客許給事王侍郎昆弟楊少尹李侍御幷見寄之作 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f10668fa-ca18-4fa7-92ff-d0cb7bdc2798', '和職方殷郎中留滯江漢初至南宮呈諸公幷見寄', '和職方殷郎中留滯江漢初至南宮呈諸公幷见寄', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["十載別文昌，藩符寄武當。","師貞上介辟，恩擢正員郎。","藻思煙霞麗，歸軒印綬光。","還希駐輦問，莫自嘆馮唐。"]', '["十載別文昌，藩符寄武當。","師貞上介辟，恩擢正員郎。","藻思煙霞丽，归軒印綬光。","還希駐輦问，莫自嘆馮唐。"]', '诗', 'shi', '', NULL, '和職方殷郎中留滯江漢初至南宮呈諸公幷見寄 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8dff86ea-eb2f-42d3-8337-c68572d2f3c3', '奉酬從兄南仲見示十九韻', '奉酬從兄南仲见示十九韻', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["晉季天下亂，安丘佐關中。","德輝靄家牒，侯籍推時功。","簪纓盛西州，清白傳素風。","逢時有舒卷，繕性無窮通。","吾兄挺奇資，向晦道自充。","耕鑿汝山下，退然安困蒙。","詩成三百篇，儒有一畝宮。","琴書滿座右，芝朮生牆東。","麗藻粲相鮮，晨輝豔芳叢。","清光杳無際，皓魄流霜空。","邦有賢諸侯，主盟詞律雄。","薦賢比文舉，理郡邁文翁。","樓中賞不獨，池畔醉每同。","聖朝闢四門，發跡貴名公。","小生何爲者，往歲學雕蟲。","華簪映武弁，一年被微躬。","開緘捧新詩，瓊玉寒青葱。","謬進空內訟，結懷遠忡忡。","時來無自疑，刷翮摩蒼穹。"]', '["晉季天下亂，安丘佐关中。","德輝靄家牒，侯籍推时功。","簪纓盛西州，清白傳素风。","逢时有舒卷，繕性無窮通。","吾兄挺奇資，向晦道自充。","耕鑿汝山下，退然安困蒙。","诗成三百篇，儒有一畝宮。","琴书满座右，芝朮生牆东。","丽藻粲相鲜，晨輝豔芳叢。","清光杳無際，皓魄流霜空。","邦有賢諸侯，主盟词律雄。","薦賢比文舉，理郡邁文翁。","楼中賞不独，池畔醉每同。","聖朝闢四门，發跡貴名公。","小生何爲者，往歲学雕蟲。","华簪映武弁，一年被微躬。","开緘捧新诗，瓊玉寒青葱。","謬進空內訟，結懷远忡忡。","时来無自疑，刷翮摩蒼穹。"]', '诗', 'shi', '', NULL, '奉酬從兄南仲見示十九韻 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41eabf19-587b-48be-ab2d-d3eef3fa6b9c', '酬崔千牛四郎早秋見寄', '酬崔千牛四郎早秋见寄', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["浩歌坐虛室，庭樹生涼風。","碧雲滅奇彩，白露萎芳叢。","感此時物變，悠然遐想通。","偶來被簪組，自覺如池龍。","少年才藻新，金鼎世業崇。","鳳文已彪炳，瓊樹何青蔥。","聯鑣長安道，接武承明宮。","君登玉墀上，我侍彤庭中。","疲病多內愧，切磋常見同。","起予覽新詩，逸韻凌秋空。","相愛每不足，因茲寓深衷。"]', '["浩歌坐虛室，庭樹生涼风。","碧云滅奇彩，白露萎芳叢。","感此时物变，悠然遐想通。","偶来被簪組，自覺如池龙。","少年才藻新，金鼎世業崇。","鳳文已彪炳，瓊樹何青蔥。","聯鑣长安道，接武承明宮。","君登玉墀上，我侍彤庭中。","疲病多內愧，切磋常见同。","起予覽新诗，逸韻凌秋空。","相愛每不足，因茲寓深衷。"]', '诗', 'shi', '', NULL, '酬崔千牛四郎早秋見寄 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28667b89-30c5-4ddf-af7f-f3acaec11dbc', '酬靈徹上人以詩代書見寄', '酬靈徹上人以诗代书见寄', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["蓮花出水地無塵，中有南宗了義人。","已取貝多翻半字，還將陽燄諭三身。","碧雲飛處詩偏麗，白月圓時信本真。","更喜開緘銷熱惱，西方社裏舊相親。"]', '["蓮花出水地無塵，中有南宗了義人。","已取貝多翻半字，還將陽燄諭三身。","碧云飞处诗偏丽，白月圓时信本真。","更喜开緘銷熱惱，西方社裏旧相親。"]', '诗', 'shi', '', NULL, '酬靈徹上人以詩代書見寄 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47c3e3e3-d13c-4562-a582-caee84ee60f5', '酬蔡十二博士見寄四韻', '酬蔡十二博士见寄四韻', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["蕪城十年別，蓬轉居不足。","終歲白屋貧，獨謠清酒聖。","風塵韋帶減，霜雪松心勁。","何以浣相思，啓元能盡性。"]', '["蕪城十年別，蓬轉居不足。","終歲白屋貧，独謠清酒聖。","风塵韋带減，霜雪松心勁。","何以浣相思，啓元能尽性。"]', '诗', 'shi', '', NULL, '酬蔡十二博士見寄四韻 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc256848-2b70-483c-9247-71f44b705772', '戲和三韻', '戲和三韻', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["墨翟突不黔，范丹甑生塵。","君今復勞歌，鶴髮吹濕薪。","前詔許真秩，何如巾軟輪。"]', '["墨翟突不黔，范丹甑生塵。","君今复勞歌，鹤髮吹濕薪。","前詔許真秩，何如巾軟輪。"]', '诗', 'shi', '', NULL, '戲和三韻 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95325255-c38d-4a92-89ac-39205e88a187', '李十韶州寄途中絕句使者取報修書之際口號酬贈', '李十韶州寄途中絕句使者取報修书之際口號酬贈', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["詔下忽臨山水郡，不妨從事恣攀登。","莫言向北千行鴈，別有圖南六月鵬。"]', '["詔下忽臨山水郡，不妨從事恣攀登。","莫言向北千行鴈，別有圖南六月鵬。"]', '诗', 'shi', '', NULL, '李十韶州寄途中絕句使者取報修書之際口號酬贈 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e0958c1-07da-4a0e-9d69-9e7ff90b42c0', '崔四郎協律以詩見寄兼惠蜀琴因以酬贈', '崔四郎協律以诗见寄兼惠蜀琴因以酬贈', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["臨風結煩想，客至傳好音。","白雪緘郢曲，朱弦亘蜀琴。","泠泠響幽韻，欵欵寄遐心。","歲晚何以報，與君期斷金。"]', '["臨风結煩想，客至傳好音。","白雪緘郢曲，朱弦亘蜀琴。","泠泠响幽韻，欵欵寄遐心。","歲晚何以報，與君期斷金。"]', '诗', 'shi', '', NULL, '崔四郎協律以詩見寄兼惠蜀琴因以酬贈 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f17b3820-4da8-4199-a31b-1cb09d6b1cf9', '酬馮絳州早秋絳臺感懷見寄', '酬馮絳州早秋絳台感懷见寄', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["良牧閑無事，層臺思眇然。","六條縈印綬，三晉辨山川。","洗嫧謳謠合，開襟眺聽偏。","秋光連大鹵，霽景下新田。","葉落徑庭樹，人歸曲沃煙。","武符頒美化，亥字訪疑年。","經術推多識，卿曹亦累遷。","齋祠常並冕，官品每差肩。","按部青絲騎，裁詩白露天。","知音媿相訪，商洛正閑眠。"]', '["良牧闲無事，層台思眇然。","六條縈印綬，三晉辨山川。","洗嫧謳謠合，开襟眺听偏。","秋光連大鹵，霽景下新田。","葉落徑庭樹，人归曲沃煙。","武符頒美化，亥字訪疑年。","經術推多識，卿曹亦累遷。","斋祠常並冕，官品每差肩。","按部青絲騎，裁诗白露天。","知音媿相訪，商洛正闲眠。"]', '诗', 'shi', '', NULL, '酬馮絳州早秋絳臺感懷見寄 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3670d47-5a12-4688-84ed-0eb055ad95a7', '酬趙尚書杏園花下醉後見寄', '酬趙尚书杏园花下醉後见寄', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["春光深處曲江西，八座風流信馬蹄。","鶴髮杏花相映好，羨君終日醉如泥。"]', '["春光深处曲江西，八座风流信马蹄。","鹤髮杏花相映好，羨君終日醉如泥。"]', '诗', 'shi', '', NULL, '酬趙尚書杏園花下醉後見寄 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cce2d4e2-5c21-4319-9b7e-10174f10519d', '酬趙尚書城南看花日晚先歸見寄', '酬趙尚书城南看花日晚先归见寄', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["杜城韋曲徧尋春，處處繁花滿目新。","日暮歸鞍不相待，與君同是醉鄉人。"]', '["杜城韋曲徧尋春，处处繁花满目新。","日暮归鞍不相待，與君同是醉乡人。"]', '诗', 'shi', '', NULL, '酬趙尚書城南看花日晚先歸見寄 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd796b81-4dd2-4b56-8e43-87482b366545', '伏蒙十六叔寄示喜慶感懷三十韻因獻之', '伏蒙十六叔寄示喜慶感懷三十韻因獻之', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["受氏自有殷，樹功緬前秦。","圭田接土宇，侯籍相紛綸。","道義集天爵，菁華極人文。","握蘭中臺並，折桂東堂春。","祖德蹈前哲，家風播清芬。","先公秉明義，大節逢艱屯。","獨立挺忠孝，至誠感神人。","命書備追錫，跡遠道不伸。","小生諒無似，積慶遭昌辰。","九年西掖忝，五轉南宮頻。","司理因曠職，曲臺仍禮神。","愧非夔龍姿，忽佐堯舜君。","內惟負且乘，徒以弱似仁。","豈足議大政，所憂玷彝倫。","叔父貞素履，含章窮典墳。","百氏若珠貫，九流皆翬分。","黃鍾蘊聲調，白玉那緇磷。","清論坐虛室，長謠宜幅巾。","開關接人祠，支策無俗賓。","種杏當暑熱，烹茶含露新。","井徑交碧蘚，軒窗棲白雲。","飛沈禽魚樂，芬馥蘭桂薰。","經術弘義訓，息男茂嘉聞。","筮仕就色養，宴居忘食貧。","四方有翹車，上國有蒲輪。","行當反招隱，豈得常退身。","秦吳路杳杳，朔海望沄沄。","侍坐馳夢寐，結懷積昏昕。","發函捧新詩，慈誨情殷勤。","省躬日三復，拜首書諸紳。"]', '["受氏自有殷，樹功緬前秦。","圭田接土宇，侯籍相紛綸。","道義集天爵，菁华極人文。","握蘭中台並，折桂东堂春。","祖德蹈前哲，家风播清芬。","先公秉明義，大節逢艱屯。","独立挺忠孝，至誠感神人。","命书備追錫，跡远道不伸。","小生諒無似，積慶遭昌辰。","九年西掖忝，五轉南宮頻。","司理因曠職，曲台仍禮神。","愧非夔龙姿，忽佐堯舜君。","內惟負且乘，徒以弱似仁。","豈足議大政，所憂玷彝倫。","叔父貞素履，含章窮典墳。","百氏若珠貫，九流皆翬分。","黄鍾蘊声調，白玉那緇磷。","清論坐虛室，长謠宜幅巾。","开关接人祠，支策無俗賓。","種杏當暑熱，烹茶含露新。","井徑交碧蘚，軒窗棲白云。","飞沈禽鱼乐，芬馥蘭桂薰。","經術弘義訓，息男茂嘉闻。","筮仕就色養，宴居忘食貧。","四方有翹车，上国有蒲輪。","行當反招隐，豈得常退身。","秦吳路杳杳，朔海望沄沄。","侍坐驰梦寐，結懷積昏昕。","發函捧新诗，慈誨情殷勤。","省躬日三复，拜首书諸紳。"]', '诗', 'shi', '', NULL, '伏蒙十六叔寄示喜慶感懷三十韻因獻之 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6dcc533e-01af-48f9-835f-47f087bc81c7', '酬李二十二兄主簿馬跡山見寄', '酬李二十二兄主簿马跡山见寄', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["杳杳塵外想，悠悠區中緣。","如何戰未勝，曾是敎所牽。","遠郊有靈峯，夙昔棲真仙。","鸞聲去已久，馬跡空依然。","丹崖轉初旭，碧落凝秋煙。","松風共簫颯，蘿月想嬋娟。","內兄蘊遐心，嘉遯性所便。","不能棲枳棘，且復探雲泉。","中有冥寂人，閑讀逍遙篇。","聯袂共支[策]，摳衣賞絕編。","徐行石上苔，靜韻風中弦。","煙霞濕儒服，日月生寥天。","新詩來起予，璀璨六義全。","能盡含寫意，轉令山水鮮。","若聞笙鶴聲，宛在耳目前。","登攀阻心賞，愁絕空懷賢。","出處豈異途，心冥即真筌。","蹔從西府檄，終臥東菑田。","不嫌予步蹇，但恐君行羶。","如能固曠懷，谷口期窮年。"]', '["杳杳塵外想，悠悠區中緣。","如何戰未勝，曾是敎所牽。","远郊有靈峯，夙昔棲真仙。","鸾声去已久，马跡空依然。","丹崖轉初旭，碧落凝秋煙。","松风共簫颯，蘿月想嬋娟。","內兄蘊遐心，嘉遯性所便。","不能棲枳棘，且复探云泉。","中有冥寂人，闲读逍遙篇。","聯袂共支[策]，摳衣賞絕編。","徐行石上苔，静韻风中弦。","煙霞濕儒服，日月生寥天。","新诗来起予，璀璨六義全。","能尽含寫意，轉令山水鲜。","若闻笙鹤声，宛在耳目前。","登攀阻心賞，愁絕空懷賢。","出处豈異途，心冥即真筌。","蹔從西府檄，終臥东菑田。","不嫌予步蹇，但恐君行羶。","如能固曠懷，谷口期窮年。"]', '诗', 'shi', '', NULL, '酬李二十二兄主簿馬跡山見寄 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49a4939a-31cb-47d3-a21e-e320c1609993', '酬陸四十楚源春夜宿虎丘山對月寄梁四敬之兼見貽之作', '酬陸四十楚源春夜宿虎丘山对月寄梁四敬之兼见貽之作', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["東風變[蘅]薄，時景日妍和。","更想千峯夜，浩然幽意多。","蕙香襲閑趾，松露泫喬柯。","潭影漾霞月，石牀封薜蘿。","夫君非歲時，已負青冥姿。","龍虎一門盛，淵雲四海推。","駸駸步騕褭，婉婉翥長離。","懸圃盡瓊樹，家林輕桂枝。","聲榮徒外獎，恬淡方自適。","逸氣凌顥清，仁祠訪金碧。","芊眠瑤草秀，斷續雲竇滴。","芳訊發幽緘，新詩比良覿。","故人石渠署，美價滿中朝。","落落杉松直，芬芬蘭杜飄。","雄詞鼓溟海，曠達豁煙霄。","營道幸同術，論心皆後凋。","循環伐木詠，緬邈招隱情。","慙茲擁腫才，愛彼潺湲清。","拘牽尚多故，夢想何由幷。","終結方外期，不待華髮生。"]', '["东风变[蘅]薄，时景日妍和。","更想千峯夜，浩然幽意多。","蕙香襲闲趾，松露泫喬柯。","潭影漾霞月，石牀封薜蘿。","夫君非歲时，已負青冥姿。","龙虎一门盛，淵云四海推。","駸駸步騕褭，婉婉翥长離。","懸圃尽瓊樹，家林轻桂枝。","声榮徒外獎，恬淡方自適。","逸氣凌顥清，仁祠訪金碧。","芊眠瑤草秀，斷續云竇滴。","芳訊發幽緘，新诗比良覿。","故人石渠署，美價满中朝。","落落杉松直，芬芬蘭杜飄。","雄词鼓溟海，曠達豁煙霄。","營道幸同術，論心皆後凋。","循环伐木詠，緬邈招隐情。","慙茲擁腫才，愛彼潺湲清。","拘牽尚多故，梦想何由幷。","終結方外期，不待华髮生。"]', '诗', 'shi', '', NULL, '酬陸四十楚源春夜宿虎丘山對月寄梁四敬之兼見貽之作 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14cdc107-6f24-4576-87fd-34160b594b09', '酬穆七侍郎早登使院西樓感懷', '酬穆七侍郎早登使院西楼感懷', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["耿耿宵欲半，振衣庭戶前。","浩歌撫長劒，臨風泛清弦。","晴霜麗寒蕪，微月露碧鮮。","杉梧韻幽籟，河漢明秋天。","良夜雖可翫，沈憂逾浩然。","樓中遲啓明，林際揮宿煙。","晨風響鐘鼓，曙色映山川。","滔滔天外駛，杲杲朝日懸。","因窮西南永，得見天地全。","動植相糺紛，車從競喧闐。","鱣鮪躍洪流，麕麚倚荒阡。","嗈嗈白雲鴈，嘒嘒清露蟬。","一氣鼓萬殊，晦明相推遷。","羲和無停鞅，不得常少年。","當令志氣神，及此鬢髮玄。","豈唯十六族，今古稱其賢。","夫君才氣雄，振藻何翩翩。","詩輕沈隱侯，賦擬王仲宣。","小鳥搶榆枋，大鵬激三千。","與君期晚歲，方結林棲緣。"]', '["耿耿宵欲半，振衣庭戶前。","浩歌撫长劒，臨风泛清弦。","晴霜丽寒蕪，微月露碧鲜。","杉梧韻幽籟，河漢明秋天。","良夜雖可翫，沈憂逾浩然。","楼中遲啓明，林際揮宿煙。","晨风响鐘鼓，曙色映山川。","滔滔天外駛，杲杲朝日懸。","因窮西南永，得见天地全。","动植相糺紛，车從競喧闐。","鱣鮪躍洪流，麕麚倚荒阡。","嗈嗈白云鴈，嘒嘒清露蟬。","一氣鼓万殊，晦明相推遷。","羲和無停鞅，不得常少年。","當令志氣神，及此鬢髮玄。","豈唯十六族，今古稱其賢。","夫君才氣雄，振藻何翩翩。","诗轻沈隐侯，賦擬王仲宣。","小鸟搶榆枋，大鵬激三千。","與君期晚歲，方結林棲緣。"]', '诗', 'shi', '', NULL, '酬穆七侍郎早登使院西樓感懷 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b30e21a-0482-42e4-b8bb-75865ef3b787', '奉和李大夫題鄭評事江樓', '奉和李大夫題鄭評事江楼', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["達士無外累，隱几依南郭。","茅棟上江開，布帆當砌落。","支頤散華髮，欹枕曝靈藥。","入鳥不亂行，觀魚還自樂。","何時金馬詔，早歲建安作。","往事盡筌蹄，虛懷寄杯杓。","邦君駐千騎，清論時間酌。","憑檻出煙埃，振衣向寥廓。","心源齊彼是，人境勝巖壑。","何必栖冥冥，然爲避矰繳。"]', '["達士無外累，隐几依南郭。","茅棟上江开，布帆當砌落。","支頤散华髮，欹枕曝靈藥。","入鸟不亂行，观鱼還自乐。","何时金马詔，早歲建安作。","往事尽筌蹄，虛懷寄杯杓。","邦君駐千騎，清論时间酌。","憑檻出煙埃，振衣向寥廓。","心源齊彼是，人境勝巖壑。","何必栖冥冥，然爲避矰繳。"]', '诗', 'shi', '', NULL, '奉和李大夫題鄭評事江樓 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1015196d-d1bc-4d98-89a5-a53328a3ddb7', '春遊茅山酬杜評事見寄', '春游茅山酬杜評事见寄', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["喜得賞心處，春山豈計程。","連溪芳草合，半嶺白雲晴。","絕澗漱冰碧，仙壇挹顥清。","懷君在人境，不共此時情。"]', '["喜得賞心处，春山豈計程。","連溪芳草合，半嶺白云晴。","絕澗漱冰碧，仙壇挹顥清。","懷君在人境，不共此时情。"]', '诗', 'shi', '', NULL, '春遊茅山酬杜評事見寄 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('644f3188-fc89-45d4-94a4-6df041708e61', '和韓侍御白髮', '和韓侍御白髮', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["白髮今朝見，虛齋曉鏡清。","乍分霜簡色，微映鐵冠生。","幕下多能事，周行挹令名。","流年未可歎，正遇太階平。"]', '["白髮今朝见，虛斋晓镜清。","乍分霜簡色，微映鐵冠生。","幕下多能事，周行挹令名。","流年未可歎，正遇太階平。"]', '诗', 'shi', '', NULL, '和韓侍御白髮 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c4301ad-433e-4016-8db8-2e1d0c83b019', '和邵端公醉後寄于諫議之作', '和邵端公醉後寄于諫議之作', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["莫羨簷前柳，春風獨早歸。","陽和次第發，桃李更芳菲。"]', '["莫羨簷前柳，春风独早归。","陽和次第發，桃李更芳菲。"]', '诗', 'shi', '', NULL, '和邵端公醉後寄于諫議之作 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('709e3d66-2471-412f-98e4-4d9b0c76c91a', '和李大夫西山祈雨因感張曲江故事十韻', '和李大夫西山祈雨因感張曲江故事十韻', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["亞相冠貂蟬，分憂統十聯。","火星當永日，雲漢倬炎天。","齋禱期靈貺，精誠契昔賢。","中宵出騶馭，清夜旅牲牷。","觸日看初起，隨車應物先。","雷音生絕巘，雨足晦平阡。","瀟灑四冥合，空濛萬頃連。","歌謠諠澤國，稼穡徧原田。","故事三台盛，新文六義全。","作霖應自此，天下待豐年。"]', '["亞相冠貂蟬，分憂統十聯。","火星當永日，云漢倬炎天。","斋禱期靈貺，精誠契昔賢。","中宵出騶馭，清夜旅牲牷。","觸日看初起，隨车應物先。","雷音生絕巘，雨足晦平阡。","瀟灑四冥合，空濛万頃連。","歌謠諠澤国，稼穡徧原田。","故事三台盛，新文六義全。","作霖應自此，天下待豐年。"]', '诗', 'shi', '', NULL, '和李大夫西山祈雨因感張曲江故事十韻 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97e1c3a8-79a1-4b90-9516-54b1a18f4378', '同陸太祝鴻漸崔法曹載華見蕭侍御留後說得衛撫州報推事使張侍御却迴前刺史戴員外無事喜而有作三首 一', '同陸太祝鴻漸崔法曹載华见蕭侍御留後说得衛撫州報推事使張侍御却迴前刺史戴員外無事喜而有作三首 一', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["專城書素至留臺，忽報張綱攬轡迴。","共看昨日蠅飛處，併是今朝鵲喜來。"]', '["專城书素至留台，忽報張綱攬轡迴。","共看昨日蠅飞处，併是今朝鵲喜来。"]', '诗', 'shi', '', NULL, '同陸太祝鴻漸崔法曹載華見蕭侍御留後說得衛撫州報推事使張侍御却迴前刺史戴員外無事喜而有作三首 一 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bada341-45a3-4536-8416-cab621e24674', '同陸太祝鴻漸崔法曹載華見蕭侍御留後說得衛撫州報推事使張侍御却迴前刺史戴員外無事喜而有作三首 二', '同陸太祝鴻漸崔法曹載华见蕭侍御留後说得衛撫州報推事使張侍御却迴前刺史戴員外無事喜而有作三首 二', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["鶴髮州民擁使車，人人自說受恩初。","如今天下無冤氣，乞爲邦君雪謗書。"]', '["鹤髮州民擁使车，人人自说受恩初。","如今天下無冤氣，乞爲邦君雪謗书。"]', '诗', 'shi', '', NULL, '同陸太祝鴻漸崔法曹載華見蕭侍御留後說得衛撫州報推事使張侍御却迴前刺史戴員外無事喜而有作三首 二 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cd3d0f4-be9d-4fb8-8180-12cc07e4a3dd', '同陸太祝鴻漸崔法曹載華見蕭侍御留後說得衛撫州報推事使張侍御却迴前刺史戴員外無事喜而有作三首 三', '同陸太祝鴻漸崔法曹載华见蕭侍御留後说得衛撫州報推事使張侍御却迴前刺史戴員外無事喜而有作三首 三', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["衆人哺啜喜君醒，渭水由來不雜涇。","遮莫雪霜撩亂下，松枝竹葉自青青。"]', '["衆人哺啜喜君醒，渭水由来不杂涇。","遮莫雪霜撩亂下，松枝竹葉自青青。"]', '诗', 'shi', '', NULL, '同陸太祝鴻漸崔法曹載華見蕭侍御留後說得衛撫州報推事使張侍御却迴前刺史戴員外無事喜而有作三首 三 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a962466-d078-403c-b2a4-a1aaaeca2ebc', '荅韋秀才寄一首', '荅韋秀才寄一首', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["中峯雲暗雨霏霏，水漲花塘未得歸。","心憶瓊枝望不見，幾迴虛濕薜蘿衣。"]', '["中峯云暗雨霏霏，水漲花塘未得归。","心憶瓊枝望不见，幾迴虛濕薜蘿衣。"]', '诗', 'shi', '', NULL, '荅韋秀才寄一首 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb916e9b-62ff-4906-b776-6d90690c684a', '戶部王曹長楊考功崔刑部二院長並同鍾陵使府之舊因以寄贈又陪郎署喜甚常僚因書所懷且敘所知', '戶部王曹长楊考功崔刑部二院长並同鍾陵使府之旧因以寄贈又陪郎署喜甚常僚因书所懷且敘所知', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["忽驚西江侶，共作南宮郎。","宿昔芝蘭室，今茲鴛鷺行。","子猷美風味，左戶推公器。","含毫白雪飛，出匣青萍利。","子雲嘗燕居，作賦似相如。","閑成考課奏，別貢賢良書。","子玉諒貞實，持刑慎丹筆。","秋天鴻鵠姿，晚歲松筠質。","伊予誠薄才，何幸復趨陪。","偶來塵右掖，空此憶中臺。","時節東流駛，悲歡追往事。","待月登庾樓，排雲上蕭寺。","盍簪蓮府讌，落帽龍沙醉。","極浦送風帆，靈山眺煙翠。","解頤通善謔，喻指窮精義。","搦管或飛章，分曹時按吏。","雨散與蓬飄，秦吳兩寂寥。","方期全擁腫，豈望躡扶搖。","夜直分三署，晨趨共九霄。","外庭時接武，廣陌更連鑣。","北極星辰拱，南薰氣序調。","欣隨衆君子，並立聖明朝。"]', '["忽驚西江侶，共作南宮郎。","宿昔芝蘭室，今茲鴛鷺行。","子猷美风味，左戶推公器。","含毫白雪飞，出匣青萍利。","子云嘗燕居，作賦似相如。","闲成考課奏，別貢賢良书。","子玉諒貞實，持刑慎丹笔。","秋天鴻鵠姿，晚歲松筠質。","伊予誠薄才，何幸复趨陪。","偶来塵右掖，空此憶中台。","时節东流駛，悲歡追往事。","待月登庾楼，排云上蕭寺。","盍簪蓮府讌，落帽龙沙醉。","極浦送风帆，靈山眺煙翠。","解頤通善謔，喻指窮精義。","搦管或飞章，分曹时按吏。","雨散與蓬飄，秦吳兩寂寥。","方期全擁腫，豈望躡扶搖。","夜直分三署，晨趨共九霄。","外庭时接武，廣陌更連鑣。","北極星辰拱，南薰氣序調。","欣隨衆君子，並立聖明朝。"]', '诗', 'shi', '', NULL, '戶部王曹長楊考功崔刑部二院長並同鍾陵使府之舊因以寄贈又陪郎署喜甚常僚因書所懷且敘所知 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e984c0b1-e3c0-47d1-a612-0ed51d47dabb', '貢院對雪以絕句代八行奉寄崔閣老', '貢院对雪以絕句代八行奉寄崔閣老', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["寓宿春闈歲欲除，嚴風密雪絕雙魚。","思君獨步西垣裏，日日含香草詔書。"]', '["寓宿春闈歲欲除，嚴风密雪絕雙鱼。","思君独步西垣裏，日日含香草詔书。"]', '诗', 'shi', '', NULL, '貢院對雪以絕句代八行奉寄崔閣老 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d294e60-8a47-47de-83c1-46008d6b2444', '初秋月夜中書宿直因呈楊閣老', '初秋月夜中书宿直因呈楊閣老', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["欹枕直廬暇，風蟬迎早秋。","沈沈玉堂夕，皎皎金波流。","對掌喜新命，分曹諧舊遊。","相思翫華彩，因感庾公樓。"]', '["欹枕直廬暇，风蟬迎早秋。","沈沈玉堂夕，皎皎金波流。","对掌喜新命，分曹諧旧游。","相思翫华彩，因感庾公楼。"]', '诗', 'shi', '', NULL, '初秋月夜中書宿直因呈楊閣老 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fe021dd-c5cf-4e34-a60a-ac5a86ee18f9', '唐開州文編遠寄新賦累惠良藥詠嘆仰佩不覺斐然走筆代書聊書還荅', '唐开州文編远寄新賦累惠良藥詠嘆仰佩不覺斐然走笔代书聊书還荅', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["風雨竦庭柯，端憂坐空堂。","多病時節換，所思道里長。","故人朱兩轓，出自尚書郎。","下車今幾時，理行遠芬芳。","瓊瑤覽良訊，芣苢滿素囊。","結根在貴州，蠲疾傳古方。","探擷當五月，慇懃逾八行。","深情婉如此，善祝何可忘。","復有金玉音，煥如龍鳳章。","一聞靈洞說，若覩羣仙翔。","三清飛慶霄，百汰成雄鋩。","體物信無對，灑心願相將。","昔年同旅食，終日窺文房。","春風眺蕪城，秋水渡柳楊。","君爲太史氏，弱質羈楚鄉。","今來忝司諫，千騎遙相望。","歸雲夕鱗鱗，圓魄夜蒼蒼。","遠思結鈴閣，何人交羽觴。","佇見徵穎川，無爲薄淮陽。","政成看再入，列侍爐煙傍。"]', '["风雨竦庭柯，端憂坐空堂。","多病时節換，所思道里长。","故人朱兩轓，出自尚书郎。","下车今幾时，理行远芬芳。","瓊瑤覽良訊，芣苢满素囊。","結根在貴州，蠲疾傳古方。","探擷當五月，慇懃逾八行。","深情婉如此，善祝何可忘。","复有金玉音，煥如龙鳳章。","一闻靈洞说，若覩羣仙翔。","三清飞慶霄，百汰成雄鋩。","體物信無对，灑心願相將。","昔年同旅食，終日窺文房。","春风眺蕪城，秋水渡柳楊。","君爲太史氏，弱質羈楚乡。","今来忝司諫，千騎遙相望。","归云夕鱗鱗，圓魄夜蒼蒼。","远思結鈴閣，何人交羽觴。","佇见徵穎川，無爲薄淮陽。","政成看再入，列侍爐煙傍。"]', '诗', 'shi', '', NULL, '唐開州文編遠寄新賦累惠良藥詠嘆仰佩不覺斐然走筆代書聊書還荅 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3322ec4b-bc6b-4cfa-8fd6-a414edba0e26', '待漏假寐夢歸江東舊居', '待漏假寐梦归江东旧居', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["十年江浦臥郊園，閑夜分明結夢魂。","舍下煙蘿通古寺，湖中雲雨到前軒。","南宗長老知心法，東郭先生識化源。","覺後忽聞清漏曉，又隨簪珮入君門。"]', '["十年江浦臥郊园，闲夜分明結梦魂。","舍下煙蘿通古寺，湖中云雨到前軒。","南宗长老知心法，东郭先生識化源。","覺後忽闻清漏晓，又隨簪珮入君门。"]', '诗', 'shi', '', NULL, '待漏假寐夢歸江東舊居 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56efb3a0-a352-47bc-bdb0-f42d989b6bb1', '祗命赴京途次淮口因書所懷', '祗命赴京途次淮口因书所懷', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["弱植素寡偶，趨時非所任。","感恩再登龍，求友皆斷金。","彪炳覩奇采，淒鏘聞雅音。","適欣佳期接，遽嘆離思侵。","靡靡遵遠道，忡忡勞寸心。","難成獨酌謠，空奏伐木吟。","泬寥清冬時，蕭索白晝陰。","交歡諒如昨，滯念紛在今。","因風試矯翼，倦飛會歸林。","向晚清淮駛，回首楚雲深。"]', '["弱植素寡偶，趨时非所任。","感恩再登龙，求友皆斷金。","彪炳覩奇采，淒鏘闻雅音。","適欣佳期接，遽嘆離思侵。","靡靡遵远道，忡忡勞寸心。","难成独酌謠，空奏伐木吟。","泬寥清冬时，蕭索白晝陰。","交歡諒如昨，滯念紛在今。","因风試矯翼，倦飞會归林。","向晚清淮駛，回首楚云深。"]', '诗', 'shi', '', NULL, '祗命赴京途次淮口因書所懷 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcc7fec6-a616-49b3-8a99-c1b47b8166cc', '省中春晚忽憶江南舊居戲書所懷因寄兩浙親故雜言', '省中春晚忽憶江南旧居戲书所懷因寄兩浙親故杂言', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["前年冠獬豸，戎府隨賓介。","去年簪進賢，贊導法宮前。","今茲戴武弁，謬列金門彥。","問我何所能，頭冠忽三變。","野性慣疎閑，晨趨興暮還。","花時限清禁，霽後愛南山。","晚景支頤對尊酒，舊遊憶在江湖久。","庾樓柳寺共開襟，楓岸煙塘幾攜手。","結廬常占練湖春，猶寄藜牀與幅巾。","疲羸只欲思三徑，戇直那堪備七人。","更想東南多竹箭，懸圃琅玕共蔥蒨。","裁書且附雙鯉魚，偏恨相思未相見。"]', '["前年冠獬豸，戎府隨賓介。","去年簪進賢，贊導法宮前。","今茲戴武弁，謬列金门彥。","问我何所能，头冠忽三变。","野性慣疎闲，晨趨兴暮還。","花时限清禁，霽後愛南山。","晚景支頤对尊酒，旧游憶在江湖久。","庾楼柳寺共开襟，楓岸煙塘幾携手。","結廬常占練湖春，猶寄藜牀與幅巾。","疲羸只欲思三徑，戇直那堪備七人。","更想东南多竹箭，懸圃琅玕共蔥蒨。","裁书且附雙鯉鱼，偏恨相思未相见。"]', '诗', 'shi', '', NULL, '省中春晚忽憶江南舊居戲書所懷因寄兩浙親故雜言 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d2712ba-cd12-413f-ba59-81123b59361a', '寄李衡州', '寄李衡州', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["片石叢花畫不如，庇身三逕豈吾廬。","主人千騎東方遠，唯望衡陽鴈足書。"]', '["片石叢花畫不如，庇身三逕豈吾廬。","主人千騎东方远，唯望衡陽鴈足书。"]', '诗', 'shi', '', NULL, '寄李衡州 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83b0088c-2d7e-43e9-898d-737fa18a2602', '寄臨海郡崔穉璋', '寄臨海郡崔穉璋', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["美酒步兵廚，古人嘗宦遊。","赤城臨海嶠，君子今督郵。","吏隱豐暇日，琴壺共冥搜。","新詩寒玉韻，曠思孤雲秋。","志士誠勇退，鄙夫自包羞。","終當就知己，莫戀潺湲流。"]', '["美酒步兵廚，古人嘗宦游。","赤城臨海嶠，君子今督郵。","吏隐豐暇日，琴壺共冥搜。","新诗寒玉韻，曠思孤云秋。","志士誠勇退，鄙夫自包羞。","終當就知己，莫戀潺湲流。"]', '诗', 'shi', '', NULL, '寄臨海郡崔穉璋 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82cd7a23-37ac-4ed1-8130-4b6bee62d86b', '李韶州著書常論釋氏之理貴州有能公遺跡詩以問之', '李韶州著书常論釋氏之理貴州有能公遺跡诗以问之', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["常日區中暇，時聞象外言。","曹溪有宗旨，一爲勘心源。"]', '["常日區中暇，时闻象外言。","曹溪有宗旨，一爲勘心源。"]', '诗', 'shi', '', NULL, '李韶州著書常論釋氏之理貴州有能公遺跡詩以問之 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e472ec64-b9ac-4d19-b5c1-179623bddbda', '馬上贈虛公', '马上贈虛公', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["馬足早塵深，飄纓又滿襟。","吾師有甘露，爲洗此時心。"]', '["马足早塵深，飄纓又满襟。","吾師有甘露，爲洗此时心。"]', '诗', 'shi', '', NULL, '馬上贈虛公 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac3d4310-b07b-49fc-aaf3-b2afbf162a21', '郴州換印緘遣之際率成三韻因寄李二兄員外使君', '郴州換印緘遣之際率成三韻因寄李二兄員外使君', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["緘題桂陽印，持寄朗陵兄。","刺舉官猶屈，風謠政已成。","行看換龜紐，奏最謁承明。"]', '["緘題桂陽印，持寄朗陵兄。","刺舉官猶屈，风謠政已成。","行看換龟紐，奏最謁承明。"]', '诗', 'shi', '', NULL, '郴州換印緘遣之際率成三韻因寄李二兄員外使君 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d74688ac-a691-4410-a3cb-b79279450247', '早發杭州泛富春江寄陸三十一公佐', '早發杭州泛富春江寄陸三十一公佐', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["候曉起徒馭，春江多好風。","白波連青雲，蕩漾晨光中。","四望浩無際，沈憂將此同。","未離奔走途，但恐成悲翁。","俯見觸餌鱗，仰目淩霄鴻。","纓塵日已厚，心累何時空。","區區此人世，所向皆樊籠。","唯應杯中物，醒醉爲窮通。","故人懸圃姿，瓊樹紛青葱。","終當此山去，共結蘭桂叢。"]', '["候晓起徒馭，春江多好风。","白波連青云，蕩漾晨光中。","四望浩無際，沈憂將此同。","未離奔走途，但恐成悲翁。","俯见觸餌鱗，仰目淩霄鴻。","纓塵日已厚，心累何时空。","區區此人世，所向皆樊籠。","唯應杯中物，醒醉爲窮通。","故人懸圃姿，瓊樹紛青葱。","終當此山去，共結蘭桂叢。"]', '诗', 'shi', '', NULL, '早發杭州泛富春江寄陸三十一公佐 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('560496ff-d961-4957-87e7-fa2b987fdb90', '寄侍御從舅', '寄侍御從舅', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["靡靡南軒蕙，迎風轉芳滋。","落落幽澗松，百尺無附枝。","世物自多故，達人心不羈。","偶陳幕中畫，未負林間期。","感恩從慰薦，循性難縶維。","野鶴無俗質，孤雲多異姿。","清[泠]松露泫，照灼巖花遲。","終當稅塵駕，來就東山嬉。"]', '["靡靡南軒蕙，迎风轉芳滋。","落落幽澗松，百尺無附枝。","世物自多故，達人心不羈。","偶陳幕中畫，未負林间期。","感恩從慰薦，循性难縶維。","野鹤無俗質，孤云多異姿。","清[泠]松露泫，照灼巖花遲。","終當稅塵駕，来就东山嬉。"]', '诗', 'shi', '', NULL, '寄侍御從舅 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e5b890a-e39b-4e7d-9d1f-b4d791e63274', '湖上晚眺呈惠上人', '湖上晚眺呈惠上人', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["湖上煙景好，鳥飛雲自還。","幸因居止近，日覺性情閑。","獨酌乍臨水，清機常見山。","此時何所憶，淨侶話玄關。"]', '["湖上煙景好，鸟飞云自還。","幸因居止近，日覺性情闲。","独酌乍臨水，清機常见山。","此时何所憶，淨侶話玄关。"]', '诗', 'shi', '', NULL, '湖上晚眺呈惠上人 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5aaa1ffc-68a1-465c-9825-9ced147d9631', '新秋月夜寄故人', '新秋月夜寄故人', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["客心宜靜夜，月色澹新秋。","影落三湘水，詩傳八詠樓。","何窮對酒望，幾處捲簾愁。","若問相思意，隨君萬里遊。"]', '["客心宜静夜，月色澹新秋。","影落三湘水，诗傳八詠楼。","何窮对酒望，幾处捲簾愁。","若问相思意，隨君万里游。"]', '诗', 'shi', '', NULL, '新秋月夜寄故人 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d173a7c-df62-4a18-9e4d-3a1b905aac05', '自楊子歸丹陽初遂閑居聊呈惠公', '自楊子归丹陽初遂闲居聊呈惠公', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["移疾喜無事，卷簾松竹寒。","稍知名是累，日與靜相歡。","蹇淺逢機少，迂疎應物難。","只思閑夜月，共向沃州看。"]', '["移疾喜無事，卷簾松竹寒。","稍知名是累，日與静相歡。","蹇淺逢機少，迂疎應物难。","只思闲夜月，共向沃州看。"]', '诗', 'shi', '', NULL, '自楊子歸丹陽初遂閑居聊呈惠公 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac702011-08e5-41d5-9fdd-a89ff50501cc', '月夜過靈徹上人房因贈', '月夜過靈徹上人房因贈', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["此身會逐白雲去，未洗塵纓還自傷。","今夜幸逢清淨境，滿庭秋月對支郎。"]', '["此身會逐白云去，未洗塵纓還自傷。","今夜幸逢清淨境，满庭秋月对支郎。"]', '诗', 'shi', '', NULL, '月夜過靈徹上人房因贈 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f5beb73-918d-41e2-a864-05145271987d', '戲贈張鍊師', '戲贈張鍊師', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["月帔飄颻摘杏花，相邀洞口勸流霞。","半酣乍奏雲和曲，疑是龜山阿母家。"]', '["月帔飄颻摘杏花，相邀洞口勸流霞。","半酣乍奏云和曲，疑是龟山阿母家。"]', '诗', 'shi', '', NULL, '戲贈張鍊師 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f505e12-13f0-4620-84aa-dac177d6c9d9', '戲贈天竺靈隱二寺寺主', '戲贈天竺靈隐二寺寺主', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["石路泉流兩寺分，尋常鐘磬隔山聞。","山僧半在中峰住，共占青巒與白雲。"]', '["石路泉流兩寺分，尋常鐘磬隔山闻。","山僧半在中峰住，共占青巒與白云。"]', '诗', 'shi', '', NULL, '戲贈天竺靈隱二寺寺主 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3211c47-06df-4ac9-a7fb-1a36bc88ea8a', '贈廣通上人', '贈廣通上人', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["身隨猨鳥在深山，早有詩名到世間。","客至上方留盥漱，龍泓洞水晝潺潺。"]', '["身隨猨鸟在深山，早有诗名到世间。","客至上方留盥漱，龙泓洞水晝潺潺。"]', '诗', 'shi', '', NULL, '贈廣通上人 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fc10515-12d3-4cd8-8d2f-bf77179b2e1c', '贈老將', '贈老將', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["白草黃雲塞上秋，曾隨驃騎出幷州。","轆轤劒折虬鬚白，轉戰功多獨不侯。"]', '["白草黄云塞上秋，曾隨驃騎出幷州。","轆轤劒折虬鬚白，轉戰功多独不侯。"]', '诗', 'shi', '', NULL, '贈老將 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6346fd58-f617-41e0-839e-abcdc09fffd0', '戲贈表兄崔秀才', '戲贈表兄崔秀才', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["何事年年戀隱淪，成名須遣及青春。","明時早獻甘泉去，若待公車却誤人。"]', '["何事年年戀隐淪，成名須遣及青春。","明时早獻甘泉去，若待公车却誤人。"]', '诗', 'shi', '', NULL, '戲贈表兄崔秀才 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('561a71fb-ee67-4894-a69c-209de8cfb222', '醉後戲贈蘇九翛', '醉後戲贈蘇九翛', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["白首書窗成鉅儒，不知簪組徧屠沽。","勸君莫問長安路，且讀魯山于蔿于。"]', '["白首书窗成鉅儒，不知簪組徧屠沽。","勸君莫问长安路，且读魯山于蔿于。"]', '诗', 'shi', '', NULL, '醉後戲贈蘇九翛 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0459c0c-e0ed-47c3-86fd-f741f2e27865', '奉送韋起居老舅百日假滿歸嵩陽舊居', '奉送韋起居老舅百日假满归嵩陽旧居', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["威鳳翔紫氣，孤雲出寥天。","奇采與幽姿，縹緲皆自然。","嘗聞陶唐氏，亦有巢由全。","以此聳風俗，豈必效羈牽。","大君遂羣方，左史蹈前賢。","振衣去朝市，賜告歸林泉。","滑和固難久，循性得所便。","有名皆畏途，無事乃真筌。","舊壑窮杳窱，新潭漾淪漣。","嵓花落又開，山月缺復圓。","輕策逗蘿逕，幅巾淩翠煙。","機閑魚鳥狎，體和芝朮鮮。","四皓本違難，二疏猶待年。","況今寰海清，復此鬢髮玄。","顧慙纓上塵，未絕區中緣。","齊竽終自退，心寄嵩峯巔。"]', '["威鳳翔紫氣，孤云出寥天。","奇采與幽姿，縹緲皆自然。","嘗闻陶唐氏，亦有巢由全。","以此聳风俗，豈必效羈牽。","大君遂羣方，左史蹈前賢。","振衣去朝市，賜告归林泉。","滑和固难久，循性得所便。","有名皆畏途，無事乃真筌。","旧壑窮杳窱，新潭漾淪漣。","嵓花落又开，山月缺复圓。","轻策逗蘿逕，幅巾淩翠煙。","機闲鱼鸟狎，體和芝朮鲜。","四皓本違难，二疏猶待年。","況今寰海清，复此鬢髮玄。","顧慙纓上塵，未絕區中緣。","齊竽終自退，心寄嵩峯巔。"]', '诗', 'shi', '', NULL, '奉送韋起居老舅百日假滿歸嵩陽舊居 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('455c8a89-ecfb-4097-96b5-705f90d809c1', '奉送孔十兄賓客承恩致政歸東都舊居', '奉送孔十兄賓客承恩致政归东都旧居', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["達人曠迹通出處，每憶安居舊山去。","乞身已見抗疏頻，優禮新聞詔書許。","家法遙傳闕里訓，心源早逐嵩丘侶。","南史編年著盛名，東朝侍講常虛佇。","角巾華髮忽自遂，命服金龜君更與。","白雲出岫暫逶迤，鴻鵠入冥無處所。","歸路依依童稚樂，都門藹藹壺觴舉。","能將此道助皇風，自可殊途並伊呂。"]', '["達人曠迹通出处，每憶安居旧山去。","乞身已见抗疏頻，優禮新闻詔书許。","家法遙傳闕里訓，心源早逐嵩丘侶。","南史編年著盛名，东朝侍講常虛佇。","角巾华髮忽自遂，命服金龟君更與。","白云出岫暫逶迤，鴻鵠入冥無处所。","归路依依童稚乐，都门藹藹壺觴舉。","能將此道助皇风，自可殊途並伊呂。"]', '诗', 'shi', '', NULL, '奉送孔十兄賓客承恩致政歸東都舊居 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e1ab4f4-8a13-44f1-a85c-4cceaa5c51f1', '送密秀才吏部駮放後歸蜀應崔大理序', '送密秀才吏部駮放後归蜀應崔大理序', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["蜀國本多士，雄文似相如。","之子西南秀，名在賢能書。","薄祿且未及，故山念歸歟。","迢迢三千里，返駕一羸車。","玉壘長路盡，錦江春物餘。","此行無慍色，知爾戀林廬。"]', '["蜀国本多士，雄文似相如。","之子西南秀，名在賢能书。","薄祿且未及，故山念归歟。","迢迢三千里，返駕一羸车。","玉壘长路尽，錦江春物餘。","此行無慍色，知爾戀林廬。"]', '诗', 'shi', '', NULL, '送密秀才吏部駮放後歸蜀應崔大理序 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f6d507f-5fd4-4036-b62f-7c1d800eb64e', '送袁中丞持節冊南詔五韻', '送袁中丞持節冊南詔五韻', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["西南使星去，遠徹通朝聘。","煙雨僰道深，麾幢漢儀盛。","途輕五尺險，水愛雙流淨。","上國洽恩波，外臣遵禮命。","離堂駐騶馭，且盡罇中聖。"]', '["西南使星去，远徹通朝聘。","煙雨僰道深，麾幢漢儀盛。","途轻五尺險，水愛雙流淨。","上国洽恩波，外臣遵禮命。","離堂駐騶馭，且尽罇中聖。"]', '诗', 'shi', '', NULL, '送袁中丞持節冊南詔五韻 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60453e5d-57f7-440f-95e6-53db619b33d6', '人日送房二十六侍御歸越', '人日送房二十六侍御归越', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["驛騎歸時驄馬蹄，蓮花府映若邪溪。","帝城人日風光早，不惜離堂醉似泥。"]', '["驛騎归时驄马蹄，蓮花府映若邪溪。","帝城人日风光早，不惜離堂醉似泥。"]', '诗', 'shi', '', NULL, '人日送房二十六侍御歸越 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50344c05-b6e2-4fe6-af05-659fde2dd5b1', '送張閣老中丞持節冊弔回鶻', '送張閣老中丞持節冊弔回鶻', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["旌斾翩翩擁漢官，君行常得遠人歡。","分職南臺知禮重，輟書東觀見才難。","金章玉節鳴騶遠，白草黃雲出塞寒。","欲散別離唯有醉，暫煩賓從駐征鞍。"]', '["旌斾翩翩擁漢官，君行常得远人歡。","分職南台知禮重，輟书东观见才难。","金章玉節鳴騶远，白草黄云出塞寒。","欲散別離唯有醉，暫煩賓從駐征鞍。"]', '诗', 'shi', '', NULL, '送張閣老中丞持節冊弔回鶻 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7217f799-249f-4b71-a2b9-462d7fb67b64', '送二十叔赴任餘杭尉', '送二十叔赴任餘杭尉', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["拜首直城陰，罇開意不任。","梅仙歸劇縣，阮巷奏離琴。","春草吳門綠，秋濤浙水深。","十年曾旅寓，應愜宦遊心。"]', '["拜首直城陰，罇开意不任。","梅仙归劇縣，阮巷奏離琴。","春草吳门綠，秋濤浙水深。","十年曾旅寓，應愜宦游心。"]', '诗', 'shi', '', NULL, '送二十叔赴任餘杭尉 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff15b7d9-2977-4881-9ea4-6fba6a4401d2', '春送十四叔赴任渝州錄事絕句', '春送十四叔赴任渝州錄事絕句', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["隨牒忽離南北巷，解巾都吏有清風。","巴城鏁印六聯靜，盡日閑謠廨署中。"]', '["隨牒忽離南北巷，解巾都吏有清风。","巴城鏁印六聯静，尽日闲謠廨署中。"]', '诗', 'shi', '', NULL, '春送十四叔赴任渝州錄事絕句 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('752765da-dcb1-4d0b-b30d-3e118048b4a6', '送韋十二丈赴襄城令三韻', '送韋十二丈赴襄城令三韻', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["留連出關騎，斟酌臨岐酒。","舊業傳一經，新官栽五柳。","去去望行塵，青門重迴首。"]', '["留連出关騎，斟酌臨岐酒。","旧業傳一經，新官栽五柳。","去去望行塵，青门重迴首。"]', '诗', 'shi', '', NULL, '送韋十二丈赴襄城令三韻 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0c801f6-e310-4215-aefa-a1598b261fa4', '送薛十九丈授將作主簿分司東都賦得春草', '送薛十九丈授將作主簿分司东都賦得春草', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["芊芊遠郊外，杳杳春嵓曲。","愁處映微波，望中連淨綠。","日暮藉離觴，折芳心斷續。"]', '["芊芊远郊外，杳杳春嵓曲。","愁处映微波，望中連淨綠。","日暮藉離觴，折芳心斷續。"]', '诗', 'shi', '', NULL, '送薛十九丈授將作主簿分司東都賦得春草 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1590cafd-ccbd-4034-873d-9608699a69d7', '送正字十九兄歸江東醉後絕句', '送正字十九兄归江东醉後絕句', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["命駕相思不爲名，春風歸騎出關程。","離堂莫起臨岐歎，文舉終當薦禰衡。"]', '["命駕相思不爲名，春风归騎出关程。","離堂莫起臨岐歎，文舉終當薦禰衡。"]', '诗', 'shi', '', NULL, '送正字十九兄歸江東醉後絕句 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81351fe4-8335-432e-99df-a63661e50726', '送張詹事致政歸嵩山舊隱', '送張詹事致政归嵩山旧隐', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["解龜辭漢庭，却憶少微星。","直指常持憲，平反更恤刑。","閑思紫芝侶，歸臥白雲扃。","明詔優筋力，安車適性靈。","羣公來藹藹，獨鶴去冥冥。","想到揮金處，嵩吟枕上青。"]', '["解龟辞漢庭，却憶少微星。","直指常持憲，平反更恤刑。","闲思紫芝侶，归臥白云扃。","明詔優筋力，安车適性靈。","羣公来藹藹，独鹤去冥冥。","想到揮金处，嵩吟枕上青。"]', '诗', 'shi', '', NULL, '送張詹事致政歸嵩山舊隱 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6e789ff-d82d-4a4a-a553-40cd3cf6cce5', '送許著作分司東都', '送許著作分司东都', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["月旦繼平輿，風流仕石渠。","分曹向瀍洛，守職正圖書。","棣萼榮相映，瓊枝色不如。","賓朋爭漉酒，徒御侍巾車。","異日始離抱，維思烹鯉魚。"]', '["月旦繼平輿，风流仕石渠。","分曹向瀍洛，守職正圖书。","棣萼榮相映，瓊枝色不如。","賓朋爭漉酒，徒御侍巾车。","異日始離抱，維思烹鯉鱼。"]', '诗', 'shi', '', NULL, '送許著作分司東都 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc03748b-91c8-4a40-bc0d-3a608c296485', '送少清赴潤州參軍因思練舊居', '送少清赴潤州參軍因思練旧居', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["二紀樂簞瓢，煙霞暮與朝。","因君宦遊去，記得春江潮。","遠別更搔首，初官方折腰。","青門望離袂，魂爲阿連銷。"]', '["二紀乐簞瓢，煙霞暮與朝。","因君宦游去，記得春江潮。","远別更搔首，初官方折腰。","青门望離袂，魂爲阿連銷。"]', '诗', 'shi', '', NULL, '送少清赴潤州參軍因思練舊居 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f49ff24-e742-45e8-8e54-fd253095e8dd', '送濬上人歸揚州禪智寺', '送濬上人归揚州禪智寺', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["𥗤露宗通法已傳，麻衣筇杖去悠然。","揚州後學應相待，遙想旛花古寺前。"]', '["𥗤露宗通法已傳，麻衣筇杖去悠然。","揚州後学應相待，遙想旛花古寺前。"]', '诗', 'shi', '', NULL, '送濬上人歸揚州禪智寺 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2e767db-1d29-4027-90c9-d88cc5a38658', '獻歲送李十兄赴黔中酒後絕句', '獻歲送李十兄赴黔中酒後絕句', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["一罇歲酒且留歡，三峽黔江去路難。","志士感恩無遠近，異時應戴惠文冠。"]', '["一罇歲酒且留歡，三峽黔江去路难。","志士感恩無远近，異时應戴惠文冠。"]', '诗', 'shi', '', NULL, '獻歲送李十兄赴黔中酒後絕句 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a818e3c1-b5a2-4f91-ba9e-d88e6108ff3d', '送張僕射朝見畢歸鎮', '送張僕射朝见畢归鎮', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["青光照目青門曙，玉勒琱戈擁騶馭。","東方連帥南陽公，文武吉甫如古風。","獨奉新恩來謁帝，感深更見新詩麗。","共看三接欲爲霖，却念百城同望歲。","雙旌去去戀儲胥，歸路鶯花伴隼旟。","今日漢庭求上略，留侯自有一編書。"]', '["青光照目青门曙，玉勒琱戈擁騶馭。","东方連帥南陽公，文武吉甫如古风。","独奉新恩来謁帝，感深更见新诗丽。","共看三接欲爲霖，却念百城同望歲。","雙旌去去戀儲胥，归路鶯花伴隼旟。","今日漢庭求上略，留侯自有一編书。"]', '诗', 'shi', '', NULL, '送張僕射朝見畢歸鎮 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af167c8e-c7a2-4926-a8f9-9c7f7b27e3db', '送韋行軍員外赴河陽', '送韋行軍員外赴河陽', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["五代武弁侍明光，輟佐中權拜外郎。","記事還同楚倚相，傳經遠自漢扶陽。","離堂處處羅簪組，東望河橋壯鼙鼓。","三城曉角啓軒門，一縣繁花照蓮府。","上略儒風並者稀，翩翩騶騎有光輝。","只今右職多虛位，應待他時伏奏歸。"]', '["五代武弁侍明光，輟佐中權拜外郎。","記事還同楚倚相，傳經远自漢扶陽。","離堂处处羅簪組，东望河橋壯鼙鼓。","三城晓角啓軒门，一縣繁花照蓮府。","上略儒风並者稀，翩翩騶騎有光輝。","只今右職多虛位，應待他时伏奏归。"]', '诗', 'shi', '', NULL, '送韋行軍員外赴河陽 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bce897c4-8d5e-45a3-9fba-6cb52a94c07b', '送韋中丞奉使新羅', '送韋中丞奉使新羅', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["淳化洽聲明，殊方均惠養。","計書重譯至，錫命雙旌往。","星辭北極遠，水泛東溟廣。","斗柄辨宵程，天琛宜晝賞。","孤光洲島迥，淨綠煙霞敞。","展禮盛賓徒，交歡覿君長。","經途勞視聽，愴別縈夢想。","延頸旬歲期，新恩在歸鞅。"]', '["淳化洽声明，殊方均惠養。","計书重譯至，錫命雙旌往。","星辞北極远，水泛东溟廣。","斗柄辨宵程，天琛宜晝賞。","孤光洲島迥，淨綠煙霞敞。","展禮盛賓徒，交歡覿君长。","經途勞視听，愴別縈梦想。","延頸旬歲期，新恩在归鞅。"]', '诗', 'shi', '', NULL, '送韋中丞奉使新羅 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa6a9f02-6ef2-4bc1-8404-0b98ca82c9af', '送從翁赴任長子縣令', '送從翁赴任长子縣令', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["家風本鉅儒，吏職化雙鳧。","啓事才方愜，臨人政自殊。","地雄韓上黨，秩比魯中都。","拜首春郊夕，離杯莫向隅。"]', '["家风本鉅儒，吏職化雙鳧。","啓事才方愜，臨人政自殊。","地雄韓上黨，秩比魯中都。","拜首春郊夕，離杯莫向隅。"]', '诗', 'shi', '', NULL, '送從翁赴任長子縣令 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2ddb99c-5b82-489d-b708-7d526364a738', '送從弟廣東歸絕句', '送從弟廣东归絕句', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["夏雲如火鑠晨輝，欵段羸車整素衣。","知爾業成還出谷，今朝莫愴斷行飛。"]', '["夏云如火鑠晨輝，欵段羸车整素衣。","知爾業成還出谷，今朝莫愴斷行飞。"]', '诗', 'shi', '', NULL, '送從弟廣東歸絕句 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e22dbc4-0de1-4128-bdf0-0ae4e3a2a84d', '送王鍊師赴王屋洞', '送王鍊師赴王屋洞', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["稔歲在芝田，歸程入洞天。","白雲辭上國，青鳥會羣仙。","自以碁銷日，寧資藥駐年。","相看話離合，風馭忽泠然。"]', '["稔歲在芝田，归程入洞天。","白云辞上国，青鸟會羣仙。","自以碁銷日，寧資藥駐年。","相看話離合，风馭忽泠然。"]', '诗', 'shi', '', NULL, '送王鍊師赴王屋洞 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05077568-a41b-41d8-99ba-2fd9282880f4', '送薛溫州', '送薛溫州', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["昨日饋連營，今來刺列城。","方期建禮直，忽訪永嘉程。","郡內裁詩暇，樓中遲客情。","憑君減千騎，莫遣海鷗驚。"]', '["昨日饋連營，今来刺列城。","方期建禮直，忽訪永嘉程。","郡內裁诗暇，楼中遲客情。","憑君減千騎，莫遣海鷗驚。"]', '诗', 'shi', '', NULL, '送薛溫州 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eadbc859-a2de-45d3-bf08-8f043d84959d', '送黔中裴中丞閣老赴任', '送黔中裴中丞閣老赴任', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["五諫留中禁，雙旌輟上才。","內臣持鳳詔，天廄錫龍媒。","宴語暌蘭室，輝榮亞柏臺。","懷黃宜命服，舉白歎離杯。","景霽山川迥，風清霧露開。","辰溪分浩淼，僰道接縈迴。","勝理環中得，殊琛徼外來。","行看旬歲詔，傳慶在公台。"]', '["五諫留中禁，雙旌輟上才。","內臣持鳳詔，天廄錫龙媒。","宴語暌蘭室，輝榮亞柏台。","懷黄宜命服，舉白歎離杯。","景霽山川迥，风清霧露开。","辰溪分浩淼，僰道接縈迴。","勝理环中得，殊琛徼外来。","行看旬歲詔，傳慶在公台。"]', '诗', 'shi', '', NULL, '送黔中裴中丞閣老赴任 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18d7abf2-edf9-4875-936c-fdbfe7b877f0', '送崔諭德致政東歸', '送崔諭德致政东归', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["天子坐法宮，詔書下江東。","懿此嘉遯士，蒲車赴丘中。","褐衣入承明，朴略多古風。","直道侍太子，昌言沃宸聰。","嵓居四十年，心與鷗鳥同。","一朝受恩澤，自說如池龍。","乞骸歸故山，累疏明深衷。","大君不奪志，命錫忽以崇。","旭旦出國門，輕裝若秋蓬。","家依白雲嶠，手植丹桂叢。","竹齋引寒泉，霞月相玲瓏。","曠然解赤綬，去逐冥冥鴻。"]', '["天子坐法宮，詔书下江东。","懿此嘉遯士，蒲车赴丘中。","褐衣入承明，朴略多古风。","直道侍太子，昌言沃宸聰。","嵓居四十年，心與鷗鸟同。","一朝受恩澤，自说如池龙。","乞骸归故山，累疏明深衷。","大君不奪志，命錫忽以崇。","旭旦出国门，轻裝若秋蓬。","家依白云嶠，手植丹桂叢。","竹斋引寒泉，霞月相玲瓏。","曠然解赤綬，去逐冥冥鴻。"]', '诗', 'shi', '', NULL, '送崔諭德致政東歸 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7ad52c3-6f5c-4eac-a557-bb93c8426a17', '送三十叔赴任晉陵', '送三十叔赴任晉陵', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["春雲結暮陰，侍坐捧離襟。","黃綬輕裝去，青門芳草深。","十年塵右職，三逕寄遐心。","便道停橈處，應過舊竹林。"]', '["春云結暮陰，侍坐捧離襟。","黄綬轻裝去，青门芳草深。","十年塵右職，三逕寄遐心。","便道停橈处，應過旧竹林。"]', '诗', 'shi', '', NULL, '送三十叔赴任晉陵 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ddfa52e-06f0-42e6-bd3c-68ad1ee04ab1', '送安南裴都護', '送安南裴都護', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["忽佩交州印，初辭列宿文。","莫言方任遠，且貴主憂分。","迥轉朱鳶路，連飛翠羽羣。","戈船航漲海，旌斾卷炎雲。","絕徼褰帷識，名香夾轂焚。","懷來通北戶，長養洽南薰。","暫歎同心阻，行看異績聞。","歸時無所欲，薏苡或煩君。"]', '["忽佩交州印，初辞列宿文。","莫言方任远，且貴主憂分。","迥轉朱鳶路，連飞翠羽羣。","戈船航漲海，旌斾卷炎云。","絕徼褰帷識，名香夾轂焚。","懷来通北戶，长養洽南薰。","暫歎同心阻，行看異績闻。","归时無所欲，薏苡或煩君。"]', '诗', 'shi', '', NULL, '送安南裴都護 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47ac8d02-6a66-4a7c-bb5d-b2356026760c', '送別沅汎', '送別沅汎', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["念爾強學殖，非貫早從師。","溫溫稟義方，慥慥習書詩。","計偕來上國，宴喜方怡怡。","經術既修明，藝文亦葳蕤。","伊予諒無取，瑣質荷洪慈。","偶來貳儀曹，量力何可支。","廢業固相受，避嫌誠自私。","徇吾刺促心，婉爾康莊姿。","古人貴直道，內訟乖坦夷。","用茲處大官，無乃玷清時。","羸車出門去，悵望交涕洟。","琢磨貴分陰，歲月若飆馳。","千里起足下，豐年繫鎡䥓。","苟令志氣堅，佇見纓珮隨。","斑斕五綵服，前路春物熙。","舊遊憶江南，環堵留蓬茨。","湖水白於練，蓴羹細若絲。","別來十三年，夢寐時見之。","寵榮忽踰量，荏苒不自知。","晨興愧華簪，止足爲靈龜。","遐路各自愛，大來行可期。","青冥在目前，努力調羽儀。"]', '["念爾強学殖，非貫早從師。","溫溫稟義方，慥慥習书诗。","計偕来上国，宴喜方怡怡。","經術既修明，藝文亦葳蕤。","伊予諒無取，瑣質荷洪慈。","偶来貳儀曹，量力何可支。","廢業固相受，避嫌誠自私。","徇吾刺促心，婉爾康莊姿。","古人貴直道，內訟乖坦夷。","用茲处大官，無乃玷清时。","羸车出门去，悵望交涕洟。","琢磨貴分陰，歲月若飆驰。","千里起足下，豐年繫鎡䥓。","苟令志氣堅，佇见纓珮隨。","斑斕五綵服，前路春物熙。","旧游憶江南，环堵留蓬茨。","湖水白於練，蓴羹細若絲。","別来十三年，梦寐时见之。","寵榮忽踰量，荏苒不自知。","晨兴愧华簪，止足爲靈龟。","遐路各自愛，大来行可期。","青冥在目前，努力調羽儀。"]', '诗', 'shi', '', NULL, '送別沅汎 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0a7f454-0d71-454d-a5ab-e6e03d6fa3e9', '送張曹長工部大夫奉使西番', '送張曹长工部大夫奉使西番', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["殊鄰覆露同，奉使小司空。","西候車徒出，南臺節印雄。","弔祠將渥命，導驛暢皇風。","故地山河在，新恩玉帛通。","塞雲凝廢壘，關月照驚蓬。","青史書歸日，翻輕五利功。"]', '["殊鄰覆露同，奉使小司空。","西候车徒出，南台節印雄。","弔祠將渥命，導驛暢皇风。","故地山河在，新恩玉帛通。","塞云凝廢壘，关月照驚蓬。","青史书归日，翻轻五利功。"]', '诗', 'shi', '', NULL, '送張曹長工部大夫奉使西番 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33fff638-4537-45f4-a33c-8b3e1a48c57c', '九華觀宴餞崔十七叔判官赴義武幕兼呈書記蕭校書', '九华观宴餞崔十七叔判官赴義武幕兼呈书記蕭校书', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["炎光三伏晝，洞府宜幽步。","宿雨潤芝田，鮮風搖桂樹。","陰陰臺殿敞，靡靡軒車駐。","晚酌臨水清，晨裝出關路。","偏榮本郡辟，倍感元臣遇。","記室有門人，因君達書素。"]', '["炎光三伏晝，洞府宜幽步。","宿雨潤芝田，鲜风搖桂樹。","陰陰台殿敞，靡靡軒车駐。","晚酌臨水清，晨裝出关路。","偏榮本郡辟，倍感元臣遇。","記室有门人，因君達书素。"]', '诗', 'shi', '', NULL, '九華觀宴餞崔十七叔判官赴義武幕兼呈書記蕭校書 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1841f94b-6ea4-4500-9299-2a6afef61afd', '送文暢上人東遊', '送文暢上人东游', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["桑門許辯才，外學接宗雷。","護法麻衣淨，翻經貝葉開。","宗通知不染，妄想自堪哀。","或結西方社，師遊早晚迴。"]', '["桑门許辯才，外学接宗雷。","護法麻衣淨，翻經貝葉开。","宗通知不染，妄想自堪哀。","或結西方社，師游早晚迴。"]', '诗', 'shi', '', NULL, '送文暢上人東遊 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41d9b21b-6f97-4be4-a475-d0cd6adb4430', '送靈武范司空', '送靈武范司空', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["上略在安邊，吳鉤結束鮮。","三公臨右地，七萃擁中堅。","舊壘銷烽火，新營辨井泉。","伐謀師以律，賈勇士爭先。","塞迥晴看月，沙平遠際天。","榮薰知屈指，應在盛秋前。"]', '["上略在安邊，吳鉤結束鲜。","三公臨右地，七萃擁中堅。","旧壘銷烽火，新營辨井泉。","伐謀師以律，賈勇士爭先。","塞迥晴看月，沙平远際天。","榮薰知屈指，應在盛秋前。"]', '诗', 'shi', '', NULL, '送靈武范司空 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0803728-7f49-4b98-a1a1-cd76d917e507', '送商州杜中丞赴任', '送商州杜中丞赴任', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["安康地里接商於，帝命專城總賦輿。","夕拜忽辭青瑣闥，晨裝獨捧紫泥書。","深山古驛分騶騎，芳草閑雲逐隼旟。","綺皓清風千古在，因君一爲謝巖居。"]', '["安康地里接商於，帝命專城總賦輿。","夕拜忽辞青瑣闥，晨裝独捧紫泥书。","深山古驛分騶騎，芳草闲云逐隼旟。","綺皓清风千古在，因君一爲謝巖居。"]', '诗', 'shi', '', NULL, '送商州杜中丞赴任 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21161999-bd74-4cd0-bada-b3a5ba42a112', '送殷卿罷舉歸淮南舊居', '送殷卿罷舉归淮南旧居', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["計偕十上竟無成，忽憶嵓居便獨行。","志業嘗探絕編義，風塵虛作棄繻生。","歲儲應歎山田薄，里社詩逢野醞清。","惆悵中年羣從少，相看欲別倍關情。"]', '["計偕十上竟無成，忽憶嵓居便独行。","志業嘗探絕編義，风塵虛作棄繻生。","歲儲應歎山田薄，里社诗逢野醞清。","惆悵中年羣從少，相看欲別倍关情。"]', '诗', 'shi', '', NULL, '送殷卿罷舉歸淮南舊居 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('804478d7-16f1-4dc8-b539-77bf9249fe1c', '送杜尹赴東都', '送杜尹赴东都', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["商於留異績，河洛賀新遷。","朝選吾公守，時推杜尹賢。","如綸披鳳詔，出匣淬龍泉。","風雨交中土，簪裾敞別筵。","清明人比玉，照灼府如蓮。","佇報司州政，徵黃似頴川。"]', '["商於留異績，河洛賀新遷。","朝選吾公守，时推杜尹賢。","如綸披鳳詔，出匣淬龙泉。","风雨交中土，簪裾敞別筵。","清明人比玉，照灼府如蓮。","佇報司州政，徵黄似頴川。"]', '诗', 'shi', '', NULL, '送杜尹赴東都 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('325be953-64ad-4563-85bc-3d3814ab485d', '送孔江州', '送孔江州', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["九派尋陽郡，分明似畫圖。","秋光連瀑布，晴翠辨香鑪。","才子厭蘭省，邦君榮竹符。","江城多暇日，能寄八行無。"]', '["九派尋陽郡，分明似畫圖。","秋光連瀑布，晴翠辨香鑪。","才子厭蘭省，邦君榮竹符。","江城多暇日，能寄八行無。"]', '诗', 'shi', '', NULL, '送孔江州 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49bf9535-2495-45a5-bb8b-3c7fdd482848', '送渾鄧州', '送渾鄧州', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["年少守南陽，新恩印綬光。","輕軒出繞霤，利刃發干將。","風勁初下葉，雲寒方護霜。","想君行縣處，露冕菊潭香。"]', '["年少守南陽，新恩印綬光。","轻軒出繞霤，利刃發干將。","风勁初下葉，云寒方護霜。","想君行縣处，露冕菊潭香。"]', '诗', 'shi', '', NULL, '送渾鄧州 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5254b1f3-d053-455b-a3c3-879225dc4f46', '埇橋達奚四于十九陳大三侍御夜宴敘各賦二韻', '埇橋達奚四于十九陳大三侍御夜宴敘各賦二韻', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["滿樹鐵冠瓊樹枝，罇前燭下心相知。","明朝又與白雲遠，自古河梁多別離。"]', '["满樹鐵冠瓊樹枝，罇前燭下心相知。","明朝又與白云远，自古河梁多別離。"]', '诗', 'shi', '', NULL, '埇橋達奚四于十九陳大三侍御夜宴敘各賦二韻 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41478cc9-de3f-496c-bea4-fed29865bba7', '酬別蔡十二見贈', '酬別蔡十二见贈', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["伊人茂天爵，恬澹臥郊園。","傲世方隱几，說經久顓門。","浩歌曳柴車，詎羨丹轂尊。","嚴霜被鶉衣，不知狐白溫。","游心羲文際，愛我相討論。","潢汙忽朝宗，傳騎令載奔。","崢嶸歲陰晚，愀愴離念繁。","別館絲桐清，寒郊煙雨昏。","中飲見逸氣，縱談窮化元。","佇見公車起，聖代待乞言。"]', '["伊人茂天爵，恬澹臥郊园。","傲世方隐几，说經久顓门。","浩歌曳柴车，詎羨丹轂尊。","嚴霜被鶉衣，不知狐白溫。","游心羲文際，愛我相討論。","潢汙忽朝宗，傳騎令載奔。","崢嶸歲陰晚，愀愴離念繁。","別館絲桐清，寒郊煙雨昏。","中饮见逸氣，縱談窮化元。","佇见公车起，聖代待乞言。"]', '诗', 'shi', '', NULL, '酬別蔡十二見贈 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('689cf3fa-0b49-4452-b010-64c3fc27a0df', '揚州與丁山人別', '揚州與丁山人別', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["將軍易道令威仙，華髮清談得此賢。","惆悵今朝廣陵別，遼東後會復何年。"]', '["將軍易道令威仙，华髮清談得此賢。","惆悵今朝廣陵別，遼东後會复何年。"]', '诗', 'shi', '', NULL, '揚州與丁山人別 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0be38b1e-84f7-4373-8dec-62667469aa28', '送台州崔錄事', '送台州崔錄事', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["不嫌臨海遠，微祿代躬耕。","古郡紀綱職，扁舟山水程。","詩因琪樹麗，心與瀑泉清。","盛府知音在，何時薦政成。"]', '["不嫌臨海远，微祿代躬耕。","古郡紀綱職，扁舟山水程。","诗因琪樹丽，心與瀑泉清。","盛府知音在，何时薦政成。"]', '诗', 'shi', '', NULL, '送台州崔錄事 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2320bc2-cbde-4793-9e55-a492e39588db', '送信安劉少府', '送信安劉少府', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["相看結離念，盡此林中淥。","夷代輕遠遊，上才隨薄祿。","參卿滯孫楚，隱市同梅福。","吏散時泛弦，賓來閑覆局。","襟情無俗慮，談笑成逸躅。","此路足灘聲，羨君多水宿。"]', '["相看結離念，尽此林中淥。","夷代轻远游，上才隨薄祿。","參卿滯孫楚，隐市同梅福。","吏散时泛弦，賓来闲覆局。","襟情無俗慮，談笑成逸躅。","此路足灘声，羨君多水宿。"]', '诗', 'shi', '', NULL, '送信安劉少府 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bc7d864-c25e-480b-992a-9db6daf514cb', '送李城門罷官歸嵩陽', '送李城门罷官归嵩陽', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["與君相識處，吏隱在牆東。","啓閉千門靜，逢迎兩掖通。","罷官多暇日，肄業有儒風。","歸去塵寰外，春山桂樹叢。"]', '["與君相識处，吏隐在牆东。","啓閉千门静，逢迎兩掖通。","罷官多暇日，肄業有儒风。","归去塵寰外，春山桂樹叢。"]', '诗', 'shi', '', NULL, '送李城門罷官歸嵩陽 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f573273-926f-4767-914e-19cbeb587983', '送上虞丞', '送上虞丞', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["越郡佳山水，菁江接上虞。","計程航一葦，試吏佐雙鳧。","雲壑窺仙籍，風謠驗地圖。","因尋黃絹字，爲我弔曹盱。"]', '["越郡佳山水，菁江接上虞。","計程航一葦，試吏佐雙鳧。","云壑窺仙籍，风謠驗地圖。","因尋黄絹字，爲我弔曹盱。"]', '诗', 'shi', '', NULL, '送上虞丞 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92acc42a-a57d-46f8-bf91-2d832174622c', '送盧評事婺州省覲', '送盧評事婺州省覲', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["知向東陽去，晨裝見綵衣。","客愁青眼別，家喜玉人歸。","漠漠水煙晚，蕭蕭楓葉飛。","雙溪泊船處，候吏拜胡威。"]', '["知向东陽去，晨裝见綵衣。","客愁青眼別，家喜玉人归。","漠漠水煙晚，蕭蕭楓葉飞。","雙溪泊船处，候吏拜胡威。"]', '诗', 'shi', '', NULL, '送盧評事婺州省覲 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31e28206-5390-42db-9496-2f88975f5300', '送崔端公郎君入京覲省', '送崔端公郎君入京覲省', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["已見風姿美，仍聞藝業勤。","清秋上國路，白皙少年人。","帶月輕帆疾，迎霜綵服新。","過庭若有問，一爲說漳濱。"]', '["已见风姿美，仍闻藝業勤。","清秋上国路，白皙少年人。","带月轻帆疾，迎霜綵服新。","過庭若有问，一爲说漳濱。"]', '诗', 'shi', '', NULL, '送崔端公郎君入京覲省 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65963428-2425-467a-9114-b7ca50744934', '送張周二秀才謁宣州薛侍郎', '送張周二秀才謁宣州薛侍郎', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["儒衣兩少年，春棹轂溪船。","湖月供詩興，嵐風費酒錢。","上帆涵浦岸，欹枕傲晴天。","不用愁羈旅，宣城太守賢。"]', '["儒衣兩少年，春棹轂溪船。","湖月供诗兴，嵐风費酒錢。","上帆涵浦岸，欹枕傲晴天。","不用愁羈旅，宣城太守賢。"]', '诗', 'shi', '', NULL, '送張周二秀才謁宣州薛侍郎 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82be4e8f-42f6-4d54-a809-baa77b082b00', '送張將軍歸東都舊業', '送張將軍归东都旧業', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["功名不復求，舊業向東周。","白草辭邊騎，青門別故侯。","摧殘寶劒折，羸病綠珠愁。","日暮寒風起，猶疑大漠秋。"]', '["功名不复求，旧業向东周。","白草辞邊騎，青门別故侯。","摧殘寶劒折，羸病綠珠愁。","日暮寒风起，猶疑大漠秋。"]', '诗', 'shi', '', NULL, '送張將軍歸東都舊業 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('527eebdf-fbba-45da-a5a6-8a27be40006b', '送句容王少府簿領赴上都', '送句容王少府簿領赴上都', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["上國路綿綿，行人候曉天。","離亭綠綺奏，鄉樹白雲連。","江露濕征袂，山鶯宜泊船。","春風若爲別，相顧起尊前。"]', '["上国路綿綿，行人候晓天。","離亭綠綺奏，乡樹白云連。","江露濕征袂，山鶯宜泊船。","春风若爲別，相顧起尊前。"]', '诗', 'shi', '', NULL, '送句容王少府簿領赴上都 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56164c0c-6a83-4c3b-8f92-4c26a6e8e34e', '送從弟謁員外叔父迴歸義興', '送從弟謁員外叔父迴归義兴', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["異鄉兄弟少，見爾自依然。","來酌林中酒，去耕湖上田。","何朝逢暑雨，幾夜泊魚煙。","餘力當勤學，成名貴少年。"]', '["異乡兄弟少，见爾自依然。","来酌林中酒，去耕湖上田。","何朝逢暑雨，幾夜泊鱼煙。","餘力當勤学，成名貴少年。"]', '诗', 'shi', '', NULL, '送從弟謁員外叔父迴歸義興 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2275360-22a1-4ea7-9983-b3dee2e80575', '送梁道士謁壽州崔大夫', '送梁道士謁壽州崔大夫', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["年少一仙官，清羸駕綵鸞。","洞宮雲渺渺，花路水漫漫。","歲計芝田熟，晨裝月帔寒。","遙知小山桂，五馬待邀歡。"]', '["年少一仙官，清羸駕綵鸾。","洞宮云渺渺，花路水漫漫。","歲計芝田熟，晨裝月帔寒。","遙知小山桂，五马待邀歡。"]', '诗', 'shi', '', NULL, '送梁道士謁壽州崔大夫 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43ad07cd-e6fe-4f1f-b218-ba3d9c876dc0', '送鄭秀才貢舉', '送鄭秀才貢舉', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["西笑意如何，知隨貢舉科。","吟詩向月露，驅馬出煙蘿。","晚色平蕪遠，秋聲候鴈多。","自憐歸未得，相送一勞歌。"]', '["西笑意如何，知隨貢舉科。","吟诗向月露，驱马出煙蘿。","晚色平蕪远，秋声候鴈多。","自怜归未得，相送一勞歌。"]', '诗', 'shi', '', NULL, '送鄭秀才貢舉 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89bc54f0-406d-4660-935f-e4c5cdf1f287', '送謝孝廉移家越州', '送謝孝廉移家越州', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["家承晉太傅，身慕魯諸生。","又見一帆去，共愁千里程。","沙平古樹迥，潮滿曉江晴。","從此幽深去，無妨隱姓名。"]', '["家承晉太傅，身慕魯諸生。","又见一帆去，共愁千里程。","沙平古樹迥，潮满晓江晴。","從此幽深去，無妨隐姓名。"]', '诗', 'shi', '', NULL, '送謝孝廉移家越州 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72376846-a6c5-4811-b39b-59f64571d03a', '送韓孝廉侍從赴舉', '送韓孝廉侍從赴舉', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["貢士去翩翩，如君最少年。","綵衣行不廢，儒服代相傳。","曉月經淮路，繁陰過楚天。","清談遇知己，應訪孝廉船。"]', '["貢士去翩翩，如君最少年。","綵衣行不廢，儒服代相傳。","晓月經淮路，繁陰過楚天。","清談遇知己，應訪孝廉船。"]', '诗', 'shi', '', NULL, '送韓孝廉侍從赴舉 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a01545fb-0ce3-4076-97cc-3c6552eeda38', '送陸拾遺秖召赴行在', '送陸拾遺秖召赴行在', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["鵷鷺承新命，翻飛入漢庭。","歌詩能合雅，獻納每論經。","月曉蜀江迥，猿啼楚樹青。","幸因焚草暇，書札訪沈冥。"]', '["鵷鷺承新命，翻飞入漢庭。","歌诗能合雅，獻納每論經。","月晓蜀江迥，猿啼楚樹青。","幸因焚草暇，书札訪沈冥。"]', '诗', 'shi', '', NULL, '送陸拾遺秖召赴行在 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c9be61b-8aa9-4d7e-89a5-b0528b4336d8', '送暎師歸本寺', '送暎師归本寺', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["還歸柳市去，遠遠出人羣。","苔甃桐花落，山窗桂樹薰。","引泉通絕澗，放鶴入孤雲。","幸許宗雷到，清談不易聞。"]', '["還归柳市去，远远出人羣。","苔甃桐花落，山窗桂樹薰。","引泉通絕澗，放鹤入孤云。","幸許宗雷到，清談不易闻。"]', '诗', 'shi', '', NULL, '送暎師歸本寺 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aa3cc5f-da40-45be-b29c-37fb7f27ea9c', '送宇文文府赴行在', '送宇文文府赴行在', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["送君當歲暮，斗酒破離顏。","車騎擁寒水，雪雲凝遠山。","且安黃綬屈，莫羨白鷗閑。","從此圖南路，青雲步武間。"]', '["送君當歲暮，斗酒破離顏。","车騎擁寒水，雪云凝远山。","且安黄綬屈，莫羨白鷗闲。","從此圖南路，青云步武间。"]', '诗', 'shi', '', NULL, '送宇文文府赴行在 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f12ba051-b790-42ea-9605-a0b0030e584f', '送岳州溫錄事赴任', '送岳州溫錄事赴任', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["解巾州主簿，捧檄不辭遙。","獨鶴九霄翼，寒松百尺條。","晨裝沾雨雪，旅宿候風潮。","爲政閑無事，清談肅郡僚。"]', '["解巾州主簿，捧檄不辞遙。","独鹤九霄翼，寒松百尺條。","晨裝沾雨雪，旅宿候风潮。","爲政闲無事，清談肅郡僚。"]', '诗', 'shi', '', NULL, '送岳州溫錄事赴任 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d686b20-c52a-4db8-a034-95f116e7af66', '送山人歸舊隱', '送山人归旧隐', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["工爲楚辭賦，更著魯衣冠。","歲儉山田薄，秋深晨服寒。","武人榮燕頷，志士戀漁竿。","會被公車薦，知君久晦難。"]', '["工爲楚辞賦，更著魯衣冠。","歲儉山田薄，秋深晨服寒。","武人榮燕頷，志士戀漁竿。","會被公车薦，知君久晦难。"]', '诗', 'shi', '', NULL, '送山人歸舊隱 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92e2f6f4-592a-4aaf-921c-413b768480f2', '惠上人房宴別', '惠上人房宴別', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["方袍相引到龍華，支策開襟路不賒。","法味已同香積會，禮容疑在少施家。","逸民羽客期皆至，疎竹青苔景半斜。","究竟相依何處好，匡山古社足煙霞。"]', '["方袍相引到龙华，支策开襟路不賒。","法味已同香積會，禮容疑在少施家。","逸民羽客期皆至，疎竹青苔景半斜。","究竟相依何处好，匡山古社足煙霞。"]', '诗', 'shi', '', NULL, '惠上人房宴別 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1c8ad2f-17c8-457c-9f46-95c808e1963d', '送裴秀才貢舉', '送裴秀才貢舉', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["儒衣風貌清，去抵漢公卿。","賓貢年猶少，篇章藝已成。","臨流惜暮景，話別起鄉情。","離酌不辭醉，西江春草生。"]', '["儒衣风貌清，去抵漢公卿。","賓貢年猶少，篇章藝已成。","臨流惜暮景，話別起乡情。","離酌不辞醉，西江春草生。"]', '诗', 'shi', '', NULL, '送裴秀才貢舉 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f0c3b4b-c0bc-40b7-8623-ca251fe48152', '送袁太祝衢婺巡覆', '送袁太祝衢婺巡覆', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["校緡稅畝不妨閑，清興自隨魚鳥間。","知君此去足佳句，路出桐溪千萬山。"]', '["校緡稅畝不妨闲，清兴自隨鱼鸟间。","知君此去足佳句，路出桐溪千万山。"]', '诗', 'shi', '', NULL, '送袁太祝衢婺巡覆 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e577367-dfb5-4a8f-be6f-18f9468a1bac', '送湖南李侍御赴本使賦採菱亭詩', '送湖南李侍御赴本使賦採菱亭诗', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["舊俗採菱處，津亭風景和。","沅江收暮靄，楚女發清歌。","曲岸縈湘葉，荒堦上白波。","蘭橈向蓮府，一爲枉帆過。"]', '["旧俗採菱处，津亭风景和。","沅江收暮靄，楚女發清歌。","曲岸縈湘葉，荒堦上白波。","蘭橈向蓮府，一爲枉帆過。"]', '诗', 'shi', '', NULL, '送湖南李侍御赴本使賦採菱亭詩 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5882895b-e584-4587-ab29-30596ecb037c', '送穆侍御歸東都', '送穆侍御归东都', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["知君儒服貴，綵繡兩相輝。","婉婉成名後，翩翩擁傳歸。","江深煙嶼沒，山暗雨雲飛。","共待酬恩罷，相將去息機。"]', '["知君儒服貴，綵繡兩相輝。","婉婉成名後，翩翩擁傳归。","江深煙嶼沒，山暗雨云飞。","共待酬恩罷，相將去息機。"]', '诗', 'shi', '', NULL, '送穆侍御歸東都 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('127da39a-a1d5-4abc-b32d-ef58ed80341c', '送崔端公赴度支江陵院三韻', '送崔端公赴度支江陵院三韻', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["津亭風雪霽，斗酒留征棹。","星傳指湘江，瑤琴多楚調。","偏愁欲別處，黯黯頹陽照。"]', '["津亭风雪霽，斗酒留征棹。","星傳指湘江，瑤琴多楚調。","偏愁欲別处，黯黯頹陽照。"]', '诗', 'shi', '', NULL, '送崔端公赴度支江陵院三韻 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d354aed-ee73-4a15-a004-23cc713f4eae', '送陸太祝赴湖南幕同用送字', '送陸太祝赴湖南幕同用送字', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["不憚征路遙，定緣賓禮重。","新知折柳贈，舊侶乘籃送。","此去佳句多，楓江接雲夢。"]', '["不憚征路遙，定緣賓禮重。","新知折柳贈，旧侶乘籃送。","此去佳句多，楓江接云梦。"]', '诗', 'shi', '', NULL, '送陸太祝赴湖南幕同用送字 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06172f1f-1a0e-4f75-bff0-86682cbdd4df', '送李處士歸弋陽山居', '送李处士归弋陽山居', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["暫來城市意何如，却憶葛陽溪上居。","不憚薄田輸井稅，自將嘉句著州閭。","波翻極浦檣竿出，霜落秋郊樹影疎。","想到家山無俗侶，逢迎只是坐籃輿。"]', '["暫来城市意何如，却憶葛陽溪上居。","不憚薄田輸井稅，自將嘉句著州閭。","波翻極浦檣竿出，霜落秋郊樹影疎。","想到家山無俗侶，逢迎只是坐籃輿。"]', '诗', 'shi', '', NULL, '送李處士歸弋陽山居 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff8e181e-90d3-4ec9-8287-ac2d11d6a2d4', '送清洨上人謁信州陸員外', '送清洨上人謁信州陸員外', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["暫辭長老去隨緣，候曉輕裝寄客船。","佳句已齊康寶月，清談遠指謝臨川。","灘經水瀨逢新雪，路過漁潭宿暝煙。","暇日若隨千騎出，南巖只在郡樓前。"]', '["暫辞长老去隨緣，候晓轻裝寄客船。","佳句已齊康寶月，清談远指謝臨川。","灘經水瀨逢新雪，路過漁潭宿暝煙。","暇日若隨千騎出，南巖只在郡楼前。"]', '诗', 'shi', '', NULL, '送清洨上人謁信州陸員外 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('586ce45c-fbf2-4618-a673-91d9cca086a8', '送別同用闊字', '送別同用闊字', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["耿耿離念繁，蕭蕭涼葉脫。","緇塵素衣敝，風露秋江闊。","想得讀書窗，巖花對巾褐。"]', '["耿耿離念繁，蕭蕭涼葉脫。","緇塵素衣敝，风露秋江闊。","想得读书窗，巖花对巾褐。"]', '诗', 'shi', '', NULL, '送別同用闊字 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8902cc4-de96-4f28-bce2-2fb64d29590f', '送人使之江陵', '送人使之江陵', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["嘉招不辭遠，捧檄利攸往。","行役念前程，讌游睽舊賞。","征軺星乍動，江信潮應上。","煙水飛一帆，霜雲搖五兩。","紛紛別袂舉，切切離鴻響。","後會杳何時，悠然勞夢想。"]', '["嘉招不辞远，捧檄利攸往。","行役念前程，讌游睽旧賞。","征軺星乍动，江信潮應上。","煙水飞一帆，霜云搖五兩。","紛紛別袂舉，切切離鴻响。","後會杳何时，悠然勞梦想。"]', '诗', 'shi', '', NULL, '送人使之江陵 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5f2bdd4-1ce0-4776-bc02-19c5728b04db', '餘干贈別張二十二侍御', '餘干贈別張二十二侍御', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["蕪城陌上春風別，干越亭邊歲暮逢。","驅車又愴南北路，返照寒江千萬峯。"]', '["蕪城陌上春风別，干越亭邊歲暮逢。","驱车又愴南北路，返照寒江千万峯。"]', '诗', 'shi', '', NULL, '餘干贈別張二十二侍御 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f28f738e-b50f-4070-9ba3-72f6576d82e9', '雜言賦得風送崔秀才歸白田限三五六七言', '杂言賦得风送崔秀才归白田限三五六七言', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["響深澗，思啼猨。","闇入蘋洲暖，輕隨柳陌暄。","澹蕩乍飄雲影，芳菲徧滿花源。","寂寞春江別君處，和煙帶雨送征軒。"]', '["响深澗，思啼猨。","闇入蘋洲暖，轻隨柳陌暄。","澹蕩乍飄云影，芳菲徧满花源。","寂寞春江別君处，和煙带雨送征軒。"]', '诗', 'shi', '', NULL, '雜言賦得風送崔秀才歸白田限三五六七言 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('502830f1-5a57-4e49-a9f7-31e10d9f57b8', '雜言同用離騷體送張評事襄陽覲省', '杂言同用離騷體送張評事襄陽覲省', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["黯離堂兮日晚，儼壺觴兮送遠。","遠水霽兮微明，杜蘅秀兮白芷生。","波泫泫兮煙冪冪，凝暮色於空碧。","紛離念兮隨君，泝九江兮經七澤。","君之去兮不可留，五采裳兮木蘭舟。"]', '["黯離堂兮日晚，儼壺觴兮送远。","远水霽兮微明，杜蘅秀兮白芷生。","波泫泫兮煙冪冪，凝暮色於空碧。","紛離念兮隨君，泝九江兮經七澤。","君之去兮不可留，五采裳兮木蘭舟。"]', '诗', 'shi', '', NULL, '雜言同用離騷體送張評事襄陽覲省 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99261cc1-a8ea-4f79-b86b-fc06a851dec1', '嶺上逢久別者又別', '嶺上逢久別者又別', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["十年曾一別，征路此相逢。","馬首向何處，夕陽千萬峯。"]', '["十年曾一別，征路此相逢。","马首向何处，夕陽千万峯。"]', '诗', 'shi', '', NULL, '嶺上逢久別者又別 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('104e9cfc-6a0e-4e07-a532-36d95074c0ea', '贈別表兄韋卿', '贈別表兄韋卿', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["新讀兵書事護羌，腰間寶劒映金章。","少年百戰應輕別，莫笑儒生淚數行。"]', '["新读兵书事護羌，腰间寶劒映金章。","少年百戰應轻別，莫笑儒生泪數行。"]', '诗', 'shi', '', NULL, '贈別表兄韋卿 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83083139-6851-444d-a675-c7f624f5fc83', '古離別', '古離別', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["人生天地間，瞥若六轡馳。","夭壽既常數，奈何生別離。","跡當中人域，正性日已衰。","是非千萬境，杳靄情塵滋。","出門事何常，暫別亦難期。","冉冉歎流景，悠悠限山陂。","盡此一夕歡，華罇會前墀。","雞鳴東方曙，夙駕臨通逵。","欲出強移步，欲留難致辭。","兩情不得已，念此留何爲。","天明去已遠，寂默居人歸。","入門復上堂，怳怳生驚疑。","經履同遊處，猶言常相隨。","覽物或臨盤，翻怪來何遲。","乃知前日歡，本爲今日悲。","特此別後心，寧及未見時。","則知交疎分，久久翻易持。","報君未別後，別後當自知。"]', '["人生天地间，瞥若六轡驰。","夭壽既常數，奈何生別離。","跡當中人域，正性日已衰。","是非千万境，杳靄情塵滋。","出门事何常，暫別亦难期。","冉冉歎流景，悠悠限山陂。","尽此一夕歡，华罇會前墀。","雞鳴东方曙，夙駕臨通逵。","欲出強移步，欲留难致辞。","兩情不得已，念此留何爲。","天明去已远，寂默居人归。","入门复上堂，怳怳生驚疑。","經履同游处，猶言常相隨。","覽物或臨盤，翻怪来何遲。","乃知前日歡，本爲今日悲。","特此別後心，寧及未见时。","則知交疎分，久久翻易持。","報君未別後，別後當自知。"]', '诗', 'shi', '', NULL, '古離別 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de9b8f59-b45b-406b-a7bb-68b34b255146', '早夏青龍寺致齋憑眺感物因書十四韻', '早夏青龙寺致斋憑眺感物因书十四韻', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["曉出文昌宮，憩茲青蓮宇。","潔齋奉明祀，憑覽傷夐古。","秦爲三月火，漢乃一抔土。","詐力自湮淪，霸儀終莽鹵。","中南橫峻極，積翠洩雲雨。","首夏諒清和，芳陰接場圃。","仁祠閟嚴淨，稽首洗靈府。","虛室僧正禪，危梁燕初乳。","通莊走聲利，結駟乃旁午。","觀化復何如，刳心信爲愈。","盛時忽過量，弱質本無取。","靜永環中樞，益愧腰下組。","塵勞期抖擻，陟降聊俯僂。","遺韻留壁間，淒然感東武。"]', '["晓出文昌宮，憩茲青蓮宇。","潔斋奉明祀，憑覽傷夐古。","秦爲三月火，漢乃一抔土。","詐力自湮淪，霸儀終莽鹵。","中南橫峻極，積翠洩云雨。","首夏諒清和，芳陰接場圃。","仁祠閟嚴淨，稽首洗靈府。","虛室僧正禪，危梁燕初乳。","通莊走声利，結駟乃旁午。","观化复何如，刳心信爲愈。","盛时忽過量，弱質本無取。","静永环中樞，益愧腰下組。","塵勞期抖擻，陟降聊俯僂。","遺韻留壁间，淒然感东武。"]', '诗', 'shi', '', NULL, '早夏青龍寺致齋憑眺感物因書十四韻 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d58e2a8-83cd-4a25-90f6-ea67ac260019', '仲秋朝拜昭陵', '仲秋朝拜昭陵', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["清秋壽原上，詔拜承吉卜。","嘗讀貞觀書，及茲幸齋沐。","文皇昔潛耀，隋季自顛覆。","撫運斯順人，救焚非逐鹿。","神祇戴元聖，君父納大麓。","良將授兵符，直臣調鼎餗。","無疆傳慶祚，有截荷亭育。","仙馭淩紫氛，神遊棄黃屋。","方祗護山跡，先正陪巖腹。","杳杳九嵕深，沈沈萬靈肅。","鳥飛田已闢，龍去雲猶簇。","金氣爽林巒，乾岡走崖谷。","吾皇弘孝理，率士蒙景福。","擁佑乃清夷，威靈諒回復。","禮承三公重，心愧二卿祿。","展敬何所伸，曾以斧山木。"]', '["清秋壽原上，詔拜承吉卜。","嘗读貞观书，及茲幸斋沐。","文皇昔潛耀，隋季自顛覆。","撫運斯順人，救焚非逐鹿。","神祇戴元聖，君父納大麓。","良將授兵符，直臣調鼎餗。","無疆傳慶祚，有截荷亭育。","仙馭淩紫氛，神游棄黄屋。","方祗護山跡，先正陪巖腹。","杳杳九嵕深，沈沈万靈肅。","鸟飞田已闢，龙去云猶簇。","金氣爽林巒，乾岡走崖谷。","吾皇弘孝理，率士蒙景福。","擁佑乃清夷，威靈諒回复。","禮承三公重，心愧二卿祿。","展敬何所伸，曾以斧山木。"]', '诗', 'shi', '', NULL, '仲秋朝拜昭陵 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('200b8b91-bd26-4196-a9ea-d9e9d183fae2', '拜昭陵出城與張祕監閣老同里臨行別承在史館未歸尋辱清辭輒酬之', '拜昭陵出城與張祕監閣老同里臨行別承在史館未归尋辱清辞輒酬之', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["仲月當南呂，晨裝拜穀林。","逢君在東觀，不得話離襟。","策馬緣雲路，開緘扣玉音。","還期纔浹日，里社酒同斟。"]', '["仲月當南呂，晨裝拜穀林。","逢君在东观，不得話離襟。","策马緣云路，开緘扣玉音。","還期纔浹日，里社酒同斟。"]', '诗', 'shi', '', NULL, '拜昭陵出城與張祕監閣老同里臨行別承在史館未歸尋辱清辭輒酬之 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c29bdc28-bccc-4f83-b399-2abfa812b62f', '酬馮監拜昭陵迴途中遇雨見示', '酬馮監拜昭陵迴途中遇雨见示', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["之子共乘軺，清秋拜上霄。","曙霞迎夙駕，零雨濕迴鑣。","甘谷行初盡，軒臺去漸遙。","望中猶可辨，耘鳥下山椒。"]', '["之子共乘軺，清秋拜上霄。","曙霞迎夙駕，零雨濕迴鑣。","甘谷行初尽，軒台去漸遙。","望中猶可辨，耘鸟下山椒。"]', '诗', 'shi', '', NULL, '酬馮監拜昭陵迴途中遇雨見示 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc13e5dc-14fa-4315-a91e-c5c222adbaf2', '朔旦冬至攝職南郊因書即事', '朔旦冬至攝職南郊因书即事', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["大明南至慶天正，朔旦圓丘樂六成。","文軌盡同堯曆象，齋祠忝備漢公卿。","星辰列位祥光滿，金石交音曉奏清。","更有觀臺稱賀處，黃雲捧日瑞昇平。"]', '["大明南至慶天正，朔旦圓丘乐六成。","文軌尽同堯曆象，斋祠忝備漢公卿。","星辰列位祥光满，金石交音晓奏清。","更有观台稱賀处，黄云捧日瑞昇平。"]', '诗', 'shi', '', NULL, '朔旦冬至攝職南郊因書即事 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53650b3a-84b8-4569-8303-37c9462e69cf', '奉和張監閣老過八陵院題贈杜卿崔員外', '奉和張監閣老過八陵院題贈杜卿崔員外', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["崇飾山園孝理深，萬方同感聖人心。","已聞東閣招從事，每向西垣奉德音。","公府從容談婉婉，賓堦清切景沈沈。","與君跬步如同舍，終日相期此盍簪。"]', '["崇飾山园孝理深，万方同感聖人心。","已闻东閣招從事，每向西垣奉德音。","公府從容談婉婉，賓堦清切景沈沈。","與君跬步如同舍，終日相期此盍簪。"]', '诗', 'shi', '', NULL, '奉和張監閣老過八陵院題贈杜卿崔員外 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b85a3ae-c81a-48d4-a416-094ac0eb2587', '奉和鄭賓客相公攝官豐陵扈從之作', '奉和鄭賓客相公攝官豐陵扈從之作', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["五輅導靈輼，千夫象繚垣。","行宮移曉漏，綵杖下秋原。","莫究希夷理，空懷渙汗恩。","頤神方蹈道，傳聖乃尊尊。","共祝如山壽，俄驚憑几言。","遐荒七月會，肸蠁百靈奔。","豹尾從風直，鸞旗映日翻。","塗芻聯法從，營騎肅旌門。","杳靄虞泉夕，淒清楚挽喧。","不堪程盡處，嗚咽望文園。"]', '["五輅導靈輼，千夫象繚垣。","行宮移晓漏，綵杖下秋原。","莫究希夷理，空懷渙汗恩。","頤神方蹈道，傳聖乃尊尊。","共祝如山壽，俄驚憑几言。","遐荒七月會，肸蠁百靈奔。","豹尾從风直，鸾旗映日翻。","塗芻聯法從，營騎肅旌门。","杳靄虞泉夕，淒清楚挽喧。","不堪程尽处，嗚咽望文园。"]', '诗', 'shi', '', NULL, '奉和鄭賓客相公攝官豐陵扈從之作 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1b03860-d390-481d-99fa-4c47f7f163ce', '詹事府宿齋絕句', '詹事府宿斋絕句', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["清齋四體泰，白晝一室空。","摧頹有古樹，騷屑多悲風。"]', '["清斋四體泰，白晝一室空。","摧頹有古樹，騷屑多悲风。"]', '诗', 'shi', '', NULL, '詹事府宿齋絕句 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cbfb138-5cc0-4b7b-9c63-25f7e1735aa6', '和王祭酒太社宿齋不得赴李尚書宅會戲書見寄', '和王祭酒太社宿斋不得赴李尚书宅會戲书见寄', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["元禮門前勞引望，句龍壇下阻歡娛。","此時對局空相憶，博進何人更樂輸。"]', '["元禮门前勞引望，句龙壇下阻歡娛。","此时对局空相憶，博進何人更乐輸。"]', '诗', 'shi', '', NULL, '和王祭酒太社宿齋不得赴李尚書宅會戲書見寄 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc88d719-d465-406f-b010-e2d1af6c0017', '酬裴端公八月十五日夜對月見懷', '酬裴端公八月十五日夜对月见懷', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["涼夜清秋半，空庭皓月圓。","動搖隨積水，皎潔滿晴天。","多病嘉期阻，深情麗曲傳。","偏懷賞心處，同望庾樓前。"]', '["涼夜清秋半，空庭皓月圓。","动搖隨積水，皎潔满晴天。","多病嘉期阻，深情丽曲傳。","偏懷賞心处，同望庾楼前。"]', '诗', 'shi', '', NULL, '酬裴端公八月十五日夜對月見懷 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2604ccf-e0f3-4452-bba6-002ded367eda', '奉和崔閣老清明日候許閣老交直之際辱裴閣老書招云與考功苗曹長先城南遊覽獨行口號因以簡贈', '奉和崔閣老清明日候許閣老交直之際辱裴閣老书招云與考功苗曹长先城南游覽独行口號因以簡贈', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["紫禁宿初迴，清明花亂開。","相招直城外，遠遠上春臺。","諫曹將列宿，幾處期子玉。","深竹與清泉，家家桃李鮮。","折芳行載酒，勝賞隨君有。","愁疾自無悰，臨風一搔首。"]', '["紫禁宿初迴，清明花亂开。","相招直城外，远远上春台。","諫曹將列宿，幾处期子玉。","深竹與清泉，家家桃李鲜。","折芳行載酒，勝賞隨君有。","愁疾自無悰，臨风一搔首。"]', '诗', 'shi', '', NULL, '奉和崔閣老清明日候許閣老交直之際辱裴閣老書招云與考功苗曹長先城南遊覽獨行口號因以簡贈 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5728439e-38dc-40cf-a534-875050a52e70', '和張祕監閣老獻歲過蔣大拾遺因呈兩省諸公幷見示', '和張祕監閣老獻歲過蔣大拾遺因呈兩省諸公幷见示', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["二賢同載筆，久次入新年。","焚草淹輕秩，藏書厭舊編。","竹風晴翠動，松雪瑞光鮮。","慶賜行春令，從茲佇九遷。"]', '["二賢同載笔，久次入新年。","焚草淹轻秩，藏书厭旧編。","竹风晴翠动，松雪瑞光鲜。","慶賜行春令，從茲佇九遷。"]', '诗', 'shi', '', NULL, '和張祕監閣老獻歲過蔣大拾遺因呈兩省諸公幷見示 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf52e310-9174-43aa-86cb-6d6f5351199b', '酬崔舍人閣老冬至日宿直省中奉簡兩掖閣老幷見示', '酬崔舍人閣老冬至日宿直省中奉簡兩掖閣老幷见示', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["令節一陽新，西垣宿近臣。","曉光連鳳沼，殘漏近雞人。","白雪飛成曲，黃鐘律應均。","層霄翔迅羽，廣陌駐歸輪。","清切晨趨貴，恩華夜直頻。","輟才時所重，分命秩皆真。","左掖期連茹，南宮愧積薪。","九年叨此地，迴首倍相親。"]', '["令節一陽新，西垣宿近臣。","晓光連鳳沼，殘漏近雞人。","白雪飞成曲，黄鐘律應均。","層霄翔迅羽，廣陌駐归輪。","清切晨趨貴，恩华夜直頻。","輟才时所重，分命秩皆真。","左掖期連茹，南宮愧積薪。","九年叨此地，迴首倍相親。"]', '诗', 'shi', '', NULL, '酬崔舍人閣老冬至日宿直省中奉簡兩掖閣老幷見示 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebcfc882-8d5d-4aaa-badf-0cad35bfb770', '八月十五日夜瑤臺寺對月絕句', '八月十五日夜瑤台寺对月絕句', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["嬴女乘鸞已上天，仁祠空在鼎湖邊。","涼風遙夜清秋半，一望金波照粉田。"]', '["嬴女乘鸾已上天，仁祠空在鼎湖邊。","涼风遙夜清秋半，一望金波照粉田。"]', '诗', 'shi', '', NULL, '八月十五日夜瑤臺寺對月絕句 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('295f895c-d021-4ad6-8ce6-1362de0b8662', '夏至日作', '夏至日作', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["璿樞無停連，四序相錯行。","寄言赫曦景，今日一陰生。"]', '["璿樞無停連，四序相錯行。","寄言赫曦景，今日一陰生。"]', '诗', 'shi', '', NULL, '夏至日作 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f3d25ae-b4cf-4439-a482-907730ef5592', '二月二十七日社兼春分端居有懷簡所思者', '二月二十七日社兼春分端居有懷簡所思者', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["清晝開簾坐，風光處處生。","看花詩思發，對酒客愁輕。","社日雙飛燕，春分百囀鶯。","所思終不見，還是一含情。"]', '["清晝开簾坐，风光处处生。","看花诗思發，对酒客愁轻。","社日雙飞燕，春分百囀鶯。","所思終不见，還是一含情。"]', '诗', 'shi', '', NULL, '二月二十七日社兼春分端居有懷簡所思者 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0130dcaf-3f27-4a94-b78a-b8a1fe5c56b1', '甲子歲元日呈鄭侍御明府', '甲子歲元日呈鄭侍御明府', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["萬里煙塵合，秦吳遂渺然。","無人來上國，灑淚向新年。","世故看風葉，生涯寄海田。","屠蘇聊一醉，猶賴主人賢。"]', '["万里煙塵合，秦吳遂渺然。","無人来上国，灑泪向新年。","世故看风葉，生涯寄海田。","屠蘇聊一醉，猶賴主人賢。"]', '诗', 'shi', '', NULL, '甲子歲元日呈鄭侍御明府 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6113d640-c2f5-4e11-aaae-0368e78f3fb6', '七夕', '七夕', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["佳期人不見，天上喜新秋。","玉珮霑新露，香車渡淺流。","東西一水隔，迢遰兩年愁。","別有穿針處，微明月暎樓。"]', '["佳期人不见，天上喜新秋。","玉珮霑新露，香车渡淺流。","东西一水隔，迢遰兩年愁。","別有穿針处，微明月暎楼。"]', '诗', 'shi', '', NULL, '七夕 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e504c01-2618-4387-a624-8f536249bab3', '嘉興九日寄丹陽親故', '嘉兴九日寄丹陽親故', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["窮年路歧客，西望思茫茫。","積水曾南渡，浮雲失舊鄉。","海邊尋別墅，愁裏見重陽。","草露荷衣冷，山風菊酒香。","獨謠看墜葉，遠目徧秋光。","更羨登攀處，煙花滿練塘。"]', '["窮年路歧客，西望思茫茫。","積水曾南渡，浮云失旧乡。","海邊尋別墅，愁裏见重陽。","草露荷衣冷，山风菊酒香。","独謠看墜葉，远目徧秋光。","更羨登攀处，煙花满練塘。"]', '诗', 'shi', '', NULL, '嘉興九日寄丹陽親故 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aaa5bd6-160c-4719-bb82-a5c7b9c9d06d', '九日北樓宴集', '九日北楼宴集', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["蕭颯秋聲樓上聞，霜風漠漠起陰雲。","不見攜觴王太守，空思落帽孟參軍。","風吟蟋蟀寒偏急，酒泛茱萸晚易醺。","心憶舊山何日見，併將愁淚共紛紛。"]', '["蕭颯秋声楼上闻，霜风漠漠起陰云。","不见携觴王太守，空思落帽孟參軍。","风吟蟋蟀寒偏急，酒泛茱萸晚易醺。","心憶旧山何日见，併將愁泪共紛紛。"]', '诗', 'shi', '', NULL, '九日北樓宴集 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7739ddd-9d7c-44c9-b8e0-c61cd4172bb0', '奉陪李大夫九日龍沙宴會', '奉陪李大夫九日龙沙宴會', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["龍沙重九會，千騎駐旌旗。","水木秋光淨，絲桐雅奏遲。","煙蕪斂暝色，霜菊發寒姿。","今日從公醉，全勝落帽時。"]', '["龙沙重九會，千騎駐旌旗。","水木秋光淨，絲桐雅奏遲。","煙蕪斂暝色，霜菊發寒姿。","今日從公醉，全勝落帽时。"]', '诗', 'shi', '', NULL, '奉陪李大夫九日龍沙宴會 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52993d71-7bc0-4371-a84f-f7bdd5546b93', '臘日龍沙會絕句', '臘日龙沙會絕句', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["簾外寒江千里色，林中罇酒七人期。","寧知臘日龍沙會，却勝重陽落帽時。"]', '["簾外寒江千里色，林中罇酒七人期。","寧知臘日龙沙會，却勝重陽落帽时。"]', '诗', 'shi', '', NULL, '臘日龍沙會絕句 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91892f0d-b686-4349-af07-d43c10a36ef0', '嚴陵釣臺下作', '嚴陵釣台下作', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["絕頂聳蒼翠，清湍石磷磷。","先生晦其中，天子不得臣。","心靈棲顥氣，纓冕猶緇塵。","不樂禁中臥，却歸江上春。","潛驅東漢風，日使薄者醇。","焉用佐天子，特此報故人。","人知大賢心，不獨私自身。","弛張有深致，耕釣陶天真。","奈何清風後，擾擾論屈伸。","交情同市道，利欲相紛綸。","我行訪遺臺，仰古懷逸民。","矰繳鴻鵠遠，雪霜松桂新。","江流去不窮，山色凌秋旻。","人世自今古，清輝照無垠。"]', '["絕頂聳蒼翠，清湍石磷磷。","先生晦其中，天子不得臣。","心靈棲顥氣，纓冕猶緇塵。","不乐禁中臥，却归江上春。","潛驱东漢风，日使薄者醇。","焉用佐天子，特此報故人。","人知大賢心，不独私自身。","弛張有深致，耕釣陶天真。","奈何清风後，擾擾論屈伸。","交情同市道，利欲相紛綸。","我行訪遺台，仰古懷逸民。","矰繳鴻鵠远，雪霜松桂新。","江流去不窮，山色凌秋旻。","人世自今古，清輝照無垠。"]', '诗', 'shi', '', NULL, '嚴陵釣臺下作 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df98256a-2092-412d-a6fe-8dff2dcef722', '曉發武陽館即事書情', '晓發武陽館即事书情', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["清晨策羸車，嘲唽聞村雞。","行將騎吏親，日與情愛暌。","東風變林樾，南畝事耕犂。","青菰冒白水，方塘接廣畦。","雜英被長坂，野草蔓幽蹊。","瀉鹵成沃壤，枯株發柔荑。","芳樹鶯命雛，深林麏引麑。","杳杳途未極，團團日已西。","哲士務纓弁，鄙夫戀蓬藜。","終當稅塵駕，盥濯依春溪。"]', '["清晨策羸车，嘲唽闻村雞。","行將騎吏親，日與情愛暌。","东风变林樾，南畝事耕犂。","青菰冒白水，方塘接廣畦。","杂英被长坂，野草蔓幽蹊。","瀉鹵成沃壤，枯株發柔荑。","芳樹鶯命雛，深林麏引麑。","杳杳途未極，團團日已西。","哲士務纓弁，鄙夫戀蓬藜。","終當稅塵駕，盥濯依春溪。"]', '诗', 'shi', '', NULL, '曉發武陽館即事書情 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('344f82e5-6f1c-4ea9-a4c2-49041091256e', '豐城劒池驛感題', '豐城劒池驛感題', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["龍劒昔未發，泥沙相晦藏。","向非張茂先，孰辨斗牛光。","神物不自達，聖賢亦彷徨。","我行豐城野，慷慨心內傷。"]', '["龙劒昔未發，泥沙相晦藏。","向非張茂先，孰辨斗牛光。","神物不自達，聖賢亦彷徨。","我行豐城野，慷慨心內傷。"]', '诗', 'shi', '', NULL, '豐城劒池驛感題 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30d659f7-fa63-45e9-be47-70bb65c120ef', '奉使宜春夜渡新淦江陸路至黃蘗館路上遇風雨作', '奉使宜春夜渡新淦江陸路至黄蘗館路上遇风雨作', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["草草理夜裝，涉江又登陸。","望路殊未窮，指期今已促。","傳呼戒徒御，振轡轉林麓。","陰雲擁嵓端，霔雨當山腹。","震雷如在耳，飛電來照目。","獸跡不敢窺，馬蹄唯務速。","虔心若齋禮，濡體如沐浴。","萬竅相怒號，百泉暗奔瀑。","危梁慮足跌，峻坂憂車覆。","問我何以然，前日受微祿。","轉知人代事，纓組乃徽束。","向若家居時，安枕春夢熟。","遵途稍已近，候吏來相續。","曉霽心始安，林端見初旭。"]', '["草草理夜裝，涉江又登陸。","望路殊未窮，指期今已促。","傳呼戒徒御，振轡轉林麓。","陰云擁嵓端，霔雨當山腹。","震雷如在耳，飞電来照目。","獸跡不敢窺，马蹄唯務速。","虔心若斋禮，濡體如沐浴。","万竅相怒號，百泉暗奔瀑。","危梁慮足跌，峻坂憂车覆。","问我何以然，前日受微祿。","轉知人代事，纓組乃徽束。","向若家居时，安枕春梦熟。","遵途稍已近，候吏来相續。","晓霽心始安，林端见初旭。"]', '诗', 'shi', '', NULL, '奉使宜春夜渡新淦江陸路至黃蘗館路上遇風雨作 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd67fe2d-abeb-48a4-92c1-5bc77dc17189', '細柳驛', '細柳驛', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["細柳肅軍令，條侯信殊倫。","棘門乃兒戲，從古多其人。","神武今不殺，介夫如搢紳。","息駕幸茲地，懷哉悚精神。"]', '["細柳肅軍令，條侯信殊倫。","棘门乃兒戲，從古多其人。","神武今不殺，介夫如搢紳。","息駕幸茲地，懷哉悚精神。"]', '诗', 'shi', '', NULL, '細柳驛 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e8b850b-8e35-49b3-9a0b-32f667bb8b4e', '渭水', '渭水', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["呂叟年八十，皤然持釣鉤。","意在靜天下，豈唯食營丘。","師臣有家法，小白猶尊周。","日暮駐征策，愛茲清渭流。"]', '["呂叟年八十，皤然持釣鉤。","意在静天下，豈唯食營丘。","師臣有家法，小白猶尊周。","日暮駐征策，愛茲清渭流。"]', '诗', 'shi', '', NULL, '渭水 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e03289f-39d2-4666-91dd-780bdf587f0e', '宮人斜絕句', '宮人斜絕句', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["一路斜分古驛前，陰風切切晦秋煙。","鉛華新舊共冥寞，日暮愁鴟飛野田。"]', '["一路斜分古驛前，陰风切切晦秋煙。","鉛华新旧共冥寞，日暮愁鴟飞野田。"]', '诗', 'shi', '', NULL, '宮人斜絕句 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0aa2282d-fa50-4739-bf7c-39a7f7d63913', '敷水驛', '敷水驛', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["空見水名敷，秦樓昔事無。","臨風駐征騎，聊復捋髭鬚。"]', '["空见水名敷，秦楼昔事無。","臨风駐征騎，聊复捋髭鬚。"]', '诗', 'shi', '', NULL, '敷水驛 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('deedefac-7346-48f5-b1dc-e68a2af0761d', '朝元閣', '朝元閣', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["繚垣複道上層霄，十月離宮萬國朝。","胡馬忽來清蹕去，空餘臺殿照山椒。"]', '["繚垣複道上層霄，十月離宮万国朝。","胡马忽来清蹕去，空餘台殿照山椒。"]', '诗', 'shi', '', NULL, '朝元閣 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e97b9412-50fd-4432-bc95-791ae1da5820', '石甕寺', '石甕寺', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["石甕靈泉勝寶井，汲人迴挂青絲綆。","廚煙半逐白雲飛，當晝老僧來灌頂。"]', '["石甕靈泉勝寶井，汲人迴挂青絲綆。","廚煙半逐白云飞，當晝老僧来灌頂。"]', '诗', 'shi', '', NULL, '石甕寺 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d439c255-fa1a-4960-844c-72838a84ed30', '盤豆驛', '盤豆驛', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["盤豆綠雲上古驛，望思臺下使人愁。","江充得計太子死，日暮戾園風雨秋。"]', '["盤豆綠云上古驛，望思台下使人愁。","江充得計太子死，日暮戾园风雨秋。"]', '诗', 'shi', '', NULL, '盤豆驛 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('098811c4-25dc-4d8e-8ab4-fb74b78b5f95', '晚渡揚子江却寄江南親故', '晚渡揚子江却寄江南親故', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["返照滿寒流，輕舟任搖漾。","支頤見千里，煙景非一狀。","遠岫有無中，片帆風水上。","天清去鳥滅，浦迥寒沙漲。","樹晚疊秋嵐，江空翻宿浪。","胸中千萬慮，對此一清曠。","迴首碧雲深，佳人不可望。"]', '["返照满寒流，轻舟任搖漾。","支頤见千里，煙景非一狀。","远岫有無中，片帆风水上。","天清去鸟滅，浦迥寒沙漲。","樹晚叠秋嵐，江空翻宿浪。","胸中千万慮，对此一清曠。","迴首碧云深，佳人不可望。"]', '诗', 'shi', '', NULL, '晚渡揚子江却寄江南親故 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad4e326d-2fca-4520-b3ee-8dc5f428c9c8', '新安江路', '新安江路', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["深潭與淺灘，萬轉出新安。","人遠禽魚淨，山深水木寒。","嘯起青蘋末，吟矚白雲端。","即事遂幽賞，何心挂儒冠。"]', '["深潭與淺灘，万轉出新安。","人远禽鱼淨，山深水木寒。","嘯起青蘋末，吟矚白云端。","即事遂幽賞，何心挂儒冠。"]', '诗', 'shi', '', NULL, '新安江路 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b60358a-fcbc-41fe-9751-de4fb2291d34', '月夜江行', '月夜江行', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["扣船不得寐，浩露清衣襟。","彌傷孤舟夜，遠結萬里心。","幽興惜瑤草，素懷寄鳴琴。","三奏月初上，寂寞寒江深。"]', '["扣船不得寐，浩露清衣襟。","彌傷孤舟夜，远結万里心。","幽兴惜瑤草，素懷寄鳴琴。","三奏月初上，寂寞寒江深。"]', '诗', 'shi', '', NULL, '月夜江行 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c47a66da-e4d1-4bfd-a8d9-38fdeda8404b', '江城夜泊寄所思', '江城夜泊寄所思', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["客程殊未極，艤櫂泊迴塘。","水宿知寒早，愁眠覺夜長。","遠鐘和暗杵，曙月照晴霜。","此夕相思意，搖搖不暫忘。"]', '["客程殊未極，艤櫂泊迴塘。","水宿知寒早，愁眠覺夜长。","远鐘和暗杵，曙月照晴霜。","此夕相思意，搖搖不暫忘。"]', '诗', 'shi', '', NULL, '江城夜泊寄所思 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e40d3f8a-7e0c-47df-b0a4-f2e55fded03a', '陪包諫議湖墅路中舉帆', '陪包諫議湖墅路中舉帆', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["蕭蕭涼雨歇，境物望中閑。","風際片帆去，煙中獨鳥還。","斷橋通遠浦，野墅接秋山。","更喜陪清興，尊前一解顏。"]', '["蕭蕭涼雨歇，境物望中闲。","风際片帆去，煙中独鸟還。","斷橋通远浦，野墅接秋山。","更喜陪清兴，尊前一解顏。"]', '诗', 'shi', '', NULL, '陪包諫議湖墅路中舉帆 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b95f8dd-a40a-4000-b102-d4767cbe71e2', '富陽陸路', '富陽陸路', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["又入亂峯去，遠程殊未歸。","煙蘿迷客路，山果落征衣。","攲石臨清淺，晴雲出翠微。","漁潭明夜泊，心憶謝玄暉。"]', '["又入亂峯去，远程殊未归。","煙蘿迷客路，山果落征衣。","攲石臨清淺，晴云出翠微。","漁潭明夜泊，心憶謝玄暉。"]', '诗', 'shi', '', NULL, '富陽陸路 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26969ecc-3f9f-454e-9cf2-7fbad838b0c3', '曉', '晓', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["曉風搖五兩，殘月映石壁。","稍稍曙光開，片帆在空碧。"]', '["晓风搖五兩，殘月映石壁。","稍稍曙光开，片帆在空碧。"]', '诗', 'shi', '', NULL, '曉 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de1523ff-1ef1-48ee-9e6c-af396bf69f51', '晝', '晝', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["孤舟漾曖景，獨鶴下秋空。","安流日正晝，淨綠天無風。"]', '["孤舟漾曖景，独鹤下秋空。","安流日正晝，淨綠天無风。"]', '诗', 'shi', '', NULL, '晝 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09de69c4-5ad3-4c63-b968-41bb9dcd415a', '晚', '晚', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["古樹夕陽盡，空江暮靄收。","寂寞扣船坐，獨生千里愁。"]', '["古樹夕陽尽，空江暮靄收。","寂寞扣船坐，独生千里愁。"]', '诗', 'shi', '', NULL, '晚 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b16bd2b-ca6b-4643-9c20-b49d5f6180c2', '夜', '夜', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["猨聲到枕上，愁夢紛難理。","寂寞深夜寒，青霜落秋水。"]', '["猨声到枕上，愁梦紛难理。","寂寞深夜寒，青霜落秋水。"]', '诗', 'shi', '', NULL, '夜 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d4f7510-5622-46cc-a6ae-71e5d38a0e20', '奉和韋諫議奉送水部家兄上後書情寄諸兄弟仍通簡南宮親舊幷呈兩省閣老院長', '奉和韋諫議奉送水部家兄上後书情寄諸兄弟仍通簡南宮親旧幷呈兩省閣老院长', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["駟牡龍旂慶至今，一門儒服耀華簪。","人望皆同照乘寶，家風不重滿籝金。","護衣直夜南宮靜，焚草清時左掖深。","何幸末班陪兩地，陽春欲和意難任。"]', '["駟牡龙旂慶至今，一门儒服耀华簪。","人望皆同照乘寶，家风不重满籝金。","護衣直夜南宮静，焚草清时左掖深。","何幸末班陪兩地，陽春欲和意难任。"]', '诗', 'shi', '', NULL, '奉和韋諫議奉送水部家兄上後書情寄諸兄弟仍通簡南宮親舊幷呈兩省閣老院長 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3dc26314-630f-409f-9e7f-47fd320e1fb5', '奉和史館張閣老以許陳二閣長愛弟俱爲尚書郎伯仲同時列在南北省會於左掖因而有詠', '奉和史館張閣老以許陳二閣长愛弟俱爲尚书郎伯仲同时列在南北省會於左掖因而有詠', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["伯仲盡時賢，平輿與潁川。","桂枝嘗徧折，棣萼更相鮮。","丹地晨趨並，黃扉夕拜聯。","豈如分侍從，來就鳳池邊。"]', '["伯仲尽时賢，平輿與潁川。","桂枝嘗徧折，棣萼更相鲜。","丹地晨趨並，黄扉夕拜聯。","豈如分侍從，来就鳳池邊。"]', '诗', 'shi', '', NULL, '奉和史館張閣老以許陳二閣長愛弟俱爲尚書郎伯仲同時列在南北省會於左掖因而有詠 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5459473-7394-4e72-a4f3-4658bdc60b0b', '韋賓客宅與諸博士宴集', '韋賓客宅與諸博士宴集', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["累抗乞身章，湛恩比上庠。","賓筵徴稷嗣，家法自扶陽。","簪組歡言久，琴壺雅興長。","陰嵐冒苔石，輕籟韻風篁。","佩玉三朝貴，揮金百慮忘。","因知臥商洛，豈勝白雲鄉。"]', '["累抗乞身章，湛恩比上庠。","賓筵徴稷嗣，家法自扶陽。","簪組歡言久，琴壺雅兴长。","陰嵐冒苔石，轻籟韻风篁。","佩玉三朝貴，揮金百慮忘。","因知臥商洛，豈勝白云乡。"]', '诗', 'shi', '', NULL, '韋賓客宅與諸博士宴集 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('560d3dc3-a4fa-4861-97e0-c01523922830', '酬張祕監閣老喜太常中書二閣老與德輿同日遷官相代之作', '酬張祕監閣老喜太常中书二閣老與德輿同日遷官相代之作', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["珠樹共飛棲，分封受紫泥。","正名推五字，貴仕仰三珪。","繼組心知忝，腰章事頗齊。","蓬山有佳句，喜氣在新題。"]', '["珠樹共飞棲，分封受紫泥。","正名推五字，貴仕仰三珪。","繼組心知忝，腰章事頗齊。","蓬山有佳句，喜氣在新題。"]', '诗', 'shi', '', NULL, '酬張祕監閣老喜太常中書二閣老與德輿同日遷官相代之作 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('343a8541-204f-402b-a55c-5032db136f9e', '國子柳博士兼領太常博士輒申賀贈', '国子柳博士兼領太常博士輒申賀贈', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["博士本秦官，求才帖職難。","臨風曲臺淨，對月璧池寒。","講學分陰重，齋祠曉漏殘。","朝衣辨色處，雙綬更宜看。"]', '["博士本秦官，求才帖職难。","臨风曲台淨，对月璧池寒。","講学分陰重，斋祠晓漏殘。","朝衣辨色处，雙綬更宜看。"]', '诗', 'shi', '', NULL, '國子柳博士兼領太常博士輒申賀贈 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39ede6ef-735d-4513-8f5e-a183ba7c98eb', '過隱者湖上所居', '過隐者湖上所居', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["蝸舍映平湖，皤然一魯儒。","唯將酒作聖，不厭谷名愚。","兵法窺黃石，天官辨白榆。","行看軟輪起，未可號潛夫。"]', '["蝸舍映平湖，皤然一魯儒。","唯將酒作聖，不厭谷名愚。","兵法窺黄石，天官辨白榆。","行看軟輪起，未可號潛夫。"]', '诗', 'shi', '', NULL, '過隱者湖上所居 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f4cf32e-a291-466a-b997-f8534086cf2e', '從叔將軍宅薔薇花開太府韋卿有題壁長句因以和作', '從叔將軍宅薔薇花开太府韋卿有題壁长句因以和作', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["環列從容蹀躞歸，光風駘蕩發紅薇。","鶯藏密葉宜新霽，蝶遶低枝愛晚暉。","豔色當軒迷舞袖，繁香滿逕拂朝衣。","名卿洞壑仍相近，佳句新成和者稀。"]', '["环列從容蹀躞归，光风駘蕩發紅薇。","鶯藏密葉宜新霽，蝶遶低枝愛晚暉。","豔色當軒迷舞袖，繁香满逕拂朝衣。","名卿洞壑仍相近，佳句新成和者稀。"]', '诗', 'shi', '', NULL, '從叔將軍宅薔薇花開太府韋卿有題壁長句因以和作 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8369bcbb-f18f-45d5-a1dd-d028d3e6b034', '奉和許閣老霽後慈恩寺杏園看花同用花字口號', '奉和許閣老霽後慈恩寺杏园看花同用花字口號', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["杏林微雨霽，灼灼滿瑤華。","左掖期先至，中園景未斜。","含毫歌白雪，藉草醉流霞。","獨限金閨籍，支頤啜茗花。"]', '["杏林微雨霽，灼灼满瑤华。","左掖期先至，中园景未斜。","含毫歌白雪，藉草醉流霞。","独限金閨籍，支頤啜茗花。"]', '诗', 'shi', '', NULL, '奉和許閣老霽後慈恩寺杏園看花同用花字口號 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6de9d2c-fe81-46c4-84df-14dc5a5727ef', '奉和陳閣老寒食初假當直從東省往集賢因過史館看木瓜花寄張蔣二閣老', '奉和陳閣老寒食初假當直從东省往集賢因過史館看木瓜花寄張蔣二閣老', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["晝漏沈沈倦瑣闈，西垣東觀閱芳菲。","繁花滿樹似留客，應爲主人休澣歸。"]', '["晝漏沈沈倦瑣闈，西垣东观閱芳菲。","繁花满樹似留客，應爲主人休澣归。"]', '诗', 'shi', '', NULL, '奉和陳閣老寒食初假當直從東省往集賢因過史館看木瓜花寄張蔣二閣老 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2601771-41b9-4b46-91b4-654495bc659a', '晚秋陪崔閣老張祕監閣老苗考功同遊昊天觀時楊閣老新直未滿以詩見寄斐然酬和有愧蕪音', '晚秋陪崔閣老張祕監閣老苗考功同游昊天观时楊閣老新直未满以诗见寄斐然酬和有愧蕪音', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["方駕遊何許，仙源去似歸。","縈迴留勝賞，蕭灑出塵機。","泛菊賢人至，燒丹姹女飛。","步虛清曉籟，隱几吸晨暉。","竹逕琅玕合，芝田沆瀣晞。","銀鉤三洞字，瑤笥六銖衣。","麗句翻紅藥，佳期限紫微。","徒然一相望，郢曲和應稀。"]', '["方駕游何許，仙源去似归。","縈迴留勝賞，蕭灑出塵機。","泛菊賢人至，燒丹姹女飞。","步虛清晓籟，隐几吸晨暉。","竹逕琅玕合，芝田沆瀣晞。","銀鉤三洞字，瑤笥六銖衣。","丽句翻紅藥，佳期限紫微。","徒然一相望，郢曲和應稀。"]', '诗', 'shi', '', NULL, '晚秋陪崔閣老張祕監閣老苗考功同遊昊天觀時楊閣老新直未滿以詩見寄斐然酬和有愧蕪音 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f15d641-9baa-4f39-9cfd-9af29463f6ad', '春日同諸公過兵部王尚書林園', '春日同諸公過兵部王尚书林园', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["休沐君相近，時容曳履過。","花間留客久，臺上見春多。","松色明金艾，鶯聲雜玉珂。","更逢新酒熟，相與藉庭莎。"]', '["休沐君相近，时容曳履過。","花间留客久，台上见春多。","松色明金艾，鶯声杂玉珂。","更逢新酒熟，相與藉庭莎。"]', '诗', 'shi', '', NULL, '春日同諸公過兵部王尚書林園 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f71697f-c14d-4a82-a975-0d58dec06e44', '與沈十九拾遺同遊棲霞寺上方於亮上人院會宿二首 一', '與沈十九拾遺同游棲霞寺上方於亮上人院會宿二首 一', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["攝山標勝絕，暇日諧想矚。","縈紆松路深，繚繞雲巖曲。","重樓迴樹杪，古像鑿山腹。","人遠水木清，地深蘭桂馥。","層臺聳金碧，絕頂摩淨綠。","下界誠可悲，南朝紛在目。","焚香入古殿，待月出深竹。","稍覺天籟清，自傷人世促。","宗雷此相遇，偃放從所欲。","清論松枝低，閑吟茗花熟。","一生如土梗，萬慮相桎梏。","永願事潛師，窮年此棲宿。"]', '["攝山標勝絕，暇日諧想矚。","縈紆松路深，繚繞云巖曲。","重楼迴樹杪，古像鑿山腹。","人远水木清，地深蘭桂馥。","層台聳金碧，絕頂摩淨綠。","下界誠可悲，南朝紛在目。","焚香入古殿，待月出深竹。","稍覺天籟清，自傷人世促。","宗雷此相遇，偃放從所欲。","清論松枝低，闲吟茗花熟。","一生如土梗，万慮相桎梏。","永願事潛師，窮年此棲宿。"]', '诗', 'shi', '', NULL, '與沈十九拾遺同遊棲霞寺上方於亮上人院會宿二首 一 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dc6be34-ad42-47da-b5fa-4236c70c4404', '與沈十九拾遺同遊棲霞寺上方於亮上人院會宿二首 二', '與沈十九拾遺同游棲霞寺上方於亮上人院會宿二首 二', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["偶來人境外，心賞幸隨君。","古殿煙霞夕，深山松桂薰。","巖花點寒溜，石磴掃春雲。","清淨諸天近，喧塵下界分。","名僧康寶月，上客沈休文。","共宿東林夜，清猨徹曙聞。"]', '["偶来人境外，心賞幸隨君。","古殿煙霞夕，深山松桂薰。","巖花点寒溜，石磴掃春云。","清淨諸天近，喧塵下界分。","名僧康寶月，上客沈休文。","共宿东林夜，清猨徹曙闻。"]', '诗', 'shi', '', NULL, '與沈十九拾遺同遊棲霞寺上方於亮上人院會宿二首 二 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5a7df0b-5fb2-45cb-b1e0-460d80716804', '題崔山人草堂', '題崔山人草堂', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["竹徑茆堂接洞天，閑時麈尾漱春泉。","世人車馬不知處，時有歸雲到枕邊。"]', '["竹徑茆堂接洞天，闲时麈尾漱春泉。","世人车马不知处，时有归云到枕邊。"]', '诗', 'shi', '', NULL, '題崔山人草堂 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3069ccd3-bb21-453b-8a1b-a5fbb40b724b', '徐孺亭馬上口號', '徐孺亭马上口號', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["湖上荒亭臨水開，龜文篆字積莓苔。","曲江北海今何處，盡逐東流去不迴。"]', '["湖上荒亭臨水开，龟文篆字積莓苔。","曲江北海今何处，尽逐东流去不迴。"]', '诗', 'shi', '', NULL, '徐孺亭馬上口號 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49e36210-6a80-4c85-bd9c-395a526fdd25', '哭劉四尚書', '哭劉四尚书', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["士友惜賢人，天朝喪守臣。","才華推獨步，聲氣幸相親。","理析寰中妙，儒爲席上珍。","笑言成月旦，風韻挹天真。","丹地膺推擇，青油寄撫循。","豈言朝象魏，翻是臥漳濱。","命賜龍泉重，追榮密印陳。","撤弦驚物故，庀具見家貧。","牢落風悲笛，汍瀾涕泣巾。","只嗟蒿里月，非復柳營春。","黃絹碑文在，青松隧路新。","音容無處所，歸作北邙塵。"]', '["士友惜賢人，天朝喪守臣。","才华推独步，声氣幸相親。","理析寰中妙，儒爲席上珍。","笑言成月旦，风韻挹天真。","丹地膺推擇，青油寄撫循。","豈言朝象魏，翻是臥漳濱。","命賜龙泉重，追榮密印陳。","撤弦驚物故，庀具见家貧。","牢落风悲笛，汍瀾涕泣巾。","只嗟蒿里月，非复柳營春。","黄絹碑文在，青松隧路新。","音容無处所，归作北邙塵。"]', '诗', 'shi', '', NULL, '哭劉四尚書 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcb815fe-d0e0-4ac0-a417-10704e338caf', '張工部至薄寒山下有書無由馳報輤車之至倍切悲懷', '張工部至薄寒山下有书無由驰報輤车之至倍切悲懷', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["書來遠自薄寒山，繚繞洮河出古關。","今日難裁秣陵報，薤歌寥落柳車邊。"]', '["书来远自薄寒山，繚繞洮河出古关。","今日难裁秣陵報，薤歌寥落柳车邊。"]', '诗', 'shi', '', NULL, '張工部至薄寒山下有書無由馳報輤車之至倍切悲懷 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bb6d6ff-585e-4b86-9dc0-7404bd80557d', '工部發引日屬傷足臥疾不遂執紼', '工部發引日屬傷足臥疾不遂執紼', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["子春傷足日，況有寢門哀。","元伯歸全去，無由白馬來。","笳簫里巷咽，龜筮墓田開。","片石潺湲淚，含悲敘史才。"]', '["子春傷足日，況有寢门哀。","元伯归全去，無由白马来。","笳簫里巷咽，龟筮墓田开。","片石潺湲泪，含悲敘史才。"]', '诗', 'shi', '', NULL, '工部發引日屬傷足臥疾不遂執紼 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1e289be-bef9-4b6b-b271-0ed1c6f1bc54', '從事淮南府過亡友楊校書舊廳感念愀然', '從事淮南府過亡友楊校书旧廳感念愀然', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["故人隨化往，倏忽今六霜。","及我就拘限，清風留此堂。","松竹逾映蔚，芝蘭自銷亡。","絕弦罷流水，聞笛同山陽。","熲如冰玉姿，粲若鸞鳳章。","欲翥摧勁翮，先秋落貞芳。","正平賦鸚鵡，文考頌靈光。","二子古不弔，夫君今何傷。","黃墟既杳杳，玄化亦茫茫。","豈必限宿草，含悽灑衣裳。"]', '["故人隨化往，倏忽今六霜。","及我就拘限，清风留此堂。","松竹逾映蔚，芝蘭自銷亡。","絕弦罷流水，闻笛同山陽。","熲如冰玉姿，粲若鸾鳳章。","欲翥摧勁翮，先秋落貞芳。","正平賦鸚鵡，文考頌靈光。","二子古不弔，夫君今何傷。","黄墟既杳杳，玄化亦茫茫。","豈必限宿草，含悽灑衣裳。"]', '诗', 'shi', '', NULL, '從事淮南府過亡友楊校書舊廳感念愀然 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7cd0592-1ca7-4c00-a207-098ece1df847', '哭李晦羣崔季文二處士', '哭李晦羣崔季文二处士', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["華封西祝堯，貴壽多男子。","二賢無主後，貧賤大壯齒。","未成鴻鵠姿，遽頓驊騮趾。","子淵將叔度，自古不得已。"]', '["华封西祝堯，貴壽多男子。","二賢無主後，貧賤大壯齒。","未成鴻鵠姿，遽頓驊騮趾。","子淵將叔度，自古不得已。"]', '诗', 'shi', '', NULL, '哭李晦羣崔季文二處士 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54942d0c-7474-4a82-bf00-8480f20a9c40', '觀葬者', '观葬者', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["塗芻隨晝哭，數里至松門。","貴盡人間禮，寧知逝者魂。","笳簫出古陌，煙雨閉寒原。","萬古皆如此，傷心反不言。"]', '["塗芻隨晝哭，數里至松门。","貴尽人间禮，寧知逝者魂。","笳簫出古陌，煙雨閉寒原。","万古皆如此，傷心反不言。"]', '诗', 'shi', '', NULL, '觀葬者 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdeae999-8685-469e-a286-1438e4e1e6f9', '成南陽墓', '成南陽墓', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["枯荄沒古基，駮蘚蔽豐碑。","向晚微風起，如聞坐嘯時。"]', '["枯荄沒古基，駮蘚蔽豐碑。","向晚微风起，如闻坐嘯时。"]', '诗', 'shi', '', NULL, '成南陽墓 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccf1691d-8325-4d04-9eda-9d8608216ba7', '周平西墓', '周平西墓', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["英威今寂寞，陳跡對崇丘。","壯志清風在，荒墳白日愁。","窮泉那復曉，喬木不知秋。","歲歲寒塘側，無人水自流。"]', '["英威今寂寞，陳跡对崇丘。","壯志清风在，荒墳白日愁。","窮泉那复晓，喬木不知秋。","歲歲寒塘側，無人水自流。"]', '诗', 'shi', '', NULL, '周平西墓 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd13f463-27b3-4cfd-9d2b-f38d52f0a760', '蘇小小墓', '蘇小小墓', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["萬古荒墳在，悠然我獨尋。","寂寥紅粉盡，冥寞黃泉深。","蔓草映寒水，空郊曖夕陰。","風流有佳句，吟眺一傷心。"]', '["万古荒墳在，悠然我独尋。","寂寥紅粉尽，冥寞黄泉深。","蔓草映寒水，空郊曖夕陰。","风流有佳句，吟眺一傷心。"]', '诗', 'shi', '', NULL, '蘇小小墓 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('567cb697-b314-4363-b4d8-7980cd57c9af', '題柳郎中茅山故居', '題柳郎中茅山故居', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["下馬荒堦日欲曛，潺潺石溜靜中聞。","鳥啼花落人聲絕，寂寞山窗掩白雲。"]', '["下马荒堦日欲曛，潺潺石溜静中闻。","鸟啼花落人声絕，寂寞山窗掩白云。"]', '诗', 'shi', '', NULL, '題柳郎中茅山故居 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6487761a-51bf-4362-9513-52c1f6c495bb', '哭張十八校書', '哭張十八校书', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["芸閣爲郎一命初，桐州寄傲十年餘。","魂隨逝水歸何處，名在新詩衆不如。","蹉跎江浦生華髮，牢落寒原會素車。","更憶八行前日到，含悽爲報秣陵書。"]', '["芸閣爲郎一命初，桐州寄傲十年餘。","魂隨逝水归何处，名在新诗衆不如。","蹉跎江浦生华髮，牢落寒原會素车。","更憶八行前日到，含悽爲報秣陵书。"]', '诗', 'shi', '', NULL, '哭張十八校書 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c41fe3c-494c-4a0c-879e-b17e141c2fa7', '題亡友江畔舊居', '題亡友江畔旧居', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["寥落留三徑，柴扉對楚江。","蠨蛸集暗壁，蜥蜴走寒窗。","松蓋欹書幌，苔衣上酒缸。","平生斷金契，到此淚成雙。"]', '["寥落留三徑，柴扉对楚江。","蠨蛸集暗壁，蜥蜴走寒窗。","松蓋欹书幌，苔衣上酒缸。","平生斷金契，到此泪成雙。"]', '诗', 'shi', '', NULL, '題亡友江畔舊居 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2368579c-8961-482d-9699-269921d44381', '德宗神武孝文皇帝挽歌詞三首 一', '德宗神武孝文皇帝挽歌词三首 一', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["覆露雍熙運，澄清敎化源。","賡歌凝庶績，羽舞被深恩。","纂業光文祖，貽謀屬孝孫。","恭聞留末命，猶是愛元元。"]', '["覆露雍熙運，澄清敎化源。","賡歌凝庶績，羽舞被深恩。","纂業光文祖，貽謀屬孝孫。","恭闻留末命，猶是愛元元。"]', '诗', 'shi', '', NULL, '德宗神武孝文皇帝挽歌詞三首 一 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa79bc15-0456-4883-a42f-157d4931bbbd', '德宗神武孝文皇帝挽歌詞三首 二', '德宗神武孝文皇帝挽歌词三首 二', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["梯航來萬國，玉帛慶三朝。","湛露恩方浹，薰風曲正調。","晏車悲鹵簿，廣樂遏簫韶。","最愴號弓處，龍髯上紫霄。"]', '["梯航来万国，玉帛慶三朝。","湛露恩方浹，薰风曲正調。","晏车悲鹵簿，廣乐遏簫韶。","最愴號弓处，龙髯上紫霄。"]', '诗', 'shi', '', NULL, '德宗神武孝文皇帝挽歌詞三首 二 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('914828b6-14dd-4adb-b40f-78c40f049c87', '德宗神武孝文皇帝挽歌詞三首 三', '德宗神武孝文皇帝挽歌词三首 三', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["常時柏梁宴，今日穀林歸。","玉斝恩波徧，靈輼煙雨霏。","喬山森羽騎，渭水擁旌旂。","仙馭何由見，耘田鳥自飛。"]', '["常时柏梁宴，今日穀林归。","玉斝恩波徧，靈輼煙雨霏。","喬山森羽騎，渭水擁旌旂。","仙馭何由见，耘田鸟自飞。"]', '诗', 'shi', '', NULL, '德宗神武孝文皇帝挽歌詞三首 三 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95fb739e-2585-46c3-8023-bc00b2c99165', '順宗至德大安孝皇帝挽歌三首 一', '順宗至德大安孝皇帝挽歌三首 一', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["十葉開昌運，三辰麗德音。","薦功期瘞玉，昭儉每捐金。","解澤皇風徧，虞泉白日沈。","仍聞起居注，焚奏感人心。"]', '["十葉开昌運，三辰丽德音。","薦功期瘞玉，昭儉每捐金。","解澤皇风徧，虞泉白日沈。","仍闻起居注，焚奏感人心。"]', '诗', 'shi', '', NULL, '順宗至德大安孝皇帝挽歌三首 一 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56930e4b-289a-4014-a9aa-18080e622de8', '順宗至德大安孝皇帝挽歌三首 二', '順宗至德大安孝皇帝挽歌三首 二', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["孝理本憂勤，玄功在嗇神。","睿圖傳上嗣，壽酒比家人。","仙馭三清遠，行宮萬象新。","小臣司吉從，還扈屬車塵。"]', '["孝理本憂勤，玄功在嗇神。","睿圖傳上嗣，壽酒比家人。","仙馭三清远，行宮万象新。","小臣司吉從，還扈屬车塵。"]', '诗', 'shi', '', NULL, '順宗至德大安孝皇帝挽歌三首 二 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('381d5e89-7ca5-410a-b3ea-7c601df4f563', '順宗至德大安孝皇帝挽歌三首 三', '順宗至德大安孝皇帝挽歌三首 三', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["候曉傳清蹕，迎風引綵旒。","共瞻宮輅出，遙想望陵愁。","弓劒隨雲氣，衣冠奉月游。","空餘駕龍處，搖落鼎湖秋。"]', '["候晓傳清蹕，迎风引綵旒。","共瞻宮輅出，遙想望陵愁。","弓劒隨云氣，衣冠奉月游。","空餘駕龙处，搖落鼎湖秋。"]', '诗', 'shi', '', NULL, '順宗至德大安孝皇帝挽歌三首 三 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14eb3310-7dd1-4406-bc53-3f826d431843', '昭德皇后挽歌詞', '昭德皇后挽歌词', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["淮水源流遠，塗山禮命升。","往年求故劒，今夕祔初陵。","鸞鏡金波澀，翬衣玉彩凝。","千年子孫慶，孝理在蒸蒸。"]', '["淮水源流远，塗山禮命升。","往年求故劒，今夕祔初陵。","鸾镜金波澀，翬衣玉彩凝。","千年子孫慶，孝理在蒸蒸。"]', '诗', 'shi', '', NULL, '昭德皇后挽歌詞 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6045bca2-8b33-4962-b50d-b6527e6ea24f', '大行皇太后挽歌詞三首 一', '大行皇太后挽歌词三首 一', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["筮水靈源濬，因山祔禮崇。","從龍開隧路，合璧向方中。","殿帳金根出，廞衣玉座空。","唯餘文母化，陰德滿公宮。"]', '["筮水靈源濬，因山祔禮崇。","從龙开隧路，合璧向方中。","殿帳金根出，廞衣玉座空。","唯餘文母化，陰德满公宮。"]', '诗', 'shi', '', NULL, '大行皇太后挽歌詞三首 一 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60b22d72-6e53-4812-99e7-cf7b8681c701', '大行皇太后挽歌詞三首 二', '大行皇太后挽歌词三首 二', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["配禮歸清廟，靈儀出直城。","九虞寧厚載，一惠易尊名。","曉漏銅壺澀，秋風羽翣輕。","容車攀望處，孺慕切皇情。"]', '["配禮归清廟，靈儀出直城。","九虞寧厚載，一惠易尊名。","晓漏銅壺澀，秋风羽翣轻。","容车攀望处，孺慕切皇情。"]', '诗', 'shi', '', NULL, '大行皇太后挽歌詞三首 二 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19f5fb5a-7849-4a74-8e78-e7c511faf04a', '大行皇太后挽歌詞三首 三', '大行皇太后挽歌词三首 三', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["哀笳出長信，寶劒入延津。","嗚咽宮車進，淒涼祠殿新。","青烏靈兆久，白燕瑞書頻。","從此山園夕，金波照玉塵。"]', '["哀笳出长信，寶劒入延津。","嗚咽宮车進，淒涼祠殿新。","青烏靈兆久，白燕瑞书頻。","從此山园夕，金波照玉塵。"]', '诗', 'shi', '', NULL, '大行皇太后挽歌詞三首 三 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9e01ea9-b222-43fb-a9e4-423a53eeb242', '惠昭皇太子挽歌詞二首 一', '惠昭皇太子挽歌词二首 一', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["前星落慶霄，薤露逐晨飆。","宮仗黃麾出，仙遊紫府遙。","空嗟鳳吹去，無復雞鳴朝。","今夜西園月，重輪更寂寥。"]', '["前星落慶霄，薤露逐晨飆。","宮仗黄麾出，仙游紫府遙。","空嗟鳳吹去，無复雞鳴朝。","今夜西园月，重輪更寂寥。"]', '诗', 'shi', '', NULL, '惠昭皇太子挽歌詞二首 一 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e351d228-3908-46e1-950d-5eb4de55f042', '惠昭皇太子挽歌詞二首 二', '惠昭皇太子挽歌词二首 二', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["東朝聞楚挽，羽翿依稀轉。","天歸京兆新，日與長安遠。","蘭芳落故殿，桂影銷空苑。","騎吹咽不前，風悲九旗卷。"]', '["东朝闻楚挽，羽翿依稀轉。","天归京兆新，日與长安远。","蘭芳落故殿，桂影銷空苑。","騎吹咽不前，风悲九旗卷。"]', '诗', 'shi', '', NULL, '惠昭皇太子挽歌詞二首 二 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0393c9a-703b-4c85-9a10-aea7b9aaeb21', '贈文敬太子挽歌詞二首 一', '贈文敬太子挽歌词二首 一', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["盤石公封重，瑤山贈禮尊。","歸全榮備物，樂善積深恩。","鴈沼寒波咽，鸞旌夕吹翻。","唯餘西靡樹，千古霸陵原。"]', '["盤石公封重，瑤山贈禮尊。","归全榮備物，乐善積深恩。","鴈沼寒波咽，鸾旌夕吹翻。","唯餘西靡樹，千古霸陵原。"]', '诗', 'shi', '', NULL, '贈文敬太子挽歌詞二首 一 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e391fb8-f3ae-46db-b83f-d00ddf5ea2a1', '贈文敬太子挽歌詞二首 二', '贈文敬太子挽歌词二首 二', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["銅壺曉漏初，羽翣擁塗車。","方外留鴻寶，人間得善書。","清笳悲畫綬，朱邸散長裾。","還似緱山駕，飄飄向碧虛。"]', '["銅壺晓漏初，羽翣擁塗车。","方外留鴻寶，人间得善书。","清笳悲畫綬，朱邸散长裾。","還似緱山駕，飄飄向碧虛。"]', '诗', 'shi', '', NULL, '贈文敬太子挽歌詞二首 二 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2932509-d3fd-4cea-aecd-68822661f74c', '贈鄭國莊穆公主挽歌二首 一', '贈鄭国莊穆公主挽歌二首 一', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["追飾崇湯沐，遺芳藹禁闈。","秋原森羽衛，夜壑掩容輝。","睿藻悲難盡，公宮望不歸。","笳簫向煙霧，疑是綵鸞飛。"]', '["追飾崇湯沐，遺芳藹禁闈。","秋原森羽衛，夜壑掩容輝。","睿藻悲难尽，公宮望不归。","笳簫向煙霧，疑是綵鸾飞。"]', '诗', 'shi', '', NULL, '贈鄭國莊穆公主挽歌二首 一 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d16672f0-646c-4ab1-95d6-4ae1e46fdf4f', '贈鄭國莊穆公主挽歌二首 二', '贈鄭国莊穆公主挽歌二首 二', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["舊館閉平陽，容車啓壽堂。","霜凝蕣英落，風度薤歌長。","淑德圖書在，皇慈禮命彰。","淒涼霸川曲，壟樹已成行。"]', '["旧館閉平陽，容车啓壽堂。","霜凝蕣英落，风度薤歌长。","淑德圖书在，皇慈禮命彰。","淒涼霸川曲，壟樹已成行。"]', '诗', 'shi', '', NULL, '贈鄭國莊穆公主挽歌二首 二 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23daec9c-1d95-4365-86c9-95f4cad539d8', '贈魏國憲穆公主挽歌詞二首 一', '贈魏国憲穆公主挽歌词二首 一', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["漢制榮車服，周詩美肅雍。","禮尊同姓主，恩錫大名封。","外館留圖史，陰堂閉德容。","睿詞悲薤露，千古仰芳蹤。"]', '["漢制榮车服，周诗美肅雍。","禮尊同姓主，恩錫大名封。","外館留圖史，陰堂閉德容。","睿词悲薤露，千古仰芳蹤。"]', '诗', 'shi', '', NULL, '贈魏國憲穆公主挽歌詞二首 一 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e68d3e1-3f45-411f-89dd-699d7d6e717c', '贈魏國憲穆公主挽歌詞二首 二', '贈魏国憲穆公主挽歌词二首 二', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["秦樓曉月殘，鹵簿列材官。","紅綬蘭桂歇，粉田風露寒。","凝笳悲駟馬，清鏡掩孤鸞。","愍冊徽音在，都人雪涕看。"]', '["秦楼晓月殘，鹵簿列材官。","紅綬蘭桂歇，粉田风露寒。","凝笳悲駟马，清镜掩孤鸾。","愍冊徽音在，都人雪涕看。"]', '诗', 'shi', '', NULL, '贈魏國憲穆公主挽歌詞二首 二 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e92e574c-8f1d-4b8b-9fb8-689c3be89ee1', '贈梁國惠康公主挽歌詞二首 一', '贈梁国惠康公主挽歌词二首 一', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["外館嬪儀貴，中參睿渥深。","初笄橫白玉，盛服鏤黃金。","風度簫聲遠，河低婺彩沈。","夜臺留冊諡，悽愴即徽音。"]', '["外館嬪儀貴，中參睿渥深。","初笄橫白玉，盛服鏤黄金。","风度簫声远，河低婺彩沈。","夜台留冊諡，悽愴即徽音。"]', '诗', 'shi', '', NULL, '贈梁國惠康公主挽歌詞二首 一 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0ffaa5d-7c3b-4cae-a04a-3c218eb5e990', '贈梁國惠康公主挽歌詞二首 二', '贈梁国惠康公主挽歌词二首 二', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["杳靄異湘川，飄颻駕紫煙。","鳳樓人已去，鸞鏡月空懸。","霧濕湯沐地，霜凝脂粉田。","音容無處所，應在玉皇前。"]', '["杳靄異湘川，飄颻駕紫煙。","鳳楼人已去，鸾镜月空懸。","霧濕湯沐地，霜凝脂粉田。","音容無处所，應在玉皇前。"]', '诗', 'shi', '', NULL, '贈梁國惠康公主挽歌詞二首 二 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11ae732b-6b28-4140-b7ab-d44d21b53561', '故太尉兼中書令贈太師西平王挽詞', '故太尉兼中书令贈太師西平王挽词', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["翊戴推元老，謀猷合大君。","河山封故地，金石表新墳。","劒履歸長夜，笳簫咽暮雲。","還經誓師處，薤露不堪聞。"]', '["翊戴推元老，謀猷合大君。","河山封故地，金石表新墳。","劒履归长夜，笳簫咽暮云。","還經誓師处，薤露不堪闻。"]', '诗', 'shi', '', NULL, '故太尉兼中書令贈太師西平王挽詞 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ed45e35-f04c-4ce2-838c-80fdc0e1f58e', '故司徒兼侍中贈太傅北平王挽詞', '故司徒兼侍中贈太傅北平王挽词', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["授律勳庸盛，居中鼎鼐和。","佐時調四氣，盡力淨三河。","忽訪天京兆，空傳漢伏波。","今朝麟閣上，偏軫聖情多。"]', '["授律勳庸盛，居中鼎鼐和。","佐时調四氣，尽力淨三河。","忽訪天京兆，空傳漢伏波。","今朝麟閣上，偏軫聖情多。"]', '诗', 'shi', '', NULL, '故司徒兼侍中贈太傅北平王挽詞 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c2e9bc9-e7a3-459b-8c90-e3aefae8d962', '奉和禮部尚書酬楊著作竹亭歌', '奉和禮部尚书酬楊著作竹亭歌', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["直城朱戶相邐連，九逵丹轂聲闐闐。","春官自有花源賞，終日南山當目前。","晨搖玉佩趨溫室，莫入竹溪疑洞天。","煙銷雨過看不足，晴翠鮮飆逗深谷。","獨謠一曲泛流霞，閑對千竿連淨綠。","縈迴疏鑿隨勝地，石磴巖扉光景異。","虛齋寂寂清籟唫，幽澗紛紛雜英墜。","家承麟趾貴，劒有龍泉賜。","上奉明時事無事，人間方外興偏多。","能以簪纓狎薜蘿，常通內學青蓮偈。","更奏新聲白雪歌，風入松，雲歸棟。","鴻飛滅處猶目送，蝶舞閑時夢忽成。","蘭臺有客敘交情，返照中林曳履聲。","直爲君恩催造膝，東方辨色謁承明。"]', '["直城朱戶相邐連，九逵丹轂声闐闐。","春官自有花源賞，終日南山當目前。","晨搖玉佩趨溫室，莫入竹溪疑洞天。","煙銷雨過看不足，晴翠鲜飆逗深谷。","独謠一曲泛流霞，闲对千竿連淨綠。","縈迴疏鑿隨勝地，石磴巖扉光景異。","虛斋寂寂清籟唫，幽澗紛紛杂英墜。","家承麟趾貴，劒有龙泉賜。","上奉明时事無事，人间方外兴偏多。","能以簪纓狎薜蘿，常通內学青蓮偈。","更奏新声白雪歌，风入松，云归棟。","鴻飞滅处猶目送，蝶舞闲时梦忽成。","蘭台有客敘交情，返照中林曳履声。","直爲君恩催造膝，东方辨色謁承明。"]', '诗', 'shi', '', NULL, '奉和禮部尚書酬楊著作竹亭歌 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0eabe0a2-cd14-4ced-97d2-bffd50579e26', '奉和張僕射朝天行', '奉和張僕射朝天行', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["元侯重寄貞師律，三郡四封今靜謐。","丹轂常思闕下來，紫泥忽自天中出。","軍裝喜氣倍趨程，千騎鳴珂入鳳城。","周王致理稱申甫，今日賢臣見明主。","拜恩稽首紛無已，凝旒前席皇情喜。","逢時自是山出雲，獻可還同石投水。","昔歲褒衣梁甫吟，當時已有致君心。","專城一鼓妖氛靜，擁斾十年天澤深。","日日披誠奉昌運，王人織路傳清問。","仙醞嘗分玉斝濃，御閑更輟金羈駿。","元正前殿朝君臣，一人負扆百福新。","宮懸綵仗儼然合，瑞氣爐煙相與春。","萬年枝上東風早，珮玉晨趨光景好。","塗山已見首諸侯，麟閣終當畫元老。","溫室沈沈漏刻移，退朝賓侶每相隨。","雄詞樂職波濤闊，曠度交歡雲霧披。","自古全才貴文武，懦夫只解冠章甫。","見公抽匣百鍊光，試欲磨鉛諒無助。"]', '["元侯重寄貞師律，三郡四封今静謐。","丹轂常思闕下来，紫泥忽自天中出。","軍裝喜氣倍趨程，千騎鳴珂入鳳城。","周王致理稱申甫，今日賢臣见明主。","拜恩稽首紛無已，凝旒前席皇情喜。","逢时自是山出云，獻可還同石投水。","昔歲褒衣梁甫吟，當时已有致君心。","專城一鼓妖氛静，擁斾十年天澤深。","日日披誠奉昌運，王人织路傳清问。","仙醞嘗分玉斝濃，御闲更輟金羈駿。","元正前殿朝君臣，一人負扆百福新。","宮懸綵仗儼然合，瑞氣爐煙相與春。","万年枝上东风早，珮玉晨趨光景好。","塗山已见首諸侯，麟閣終當畫元老。","溫室沈沈漏刻移，退朝賓侶每相隨。","雄词乐職波濤闊，曠度交歡云霧披。","自古全才貴文武，懦夫只解冠章甫。","见公抽匣百鍊光，試欲磨鉛諒無助。"]', '诗', 'shi', '', NULL, '奉和張僕射朝天行 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f07c915-4af5-406f-b475-1b66ed3d8a7d', '和李中丞慈恩寺清上人院牡丹花歌', '和李中丞慈恩寺清上人院牡丹花歌', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["澹蕩韶光三月中，牡丹偏自占春風。","時過寶地尋香徑，已見新花出故叢。","曲水亭西杏園北，濃芳深院紅霞色。","擢秀全勝珠樹林，結根幸在青蓮城。","豔蘂鮮房次第開，含煙洗露照蒼苔。","龐眉依杖禪僧起，輕翅縈枝舞蝶來。","獨坐南臺時共美，閑行古剎情何已。","花間一曲奏陽春，應爲芬芳比君子。"]', '["澹蕩韶光三月中，牡丹偏自占春风。","时過寶地尋香徑，已见新花出故叢。","曲水亭西杏园北，濃芳深院紅霞色。","擢秀全勝珠樹林，結根幸在青蓮城。","豔蘂鲜房次第开，含煙洗露照蒼苔。","龐眉依杖禪僧起，轻翅縈枝舞蝶来。","独坐南台时共美，闲行古剎情何已。","花间一曲奏陽春，應爲芬芳比君子。"]', '诗', 'shi', '', NULL, '和李中丞慈恩寺清上人院牡丹花歌 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c167a59-3964-4e06-ae49-d65cd16365f5', '錫杖歌送明楚上人歸佛川', '錫杖歌送明楚上人归佛川', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["上人遠自西天竺，頭陁行徧國朝寺。","口翻貝葉古字經，手持金策聲泠泠。","護法護身唯振錫，石瀨雲溪深寂寂。","乍來松徑風更寒，遙映霜天月成魄。","後夜空山禪誦時，寥寥挂在枯樹枝。","真法常傳心不住，東西南北隨緣路。","佛川此去何時迴，應真莫便遊天台。"]', '["上人远自西天竺，头陁行徧国朝寺。","口翻貝葉古字經，手持金策声泠泠。","護法護身唯振錫，石瀨云溪深寂寂。","乍来松徑风更寒，遙映霜天月成魄。","後夜空山禪誦时，寥寥挂在枯樹枝。","真法常傳心不住，东西南北隨緣路。","佛川此去何时迴，應真莫便游天台。"]', '诗', 'shi', '', NULL, '錫杖歌送明楚上人歸佛川 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c32b8dc-af32-4775-b167-6bfaa08fd799', '馬秀才草書歌', '马秀才草书歌', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["伯英草聖稱絕倫，後來學者無其人。","白眉年少未弱冠，落紙紛紛運纖腕。","初聞之子十歲餘，當時時輩皆不如。","猶輕昔日墨池學，未許前賢團扇書。","豔彩芳姿相點綴，水映荷花風轉蕙。","三春併向指下生，萬象爭分筆端勢。","有時當暑如清秋，滿堂風雨寒颼颼。","乍疑崩崖瀑水落，又見古木飢鼯愁。","變化縱橫出新意，眼看一字千金貴。","憶昔謝安問獻之，時人雖見那得知。"]', '["伯英草聖稱絕倫，後来学者無其人。","白眉年少未弱冠，落紙紛紛運纖腕。","初闻之子十歲餘，當时时輩皆不如。","猶轻昔日墨池学，未許前賢團扇书。","豔彩芳姿相点綴，水映荷花风轉蕙。","三春併向指下生，万象爭分笔端勢。","有时當暑如清秋，满堂风雨寒颼颼。","乍疑崩崖瀑水落，又见古木飢鼯愁。","变化縱橫出新意，眼看一字千金貴。","憶昔謝安问獻之，时人雖见那得知。"]', '诗', 'shi', '', NULL, '馬秀才草書歌 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50074313-0ec0-4b54-b73d-839bea9f1edd', '離合詩贈張監閣老', '離合诗贈張監閣老', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["黃葉從風散，暗嗟時節換。","忽見鬢邊霜，勿辭林下觴。","躬行君子道，身負芳名早。","帳殿漢官儀，巾車塞垣草。","交情劇斷金，文律每招尋。","始知蓬山下，如見古人心。"]', '["黄葉從风散，暗嗟时節換。","忽见鬢邊霜，勿辞林下觴。","躬行君子道，身負芳名早。","帳殿漢官儀，巾车塞垣草。","交情劇斷金，文律每招尋。","始知蓬山下，如见古人心。"]', '诗', 'shi', '', NULL, '離合詩贈張監閣老 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad3162f3-ffc3-48ff-9746-e4f19c0c1342', '春日雪酬潘孟陽迴文', '春日雪酬潘孟陽迴文', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["酒杯春醉好，飛雪晚庭閑。","久憶同前賞，中林對遠山。"]', '["酒杯春醉好，飞雪晚庭闲。","久憶同前賞，中林对远山。"]', '诗', 'shi', '', NULL, '春日雪酬潘孟陽迴文 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('387c52cf-4fa1-47ac-87a2-4fe2fc025e86', '五雜組', '五杂組', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["五雜組，旗亭客。","往復還，城南陌。","不得已，天涯謫。"]', '["五杂組，旗亭客。","往复還，城南陌。","不得已，天涯謫。"]', '诗', 'shi', '', NULL, '五雜組 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57788483-fa7b-4908-8315-878211693545', '數名詩', '數名诗', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["一區楊雄宅，恬然無所欲。","二頃季子田，歲晏常自足。","三端固爲累，事物反徽束。","四體苟不動，安得豐菽粟。","五侯誠暐曄，榮甚或爲辱。","六翮未鶱翔，虞羅乃相觸。","七人稱作者，杳杳有遐躅。","八桂挺奇姿，森森照初旭。","九歌傷澤畔，怨思徒刺促。","十翼有格言，幽貞謝浮俗。"]', '["一區楊雄宅，恬然無所欲。","二頃季子田，歲晏常自足。","三端固爲累，事物反徽束。","四體苟不动，安得豐菽粟。","五侯誠暐曄，榮甚或爲辱。","六翮未鶱翔，虞羅乃相觸。","七人稱作者，杳杳有遐躅。","八桂挺奇姿，森森照初旭。","九歌傷澤畔，怨思徒刺促。","十翼有格言，幽貞謝浮俗。"]', '诗', 'shi', '', NULL, '數名詩 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c81fa14-3388-49bf-af9d-f425ec3b522d', '星名詩', '星名诗', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["虛懷何所欲，歲晏聊懶逸。","雲翼謝翩翻，松心保貞實。","風秋景氣爽，葉落井逕出。","陶然美酒酣，所謂幽人吉。","自當輕尺璧，豈復埽一室。","安用簪進賢，少微斯可必。"]', '["虛懷何所欲，歲晏聊懶逸。","云翼謝翩翻，松心保貞實。","风秋景氣爽，葉落井逕出。","陶然美酒酣，所謂幽人吉。","自當轻尺璧，豈复埽一室。","安用簪進賢，少微斯可必。"]', '诗', 'shi', '', NULL, '星名詩 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d10dc89-51e6-415d-9389-cf5af5d71c73', '卦名詩', '卦名诗', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["節變忽驚春，臨風騁望頻。","支頤倦書幌，步履整山巾。","時鳥漸成曲，雜芳隨意新。","曙霞連觀闕，綺陌麗咸秦。","天地今交泰，雲雷背遘屯。","中孚諒可樂，書此示家人。"]', '["節变忽驚春，臨风騁望頻。","支頤倦书幌，步履整山巾。","时鸟漸成曲，杂芳隨意新。","曙霞連观闕，綺陌丽咸秦。","天地今交泰，云雷背遘屯。","中孚諒可乐，书此示家人。"]', '诗', 'shi', '', NULL, '卦名詩 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d3cc50a-68bc-482d-b911-171a8e667d1b', '藥名詩', '藥名诗', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["七澤蘭芳千里春，瀟湘花落石磷磷。","有時浪白微風起，坐釣藤陰不見人。"]', '["七澤蘭芳千里春，瀟湘花落石磷磷。","有时浪白微风起，坐釣藤陰不见人。"]', '诗', 'shi', '', NULL, '藥名詩 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45c3b8e3-0f3a-4f93-bc3e-6e6f9af38482', '古人名詩', '古人名诗', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["藩宣秉戎寄，衡石崇勢位。","年紀信不留，弛張良自愧。","樵蘇則爲愜，瓜李斯可畏。","不顧榮官尊，每陳豐畝利。","家林類巖巘，負郭躬斂積。","忌滿寵生嫌，養蒙恬勝智。","疎鐘皓月曉，晚景丹霞異。","澗谷永不諼，山梁冀無累。","頗符生肇學，得展禽尚志。","從此直不疑，支離疎世事。"]', '["藩宣秉戎寄，衡石崇勢位。","年紀信不留，弛張良自愧。","樵蘇則爲愜，瓜李斯可畏。","不顧榮官尊，每陳豐畝利。","家林類巖巘，負郭躬斂積。","忌满寵生嫌，養蒙恬勝智。","疎鐘皓月晓，晚景丹霞異。","澗谷永不諼，山梁冀無累。","頗符生肇学，得展禽尚志。","從此直不疑，支離疎世事。"]', '诗', 'shi', '', NULL, '古人名詩 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62230011-0a84-4370-8651-879a5a6ad72c', '州名詩寄道士', '州名诗寄道士', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["金蘭同道義，瓊簡復芝田。","平楚白雲合，幽崖丹桂連。","松峯明愛景，石竇納新泉。","冀永南山壽，歡隨萬福延。"]', '["金蘭同道義，瓊簡复芝田。","平楚白云合，幽崖丹桂連。","松峯明愛景，石竇納新泉。","冀永南山壽，歡隨万福延。"]', '诗', 'shi', '', NULL, '州名詩寄道士 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb9df600-b1c0-447e-ae8d-c6ac86e0d21e', '八音詩', '八音诗', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["金谷盛繁華，涼臺列簪組。","石崇留客醉，綠珠當座舞。","絲淚可銷骨，冶容竟何補。","竹林諒賢人，滿酌無所苦。","匏居容宴豆，儒室貴環堵。","土鼓與污尊，頤神則爲愈。","革道當在早，謙光斯可取。","木鴈才不才，吾知養生主。"]', '["金谷盛繁华，涼台列簪組。","石崇留客醉，綠珠當座舞。","絲泪可銷骨，冶容竟何補。","竹林諒賢人，满酌無所苦。","匏居容宴豆，儒室貴环堵。","土鼓與污尊，頤神則爲愈。","革道當在早，謙光斯可取。","木鴈才不才，吾知養生主。"]', '诗', 'shi', '', NULL, '八音詩 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb6982c8-4d92-4a8d-8b0c-dbe7b324219c', '建除詩', '建除诗', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["建節出王都，雄雄大丈夫。","除書加右職，騎吏擁前驅。","滿月張繁弱，含霜耀鹿盧。","平明躍騕褭，清夜擊珊瑚。","定遠功那比，平津策乃迂。","執心思報國，效節在忘軀。","破膽銷丹浦，顰蛾舞綠珠。","危冠徒自愛，長轂事應殊。","成績封千室，疇勞使五符。","收功輕驃衛，致埋邁黃虞。","開濟今如此，英威古不侔。","閉關草玄者，無乃誤爲儒。"]', '["建節出王都，雄雄大丈夫。","除书加右職，騎吏擁前驱。","满月張繁弱，含霜耀鹿盧。","平明躍騕褭，清夜擊珊瑚。","定远功那比，平津策乃迂。","執心思報国，效節在忘軀。","破膽銷丹浦，顰蛾舞綠珠。","危冠徒自愛，长轂事應殊。","成績封千室，疇勞使五符。","收功轻驃衛，致埋邁黄虞。","开濟今如此，英威古不侔。","閉关草玄者，無乃誤爲儒。"]', '诗', 'shi', '', NULL, '建除詩 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2818da83-b661-4ff4-83a1-838a53154938', '六府詩', '六府诗', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["金罍暎玉俎，賓友紛宴喜。","木蘭泛方塘，桂酒啓皓齒。","水榭臨空迥，酣歌當座起。","火雲散奇峯，瑤瑟韻清徴。","土梗乃虛論，康莊有逸軌。","穀成一編書，談笑佐天子。"]', '["金罍暎玉俎，賓友紛宴喜。","木蘭泛方塘，桂酒啓皓齒。","水榭臨空迥，酣歌當座起。","火云散奇峯，瑤瑟韻清徴。","土梗乃虛論，康莊有逸軌。","穀成一編书，談笑佐天子。"]', '诗', 'shi', '', NULL, '六府詩 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a1b83a6-a6fc-48bc-9dca-c1d62cf3fe5b', '三婦詩', '三婦诗', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["大婦刺繡文，中婦縫羅裙。","小婦無所作，嬌歌遏行雲。","丈人且安坐，金爐香正薰。"]', '["大婦刺繡文，中婦縫羅裙。","小婦無所作，嬌歌遏行云。","丈人且安坐，金爐香正薰。"]', '诗', 'shi', '', NULL, '三婦詩 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6492dd68-3e5a-4e0a-9d92-b2af592a5614', '安語', '安語', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["巖巖五岳鎮方輿，八極廓清氛祲除。","揮金得謝歸里閭，象牀角枕支體舒。"]', '["巖巖五岳鎮方輿，八極廓清氛祲除。","揮金得謝归里閭，象牀角枕支體舒。"]', '诗', 'shi', '', NULL, '安語 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6ac9590-2389-49a5-ace9-5c9e1adc6e6b', '危語', '危語', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["被病獨行逢乳虎，狂風駭浪失櫂櫓。","舉人看牓聞曉鼓，孱夫孽子遇妬母。"]', '["被病独行逢乳虎，狂风駭浪失櫂櫓。","舉人看牓闻晓鼓，孱夫孽子遇妬母。"]', '诗', 'shi', '', NULL, '危語 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('049fb798-fe8b-44c2-aebd-075a3ee695b9', '大言', '大言', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["華嵩爲佩河爲帶，南交北朔跬步內。","搏鵬作臘巨鼇鱠，伸舒軼出元氣外。"]', '["华嵩爲佩河爲带，南交北朔跬步內。","搏鵬作臘巨鼇鱠，伸舒軼出元氣外。"]', '诗', 'shi', '', NULL, '大言 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('397d50fd-79fc-4c11-94fb-237bceee7c30', '小言', '小言', '32c4947b-c3d0-4b66-82c4-441e77dcf87d', '唐', '["醯雞伺晨駕蚊翼，毫端棘刺分畛域。","蛛絲結搆聊蔭息，蟻垤崔嵬不可陟。"]', '["醯雞伺晨駕蚊翼，毫端棘刺分畛域。","蛛絲結搆聊蔭息，蟻垤崔嵬不可陟。"]', '诗', 'shi', '', NULL, '小言 權德舆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a451d5f-2d94-4fd7-92d1-335c153312bb', '雜詩五首 一', '杂诗五首 一', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["婉彼嬴氏女。","吹簫偶蕭史，綵鸞駕非煙。","綽約兩僊子，神期諒交感。","相顧乃如此，豈比成都人，琴心中夜起。"]', '["婉彼嬴氏女。","吹簫偶蕭史，綵鸾駕非煙。","綽約兩僊子，神期諒交感。","相顧乃如此，豈比成都人，琴心中夜起。"]', '诗', 'shi', '', NULL, '雜詩五首 一 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('353993d4-5c9a-422c-a899-dc92bbf6ee6e', '雜詩五首 二', '杂诗五首 二', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["陽臺巫山上，風雨忽清曠。","朝雲與遊龍，變化千萬狀。","魂交復目斷，縹緲難比況。","蘭澤不可親，凝清坐惆悵。"]', '["陽台巫山上，风雨忽清曠。","朝云與游龙，变化千万狀。","魂交复目斷，縹緲难比況。","蘭澤不可親，凝清坐惆悵。"]', '诗', 'shi', '', NULL, '雜詩五首 二 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b431ecf5-b7de-4aed-83d4-d9d58e1c8a77', '雜詩五首 三', '杂诗五首 三', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["淇水春正綠，上宮蘭葉齊。","光風兩搖蕩，鳴珮出中閨。","一顧授橫波，千金呈瓠犀。","徒然路傍子，怳怳復悽悽。"]', '["淇水春正綠，上宮蘭葉齊。","光风兩搖蕩，鳴珮出中閨。","一顧授橫波，千金呈瓠犀。","徒然路傍子，怳怳复悽悽。"]', '诗', 'shi', '', NULL, '雜詩五首 三 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7725dcec-cef1-4c84-95e7-57b2feaf2a19', '雜詩五首 四', '杂诗五首 四', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["碧樹泛鮮飆，玉琴含妙曲。","佳人掩鸞鏡，婉婉凝相矚。","文袿映束素，香黛宜𥊑綠。","寂寞遠懷春，何時來比目。"]', '["碧樹泛鲜飆，玉琴含妙曲。","佳人掩鸾镜，婉婉凝相矚。","文袿映束素，香黛宜𥊑綠。","寂寞远懷春，何时来比目。"]', '诗', 'shi', '', NULL, '雜詩五首 四 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39b28df8-a088-4c04-b5e6-d294e399a9bf', '雜詩五首 五', '杂诗五首 五', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["含顰倚瑤瑟，丹慊結繁慮。","失身不自還，萬恨隨玉筯。","蘼蕪山下路，團扇秋風去。","君看心斷時，猶在目成處。"]', '["含顰倚瑤瑟，丹慊結繁慮。","失身不自還，万恨隨玉筯。","蘼蕪山下路，團扇秋风去。","君看心斷时，猶在目成处。"]', '诗', 'shi', '', NULL, '雜詩五首 五 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3646f9c-437b-466f-ad4f-4d7782f7b1aa', '廣陵詩', '廣陵诗', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["廣陵實佳麗，隋季此爲京。","八方稱輻湊，五達如砥平。","大斾映空色，笳簫發連營。","層臺出重霄，金碧摩顥清。","交馳流水轂，迥接浮雲甍。","青樓旭日映，綠野春風晴。","噴玉光照地，顰蛾價傾城。","燈前互巧笑，陌上相逢迎。","飄飄翠羽薄，掩映紅襦明。","蘭麝遠不散，管弦閑自清。","曲士守文墨，達人隨性情。","茫茫竟同盡，冉冉將何營。","且申今日歡，莫務身後名。","肯學諸儒輩，書窗誤一生。"]', '["廣陵實佳丽，隋季此爲京。","八方稱輻湊，五達如砥平。","大斾映空色，笳簫發連營。","層台出重霄，金碧摩顥清。","交驰流水轂，迥接浮云甍。","青楼旭日映，綠野春风晴。","噴玉光照地，顰蛾價傾城。","灯前互巧笑，陌上相逢迎。","飄飄翠羽薄，掩映紅襦明。","蘭麝远不散，管弦闲自清。","曲士守文墨，達人隨性情。","茫茫竟同尽，冉冉將何營。","且申今日歡，莫務身後名。","肯学諸儒輩，书窗誤一生。"]', '诗', 'shi', '', NULL, '廣陵詩 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07ff181a-394f-41cf-9c16-f5e1489cd158', '古意', '古意', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["家人強進酒，酒後能忘情。","持杯未飲時，衆感紛已盈。","明月照我房，庭柯振秋聲。","空庭白露下，枕席涼風生。","所思萬里餘，水闊山縱橫。","佳期憑夢想，未曉愁雞鳴。","願將一心人，當年歡樂平。","長筵暎玉俎，素手彈秦箏。","𥊑睇呈巧笑，惠音激淒清。","此願良未果，永懷空如酲。"]', '["家人強進酒，酒後能忘情。","持杯未饮时，衆感紛已盈。","明月照我房，庭柯振秋声。","空庭白露下，枕席涼风生。","所思万里餘，水闊山縱橫。","佳期憑梦想，未晓愁雞鳴。","願將一心人，當年歡乐平。","长筵暎玉俎，素手彈秦箏。","𥊑睇呈巧笑，惠音激淒清。","此願良未果，永懷空如酲。"]', '诗', 'shi', '', NULL, '古意 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d38dd760-d139-43dc-b33d-7b6c60aeebbc', '雜言和常州李員外副使春日戲題十首 一', '杂言和常州李員外副使春日戲題十首 一', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["隨風柳絮輕，暎日杏花明。","無奈花深處，流鶯三數聲。"]', '["隨风柳絮轻，暎日杏花明。","無奈花深处，流鶯三數声。"]', '诗', 'shi', '', NULL, '雜言和常州李員外副使春日戲題十首 一 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84b01de8-94d9-4bee-be0d-f7f39422efdf', '雜言和常州李員外副使春日戲題十首 二', '杂言和常州李員外副使春日戲題十首 二', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["蘭橈畫舸轉花塘，水映風搖路漸香。","任興不知行近遠，更憐微月照鳴榔。"]', '["蘭橈畫舸轉花塘，水映风搖路漸香。","任兴不知行近远，更怜微月照鳴榔。"]', '诗', 'shi', '', NULL, '雜言和常州李員外副使春日戲題十首 二 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('759d69ef-add4-44fe-8c76-181ddaddab8e', '雜言和常州李員外副使春日戲題十首 三', '杂言和常州李員外副使春日戲題十首 三', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["簷前曉色驚雙燕，戶外春風舞百花。","粉署可憐閑對此，唯令碧玉泛流霞。"]', '["簷前晓色驚雙燕，戶外春风舞百花。","粉署可怜闲对此，唯令碧玉泛流霞。"]', '诗', 'shi', '', NULL, '雜言和常州李員外副使春日戲題十首 三 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5694049-628d-4422-a210-e2e5fdb30944', '雜言和常州李員外副使春日戲題十首 四', '杂言和常州李員外副使春日戲題十首 四', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["枕上覺，窗外曉。","怯朝光，驚曙鳥。","花墜露，滿芳沼。","柳如絲，風褭褭。","佳期遠，相見少。","試一望，魂杳渺。"]', '["枕上覺，窗外晓。","怯朝光，驚曙鸟。","花墜露，满芳沼。","柳如絲，风褭褭。","佳期远，相见少。","試一望，魂杳渺。"]', '诗', 'shi', '', NULL, '雜言和常州李員外副使春日戲題十首 四 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb21da51-d0c5-450f-89d4-af3956031dd9', '雜言和常州李員外副使春日戲題十首 五', '杂言和常州李員外副使春日戲題十首 五', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["閑庭無事，獨步春輝。","韶光滿目，落蘂盈衣。","芳樹交柯，文禽並飛。","婉彼君子，悵然有違。","對酒不飲，橫琴不揮。","不揮者何，知音誠稀。"]', '["闲庭無事，独步春輝。","韶光满目，落蘂盈衣。","芳樹交柯，文禽並飞。","婉彼君子，悵然有違。","对酒不饮，橫琴不揮。","不揮者何，知音誠稀。"]', '诗', 'shi', '', NULL, '雜言和常州李員外副使春日戲題十首 五 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a54b93e-97b3-4808-ad84-348971be16a4', '雜言和常州李員外副使春日戲題十首 六', '杂言和常州李員外副使春日戲題十首 六', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["江春好游衍，處處芳菲積。","綵舫入花津，香車依柳陌。","綠楊煙褭褭，紅蘂鶯寂寂。","如何愁思人，獨與風光隔。"]', '["江春好游衍，处处芳菲積。","綵舫入花津，香车依柳陌。","綠楊煙褭褭，紅蘂鶯寂寂。","如何愁思人，独與风光隔。"]', '诗', 'shi', '', NULL, '雜言和常州李員外副使春日戲題十首 六 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0f4b3ef-8353-40a7-a27c-37d03e0379ff', '雜言和常州李員外副使春日戲題十首 七', '杂言和常州李員外副使春日戲題十首 七', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["曙月漸到窗前，移尊更就芳筵。","輕吹乍搖蘭燭，春光暗入花鈿。","絲竹偏宜靜夜，綺羅共占韶年。","不遣通宵盡醉，定知辜負風煙。"]', '["曙月漸到窗前，移尊更就芳筵。","轻吹乍搖蘭燭，春光暗入花鈿。","絲竹偏宜静夜，綺羅共占韶年。","不遣通宵尽醉，定知辜負风煙。"]', '诗', 'shi', '', NULL, '雜言和常州李員外副使春日戲題十首 七 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8e885f3-6c75-49cd-b044-7e07b376e2ae', '雜言和常州李員外副使春日戲題十首 八', '杂言和常州李員外副使春日戲題十首 八', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["露洗百花新，簾開月照人。","綠窗銷暗燭，蘭逕埽清塵。","雙燕頻驚夢，三桃競報春。","相思寂不語，珠淚灑紅巾。"]', '["露洗百花新，簾开月照人。","綠窗銷暗燭，蘭逕埽清塵。","雙燕頻驚梦，三桃競報春。","相思寂不語，珠泪灑紅巾。"]', '诗', 'shi', '', NULL, '雜言和常州李員外副使春日戲題十首 八 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df746464-ff76-4402-a4b6-04bd238b3f1b', '雜言和常州李員外副使春日戲題十首 九', '杂言和常州李員外副使春日戲題十首 九', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["雨歇風輕一院香，紅芳綠草接東牆。","春衣試出當軒立，定被鄰家暗斷腸。"]', '["雨歇风轻一院香，紅芳綠草接东牆。","春衣試出當軒立，定被鄰家暗斷腸。"]', '诗', 'shi', '', NULL, '雜言和常州李員外副使春日戲題十首 九 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b393d92-dcd6-4f32-9aba-f472e8f39493', '雜言和常州李員外副使春日戲題十首 十', '杂言和常州李員外副使春日戲題十首 十', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["春風半，春光徧。","柳如絲，花似霰。","歸心勞夢寐，遠目傷遊眄。","可惜長安無限春，年年空向江南見。"]', '["春风半，春光徧。","柳如絲，花似霰。","归心勞梦寐，远目傷游眄。","可惜长安無限春，年年空向江南见。"]', '诗', 'shi', '', NULL, '雜言和常州李員外副使春日戲題十首 十 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0d628c7-f61a-41e7-8829-ce5c064aef8f', '相思曲', '相思曲', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["少小別潘郎，嬌羞倚畫堂。","有時裁尺素，無事約殘黃。","鵲語臨妝鏡，花飛落繡牀。","相思不解說，明月照空房。"]', '["少小別潘郎，嬌羞倚畫堂。","有时裁尺素，無事約殘黄。","鵲語臨妝镜，花飞落繡牀。","相思不解说，明月照空房。"]', '诗', 'shi', '', NULL, '相思曲 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc6626ba-c184-43f2-93ea-6f8bdc82a4de', '古樂府', '古乐府', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["風光澹蕩百花吐，樓上朝朝學歌舞。","身年二八壻侍中，幼妹承恩兄尚主。","綠窗珠箔繡鴛鴦，侍婢先焚百和香。","鶯啼日出不知曙，寂寂羅幃春夢長。"]', '["风光澹蕩百花吐，楼上朝朝学歌舞。","身年二八壻侍中，幼妹承恩兄尚主。","綠窗珠箔繡鴛鴦，侍婢先焚百和香。","鶯啼日出不知曙，寂寂羅幃春梦长。"]', '诗', 'shi', '', NULL, '古樂府 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97ec1e0e-4be0-4a22-94ac-763f30dce680', '渡江秋怨二首 一', '渡江秋怨二首 一', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["秋江平，秋月明，孤舟獨夜萬里情。","萬里情，相思遠，人不見兮淚滿眼。"]', '["秋江平，秋月明，孤舟独夜万里情。","万里情，相思远，人不见兮泪满眼。"]', '诗', 'shi', '', NULL, '渡江秋怨二首 一 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40a92675-3a77-4ce1-9242-17eb287a246a', '渡江秋怨二首 二', '渡江秋怨二首 二', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["渡秋江兮渺然，望秋月兮嬋娟。","色如練，萬里徧，我有所思兮不得見。","不得見兮露寒水深，耿遙夜兮傷心。"]', '["渡秋江兮渺然，望秋月兮嬋娟。","色如練，万里徧，我有所思兮不得见。","不得见兮露寒水深，耿遙夜兮傷心。"]', '诗', 'shi', '', NULL, '渡江秋怨二首 二 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('929b6afa-418f-416d-921e-bae39cc99039', '秋閨月', '秋閨月', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["三五二八月如練，海上天涯應共見。","不知何處玉樓前，乍入深閨玳瑁筵。","露濃香逕和愁坐，風動羅幃照獨眠。","初卷珠簾看不足，斜抱箜篌未成曲。","稍映妝臺臨綺窗，遙知不語淚雙雙。","此時愁望知何極，萬里秋天同一色。","靄靄遙分陌上光，迢迢對此閨中憶。","早晚歸來歡讌同，可憐歌吹月明中。","此夜不堪腸斷絕，願隨流影到遼東。"]', '["三五二八月如練，海上天涯應共见。","不知何处玉楼前，乍入深閨玳瑁筵。","露濃香逕和愁坐，风动羅幃照独眠。","初卷珠簾看不足，斜抱箜篌未成曲。","稍映妝台臨綺窗，遙知不語泪雙雙。","此时愁望知何極，万里秋天同一色。","靄靄遙分陌上光，迢迢对此閨中憶。","早晚归来歡讌同，可怜歌吹月明中。","此夜不堪腸斷絕，願隨流影到遼东。"]', '诗', 'shi', '', NULL, '秋閨月 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c92216ac-114d-4bda-9c55-89688840f5b0', '薄命篇', '薄命篇', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["昔住邯鄲年尚少，只是嬌羞弄花鳥。","青樓碧紗大道邊，綠楊日暮風褭褭。","嬋娟玉貌二八餘，自憐顏色花不如。","麗質全勝秦氏女，藁砧寧用專城居。","歲去年來年漸長，青春紅粉全堪賞。","玉樓珠箔但閑居，南陌東城詎來往。","韶光日日看漸遲，[摽]梅既落行有時。","寧知燕趙娉婷子，翻嫁幽幷游俠兒。","年年結束青絲騎，出門一去何時至。","秋月空懸翡翠簾，春幃嬾臥鴛鴦被。","沙塞經時不寄書，深閨愁獨意何如。","花前拭淚情無限，月下調琴恨有餘。","離別苦多相見少，洞房愁夢何由曉。","閑看雙燕淚霏霏，靜對空牀魂悄悄。","鏡裏紅顏不自禁，陌頭香騎動春心。","爲問佳期早晚是，人人總解有黃金。"]', '["昔住邯鄲年尚少，只是嬌羞弄花鸟。","青楼碧紗大道邊，綠楊日暮风褭褭。","嬋娟玉貌二八餘，自怜顏色花不如。","丽質全勝秦氏女，藁砧寧用專城居。","歲去年来年漸长，青春紅粉全堪賞。","玉楼珠箔但闲居，南陌东城詎来往。","韶光日日看漸遲，[摽]梅既落行有时。","寧知燕趙娉婷子，翻嫁幽幷游俠兒。","年年結束青絲騎，出门一去何时至。","秋月空懸翡翠簾，春幃嬾臥鴛鴦被。","沙塞經时不寄书，深閨愁独意何如。","花前拭泪情無限，月下調琴恨有餘。","離別苦多相见少，洞房愁梦何由晓。","闲看雙燕泪霏霏，静对空牀魂悄悄。","镜裏紅顏不自禁，陌头香騎动春心。","爲问佳期早晚是，人人總解有黄金。"]', '诗', 'shi', '', NULL, '薄命篇 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96df801d-b5cf-4652-a219-aecf5ecda465', '放歌行', '放歌行', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["夕陽不駐東流急，榮名貴在當年立。","青春虛度無所成，白首銜悲亦何及。","拂衣西笑出東山，君臣道合俄頃間。","一言一笑玉墀上，變化生涯如等閑。","朱門杳杳列華戟，座中皆是王侯客。","鳴環動珮暗珊珊，駿馬花驄白玉鞍。","十千斗酒不知貴，半醉留賓邀盡歡。","銀燭煌煌夜將久，侍婢金罍瀉春酒。","春酒盛來琥珀光，暗聞蘭麝幾般香。","乍看皓腕暎羅袖，微聽清歌發杏梁。","雙鬟美人君不見，一一皆勝趙飛燕。","迎杯乍舉石榴裙，勻粉時交合歡扇。","未央鐘漏醉中聞，聯騎朝天曙色分。","雙闕煙雲遙靄靄，五衢車馬亂紛紛。","罷朝鳴珮驟歸鞍，今日還同昨日歡。","歲歲年年恣遊讌，出門滿路光輝徧。","一身自樂何足言，九族爲榮真可羨。","男兒稱意須及時，閉門下帷人不知。","年光看逐轉蓬盡，徒詠東山招隱詩。"]', '["夕陽不駐东流急，榮名貴在當年立。","青春虛度無所成，白首銜悲亦何及。","拂衣西笑出东山，君臣道合俄頃间。","一言一笑玉墀上，变化生涯如等闲。","朱门杳杳列华戟，座中皆是王侯客。","鳴环动珮暗珊珊，駿马花驄白玉鞍。","十千斗酒不知貴，半醉留賓邀尽歡。","銀燭煌煌夜將久，侍婢金罍瀉春酒。","春酒盛来琥珀光，暗闻蘭麝幾般香。","乍看皓腕暎羅袖，微听清歌發杏梁。","雙鬟美人君不见，一一皆勝趙飞燕。","迎杯乍舉石榴裙，勻粉时交合歡扇。","未央鐘漏醉中闻，聯騎朝天曙色分。","雙闕煙云遙靄靄，五衢车马亂紛紛。","罷朝鳴珮驟归鞍，今日還同昨日歡。","歲歲年年恣游讌，出门满路光輝徧。","一身自乐何足言，九族爲榮真可羨。","男兒稱意須及时，閉门下帷人不知。","年光看逐轉蓬尽，徒詠东山招隐诗。"]', '诗', 'shi', '', NULL, '放歌行 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1318e5a7-c894-4bb0-a1aa-f5760e0b7f63', '旅館雪晴又覩新月衆興所感因成雜言', '旅館雪晴又覩新月衆兴所感因成杂言', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["寥寥深夜雪初晴，樓上雲開月漸明。","池中片影依稀見，簾外清光遠近生。","皎皎晴空疑破鏡，廣庭積素偏相映。","珠簾卷却光更深，玉指持來色逾淨。","夢覺青樓最可憐，嬋娟素魄滿寒天。","天地寥寥同一色，秦淮楚江無限極。","歸鴻斷猨何處聲，深閨旅館遙相憶。","長安五侯華閣開，嘉賓列坐傾金罍。","賞明月，翫流雪，纖手蛾眉座中設。","清歌一聲無斷絕，夜已央，樂未闌。","狐裘獸炭不知寒，珠環翠珮聲珊珊。","履舃紛紜桂袖攢，朱顏倚醉盡君歡。","人生少年全不久，相看且勸杯中酒。","丈夫富貴自有期，映雪讀書徒白首。"]', '["寥寥深夜雪初晴，楼上云开月漸明。","池中片影依稀见，簾外清光远近生。","皎皎晴空疑破镜，廣庭積素偏相映。","珠簾卷却光更深，玉指持来色逾淨。","梦覺青楼最可怜，嬋娟素魄满寒天。","天地寥寥同一色，秦淮楚江無限極。","归鴻斷猨何处声，深閨旅館遙相憶。","长安五侯华閣开，嘉賓列坐傾金罍。","賞明月，翫流雪，纖手蛾眉座中設。","清歌一声無斷絕，夜已央，乐未闌。","狐裘獸炭不知寒，珠环翠珮声珊珊。","履舃紛紜桂袖攢，朱顏倚醉尽君歡。","人生少年全不久，相看且勸杯中酒。","丈夫富貴自有期，映雪读书徒白首。"]', '诗', 'shi', '', NULL, '旅館雪晴又覩新月衆興所感因成雜言 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2a9c971-c055-47e8-94ba-ab163742f747', '玉臺體十二首 一', '玉台體十二首 一', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["鶯啼蘭已紅，見出鳳城東。","粉汗宜斜日，衣香逐上風。","情來不自覺，暗駐五花驄。"]', '["鶯啼蘭已紅，见出鳳城东。","粉汗宜斜日，衣香逐上风。","情来不自覺，暗駐五花驄。"]', '诗', 'shi', '', NULL, '玉臺體十二首 一 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('421ac769-e695-4a94-be7a-d49497838f29', '玉臺體十二首 二', '玉台體十二首 二', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["嬋娟二八正嬌羞，日暮相逢南陌頭。","試問佳期不肯道，落花深處指青樓。"]', '["嬋娟二八正嬌羞，日暮相逢南陌头。","試问佳期不肯道，落花深处指青楼。"]', '诗', 'shi', '', NULL, '玉臺體十二首 二 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b011a41b-ac9c-4452-b2a1-95c3adffa701', '玉臺體十二首 三', '玉台體十二首 三', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["隱映羅衫薄，輕盈玉腕圓。","相逢不肯語，微笑畫屏前。"]', '["隐映羅衫薄，轻盈玉腕圓。","相逢不肯語，微笑畫屏前。"]', '诗', 'shi', '', NULL, '玉臺體十二首 三 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('152d1b43-181b-4e0d-b726-ed75fb11a25e', '玉臺體十二首 四', '玉台體十二首 四', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["知向遼東去，由來幾許愁。","破顏君莫怪，嬌小不禁羞。"]', '["知向遼东去，由来幾許愁。","破顏君莫怪，嬌小不禁羞。"]', '诗', 'shi', '', NULL, '玉臺體十二首 四 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db250770-5759-41e1-9058-45e4fbad7074', '玉臺體十二首 五', '玉台體十二首 五', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["樓上吹簫罷，閨中刺繡闌。","佳期不可見，盡日淚潺潺。"]', '["楼上吹簫罷，閨中刺繡闌。","佳期不可见，尽日泪潺潺。"]', '诗', 'shi', '', NULL, '玉臺體十二首 五 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0e11d93-4d60-46f0-ab86-1b2ca8e35f9a', '玉臺體十二首 六', '玉台體十二首 六', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["淚盡珊瑚枕，魂銷玳瑁牀。","羅衣不忍著，羞見繡鴛鴦。"]', '["泪尽珊瑚枕，魂銷玳瑁牀。","羅衣不忍著，羞见繡鴛鴦。"]', '诗', 'shi', '', NULL, '玉臺體十二首 六 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14653c00-b703-4beb-8d90-acfce2cd7c0c', '玉臺體十二首 七', '玉台體十二首 七', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["君去期花時，花時君不至。","簷前雙燕飛，落妾相思淚。"]', '["君去期花时，花时君不至。","簷前雙燕飞，落妾相思泪。"]', '诗', 'shi', '', NULL, '玉臺體十二首 七 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c63932c0-3d5f-4037-96db-428334fd5aa4', '玉臺體十二首 八', '玉台體十二首 八', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["空閨滅燭後，羅幌獨眠時。","淚盡腸欲斷，心知人不知。"]', '["空閨滅燭後，羅幌独眠时。","泪尽腸欲斷，心知人不知。"]', '诗', 'shi', '', NULL, '玉臺體十二首 八 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8858d3ff-7e41-486a-a236-3c419457ccd1', '玉臺體十二首 九', '玉台體十二首 九', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["秋風一夜至，吹盡後庭花。","莫作經時別，西鄰是宋家。"]', '["秋风一夜至，吹尽後庭花。","莫作經时別，西鄰是宋家。"]', '诗', 'shi', '', NULL, '玉臺體十二首 九 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b35c026-dbc7-4363-8301-5646e8d02adb', '玉臺體十二首 十', '玉台體十二首 十', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["獨自披衣坐，更深月露寒。","隔簾腸欲斷，爭敢下堦看。"]', '["独自披衣坐，更深月露寒。","隔簾腸欲斷，爭敢下堦看。"]', '诗', 'shi', '', NULL, '玉臺體十二首 十 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a5070c8-8b6a-46d3-a976-ce942baf42e7', '玉臺體十二首 十一', '玉台體十二首 十一', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["昨夜裙帶解，今朝蟢子飛。","鉛華不可棄，莫是藁砧歸。"]', '["昨夜裙带解，今朝蟢子飞。","鉛华不可棄，莫是藁砧归。"]', '诗', 'shi', '', NULL, '玉臺體十二首 十一 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46209cfd-b11b-49df-9623-856528a36167', '玉臺體十二首 十二', '玉台體十二首 十二', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["萬里行人至，深閨夜未眠。","雙眉燈下埽，不待鏡臺前。"]', '["万里行人至，深閨夜未眠。","雙眉灯下埽，不待镜台前。"]', '诗', 'shi', '', NULL, '玉臺體十二首 十二 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8832732-e7a8-4813-becc-9832af2db960', '贈友人', '贈友人', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["知向巫山逢日暮，輕袿玉佩暫淹留。","曉隨雲雨歸何處，還是襄王夢覺愁。"]', '["知向巫山逢日暮，轻袿玉佩暫淹留。","晓隨云雨归何处，還是襄王梦覺愁。"]', '诗', 'shi', '', NULL, '贈友人 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f49465c-1669-4b74-bb9b-f3afa519f9d7', '舟行見月', '舟行见月', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["月入孤舟夜半晴，寥寥霜鴈兩三聲。","洞房燭影在何處，欲寄相思夢不成。"]', '["月入孤舟夜半晴，寥寥霜鴈兩三声。","洞房燭影在何处，欲寄相思梦不成。"]', '诗', 'shi', '', NULL, '舟行見月 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a74e140c-b177-40df-94df-601bfc2d3fcf', '雜興五首 一', '杂兴五首 一', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["叢鬢愁眉時勢新，初笄絕代北方人。","一顰一笑千金重，肯似成都夜失身。"]', '["叢鬢愁眉时勢新，初笄絕代北方人。","一顰一笑千金重，肯似成都夜失身。"]', '诗', 'shi', '', NULL, '雜興五首 一 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9979b18b-741e-456b-9da8-cf7397cb9df3', '雜興五首 二', '杂兴五首 二', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["乍聽絲聲似竹聲，又疑丹穴九雛驚。","金波露洗淨於晝，寂寞不堪深夜情。"]', '["乍听絲声似竹声，又疑丹穴九雛驚。","金波露洗淨於晝，寂寞不堪深夜情。"]', '诗', 'shi', '', NULL, '雜興五首 二 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('758a74cd-9966-4572-8fb3-6ed51823893c', '雜興五首 三', '杂兴五首 三', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["琥珀尊開月暎簾，調弦理曲指纖纖。","含羞斂態勸君住，更奏新聲刮骨鹽。"]', '["琥珀尊开月暎簾，調弦理曲指纖纖。","含羞斂態勸君住，更奏新声刮骨鹽。"]', '诗', 'shi', '', NULL, '雜興五首 三 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd802c06-6d8f-4322-800b-0001fa2b8266', '雜興五首 四', '杂兴五首 四', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["乳燕雙飛鶯亂啼，百花如繡照深閨。","新妝對鏡知無比，微笑時時出瓠犀。"]', '["乳燕雙飞鶯亂啼，百花如繡照深閨。","新妝对镜知無比，微笑时时出瓠犀。"]', '诗', 'shi', '', NULL, '雜興五首 四 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61ba3837-99d5-42c5-88de-3840dbba8e40', '雜興五首 五', '杂兴五首 五', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["巫山雲雨洛川神，珠襻香腰穩稱身。","惆悵妝成君不見，含情起立問傍人。"]', '["巫山云雨洛川神，珠襻香腰穩稱身。","惆悵妝成君不见，含情起立问傍人。"]', '诗', 'shi', '', NULL, '雜興五首 五 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65930a39-b7b6-4708-9f8a-8cdc22f59f86', '秖役江西路上以詩代書寄內', '秖役江西路上以诗代书寄內', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["辛苦事行役，風波倦晨暮。","搖搖結遐心，靡靡即長路。","別來如昨日，每見缺蟾兔。","潮信催客帆，春光變江樹。","宦遊豈云愜，歸夢無復數。","愧非超曠姿，循此跼促步。","笑言思暇日，規勸多遠度。","鶉服我久安，荆釵君所慕。","伊予多昧理，初不涉世務。","適因擁腫材，成此懶慢趣。","一身常抱病，不復理章句。","胸中無町畦，與物且多忤。","既非大川檝，則守南山霧。","胡爲出處間，徒使名利污。","羈孤望予祿，孩穉待我餔。","未能即忘懷，恨恨以此故。","終當稅鞿鞅，豈待畢婚娶。","如何久人寰，俛仰學舉措。","衡茅去迢遰，水陸兩馳騖。","晰晰窺曉星，塗塗踐朝露。","靜聞田鶴起，遠見沙𩾨聚。","怪石不易躋，急湍那可泝。","漁商聞遠岸，煙火明古渡。","下碇夜已深，上碕波不駐。","畏途信非一，離念紛難具。","枕席有餘清，壺觴無與晤。","南方出蘭桂，歸日自分付。","北窗留琴書，無乃委童孺。","春江足魚鴈，彼此勤尺素。","早晚到中閨，怡然兩相顧。"]', '["辛苦事行役，风波倦晨暮。","搖搖結遐心，靡靡即长路。","別来如昨日，每见缺蟾兔。","潮信催客帆，春光变江樹。","宦游豈云愜，归梦無复數。","愧非超曠姿，循此跼促步。","笑言思暇日，規勸多远度。","鶉服我久安，荆釵君所慕。","伊予多昧理，初不涉世務。","適因擁腫材，成此懶慢趣。","一身常抱病，不复理章句。","胸中無町畦，與物且多忤。","既非大川檝，則守南山霧。","胡爲出处间，徒使名利污。","羈孤望予祿，孩穉待我餔。","未能即忘懷，恨恨以此故。","終當稅鞿鞅，豈待畢婚娶。","如何久人寰，俛仰学舉措。","衡茅去迢遰，水陸兩驰騖。","晰晰窺晓星，塗塗踐朝露。","静闻田鹤起，远见沙𩾨聚。","怪石不易躋，急湍那可泝。","漁商闻远岸，煙火明古渡。","下碇夜已深，上碕波不駐。","畏途信非一，離念紛难具。","枕席有餘清，壺觴無與晤。","南方出蘭桂，归日自分付。","北窗留琴书，無乃委童孺。","春江足鱼鴈，彼此勤尺素。","早晚到中閨，怡然兩相顧。"]', '诗', 'shi', '', NULL, '秖役江西路上以詩代書寄內 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa241c43-0b5c-4f97-a416-7c2536ee0484', '夜泊有懷', '夜泊有懷', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["棲鳥向前林，暝色生寒蕪。","孤舟去不息，衆感非一途。","川程方浩淼，離思方鬱紆。","轉枕眼未熟，擁衾淚已濡。","窘然風水上，寢食疲朝晡。","心想洞房夜，知君還向隅。"]', '["棲鸟向前林，暝色生寒蕪。","孤舟去不息，衆感非一途。","川程方浩淼，離思方鬱紆。","轉枕眼未熟，擁衾泪已濡。","窘然风水上，寢食疲朝晡。","心想洞房夜，知君還向隅。"]', '诗', 'shi', '', NULL, '夜泊有懷 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e4a66fe-fc87-4169-885f-7f68c69995a2', '自桐廬如蘭溪有寄', '自桐廬如蘭溪有寄', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["東南江路舊知名，惆悵春深又獨行。","新婦山頭雲半斂，女兒灘上月初明。","風前蕩颺雙飛蝶，花裏間關百囀鶯。","滿目歸心何處說，欹眠搔首不勝情。"]', '["东南江路旧知名，惆悵春深又独行。","新婦山头云半斂，女兒灘上月初明。","风前蕩颺雙飞蝶，花裏间关百囀鶯。","满目归心何处说，欹眠搔首不勝情。"]', '诗', 'shi', '', NULL, '自桐廬如蘭溪有寄 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0a7081a-75d2-4f2f-b7d3-d648bc546eed', '相思樹', '相思樹', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["家寄江東遠，身對江西春。","空見相思樹，不見相思人。"]', '["家寄江东远，身对江西春。","空见相思樹，不见相思人。"]', '诗', 'shi', '', NULL, '相思樹 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e12a0e13-71b5-419e-bf17-2af3e1e306f2', '石楠樹', '石楠樹', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["石楠紅葉透簾春，憶得妝成下錦茵。","試折一枝含萬恨，分明說向夢中人。"]', '["石楠紅葉透簾春，憶得妝成下錦茵。","試折一枝含万恨，分明说向梦中人。"]', '诗', 'shi', '', NULL, '石楠樹 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd5d1e99-7301-464e-a788-8e09419e449a', '斗子灘', '斗子灘', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["斗子灘頭夜已深，月華偏照此時心。","春江風水連天闊，歸夢悠揚何處尋。"]', '["斗子灘头夜已深，月华偏照此时心。","春江风水連天闊，归梦悠揚何处尋。"]', '诗', 'shi', '', NULL, '斗子灘 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('017c7ff5-d04b-4340-98c9-3ba532bd1913', '黃蘗館', '黄蘗館', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["驅車振楫越山川，候曉通宵冒煙雨。","青楓浦上魂已銷，黃蘗館前心自苦。"]', '["驱车振楫越山川，候晓通宵冒煙雨。","青楓浦上魂已銷，黄蘗館前心自苦。"]', '诗', 'shi', '', NULL, '黃蘗館 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a935cce-b030-4527-a3cc-d6cf9899924a', '清明日次弋陽', '清明日次弋陽', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["自歎清明在遠鄉，桐花覆水葛溪長。","家人定是持新火，點作孤燈照洞房。"]', '["自歎清明在远乡，桐花覆水葛溪长。","家人定是持新火，点作孤灯照洞房。"]', '诗', 'shi', '', NULL, '清明日次弋陽 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae06c8aa-677c-41ba-b360-ed8a1f19b2cd', '中書夜直寄贈', '中书夜直寄贈', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["通籍在金閨，懷君百慮迷。","迢迢五夜永，脈脈兩心齊。","步履疲青瑣，開緘倦紫泥。","不堪風雨夜，轉枕憶鴻妻。"]', '["通籍在金閨，懷君百慮迷。","迢迢五夜永，脈脈兩心齊。","步履疲青瑣，开緘倦紫泥。","不堪风雨夜，轉枕憶鴻妻。"]', '诗', 'shi', '', NULL, '中書夜直寄贈 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acd61a32-e143-43da-b1d9-61cec3178c73', '病中寓直代書題寄', '病中寓直代书題寄', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["愚夫何所任，多病感君深。","自謂青春壯，寧知白髮侵。","寢興勞善祝，疎懶愧良箴。","寂寞聞宮漏，那堪直夜心。"]', '["愚夫何所任，多病感君深。","自謂青春壯，寧知白髮侵。","寢兴勞善祝，疎懶愧良箴。","寂寞闻宮漏，那堪直夜心。"]', '诗', 'shi', '', NULL, '病中寓直代書題寄 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('830c5d4c-c70e-4b88-837a-f25efc71be2b', '端午日禮部宿齋有衣服綵結之貺以詩還荅', '端午日禮部宿斋有衣服綵結之貺以诗還荅', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["良辰當五日，偕老祝千年。","綵縷同心麗，輕裾暎體鮮。","寂寥齋畫省，欵曲擘香牋。","更想傳觴處，孫孩徧目前。"]', '["良辰當五日，偕老祝千年。","綵縷同心丽，轻裾暎體鲜。","寂寥斋畫省，欵曲擘香牋。","更想傳觴处，孫孩徧目前。"]', '诗', 'shi', '', NULL, '端午日禮部宿齋有衣服綵結之貺以詩還荅 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2612953-e483-4f76-9872-00a4270ce131', '酬九日', '酬九日', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["重九共遊娛，秋光景氣殊。","他時頭似雪，還對插茱萸。"]', '["重九共游娛，秋光景氣殊。","他时头似雪，還对插茱萸。"]', '诗', 'shi', '', NULL, '酬九日 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1b25f99-305c-4c53-b02e-d1644c528e0f', '和九日從楊氏姊遊', '和九日從楊氏姊游', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["秋光風露天，令節慶初筵。","易象家人吉，閨門女士賢。","招邀菊酒會，屬和柳花篇。","今日同心賞，全勝落帽年。"]', '["秋光风露天，令節慶初筵。","易象家人吉，閨门女士賢。","招邀菊酒會，屬和柳花篇。","今日同心賞，全勝落帽年。"]', '诗', 'shi', '', NULL, '和九日從楊氏姊遊 權德輿 shi');
